INSERT OR REPLACE INTO posts (id, content, author_name, author_handle, likes_count, reposts_count, created_at, category, has_media, anime_meta, game_id) VALUES ('4e8cbf1a-3c4d-4609-86af-3ba1a728fd57', 'Theory of Shitting - William Shakespolearm

1. To think is to shit.
2. I shit therefore i am.
3. To shit or no-shit.

If a man thinks about shitting but never shits, has he truly thought? what is in the mind of a man who are shitting?

