INSERT OR REPLACE INTO profiles (id, name, handle, headline, bio, avatar_url, banner_url, location, status_message, currently_building, tech_stack, social_links, contact_email, contact_details, contact_note, updated_at, created_at, theme) VALUES ('default', 'Kur Zagin 𒀭𒆳𒍝𒆳', '@kurzagin', 'System architect, solo developer, and builder of strange but useful things.', 'I design products where software, knowledge systems, AI, and immersive interfaces overlap.

My work usually begins with a small irritation:
> “Why is this still difficult?”

Then I build the tool I wish already existed.', 'https://cdn.kurzagin.com/profiles/avatars/a2eb810f-b308-483a-9d48-139bdc69b3ca.avif', 'https://cdn.kurzagin.com/profiles/banners/13ac970f-733e-4ed6-8252-3c253d5ce146.avif', '35.6614° N, 139.6681° E', 'building tools I wish already existed', '[{"url":"https://github.com/vxnus-studio/siduri-x","badge":"Active","title":"siduri","description":"An AI companion and knowledge layer designed to understand applications without becoming tightly coupled to them"}]', '["TypeScript","JavaScript","Python","Rust","Next.js","React","Astro","PostgreSQL","AI workflows","System architecture"]', '[{"url":"https://kurzagin.com","label":"kurzagin.com","platform":"Website"},{"url":"https://vxnus.xyz","label":"vxnus.xyz","platform":"VXNUS Studio"},{"url":"https://github.com/kurzagin","label":"@kurzagin","platform":"GitHub"},{"url":"https://x.com/kurzagin","label":"@kurzagin","platform":"X"},{"url":"https://github.com/vxnus-studio","label":"@vxnus-studio","platform":"VXNUS GitHub"}]', 'venus@krzgn.xyz', '[{"link":"mailto:venus@krzgn.xyz","value":"venus@krzgn.xyz","method":"Email"},{"link":"https://github.com/vxnus-studio","value":"vxnus-studio","method":"GitHub Discussions"},{"link":"https://x.com/kurzagin","value":"@kurzagin on X","method":"Direct Message"}]', 'Ideas, feedback, technical conversations, and unusual collaborations are welcome ✨', '2026-10-22T23:44:51.862Z', '2026-10-03T15:50:22.755Z', 'default');

