INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('44ee604c-b56a-44d7-9f85-6ad37b4bb31b', 112301, 'The Misfit of Demon King Academy: History’s Strongest Demon King Reincarnates and Goes to School with His Descendants', 'Maou Gakuin no Futekigousha: Shijou Saikyou no Maou no Shiso, Tensei shite Shison-tachi no Gakkou e Kayou', '魔王学院の不適合者 ～史上最強の魔王の始祖、転生して子孫たちの学校へ通う～', 'https://cdn.kurzagin.com/anime/covers/112301.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/112301-e50SRjhGDGUu.jpg', 'TV', 'completed', 13, 13, 8, '["Action","Comedy","Fantasy"]', 'SILVER LINK.', 2020, 'Anos, the Demon King of Tyranny, has defeated humans, spirits, and gods alike. But even demon kings get tired of all the fighting sometimes! Hoping for a more peaceful life, Anos decides to reincarnate himself. When he wakes two thousand years later, though, he finds the world has become too peaceful--his descendants have grown weak and magic is in serious decline. Intending to reclaim his rightful place, he enrolls in Demon King Academy, where he finds that his magical power is off the charts. Literally. And because they can''t measure his power, the faculty and other students regard Anos as a misfit. With the support of Misha, the one student he manages to befriend, the misfit (Demon King) begins his climb up the demon ranks!

(Source: Square Enix)', '2026-10-05T05:07:35.100Z', '2026-10-05T05:07:35.100Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('83d9a2a4-6a65-4205-b073-b582bcb748b3', 130588, 'The Misfit of Demon King Academy Ⅱ: History''s Strongest Demon King Reincarnates and Goes to School with His Descendants', 'Maou Gakuin no Futekigousha: Shijou Saikyou no Maou no Shiso, Tensei shite Shison-tachi no Gakkou e Kayou II', '魔王学院の不適合者 ～史上最強の魔王の始祖、転生して子孫たちの学校へ通う～ Ⅱ', 'https://cdn.kurzagin.com/anime/covers/130588.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/130588-TVZlsARgfLfm.jpg', 'TV', 'completed', 12, 12, 5, '["Action","Fantasy"]', 'SILVER LINK.', 2023, 'As peace returns to the demon realm, Anos Voldigoad wishes nothing more than to put his reputation as the Demon King of Tyranny to rest and go back to being a misfit at the prestigious Demon King Academy. Unfortunately, any tranquility is fleeting: sinister demons, kings, and deities plot Anos''s demise from the shadows.

Rumors spread about the "Child of God," a being whose power may rival that of Anos. To uncover the truth and eliminate the potential threat, Anos must journey deep into the land of spirits. However, the spirit world is shrouded in mystery, and it may only be entered after undergoing a series of difficult trials.

With unrivaled power and confidence, Anos braces himself to defeat various formidable enemies with grandiose titles. But he—with the assistance of his trusted allies—will barely have to break a sweat as the true Demon King of Tyranny.

(Source: MAL Rewrite)', '2026-10-05T05:08:12.039Z', '2026-10-05T05:08:12.039Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('788a8c17-5591-439a-aa87-22b8747c2e2f', 130590, 'The Misfit of Demon King Academy II (Cour 2)', 'Maou Gakuin no Futekigousha: Shijou Saikyou no Maou no Shiso, Tensei shite Shison-tachi no Gakkou e Kayou II Part 2', '魔王学院の不適合者 ～史上最強の魔王の始祖、転生して子孫たちの学校へ通う～ Ⅱ 2クール', 'https://cdn.kurzagin.com/anime/covers/130590.avif', NULL, 'TV', 'completed', 12, 12, 6, '["Action","Fantasy"]', 'SILVER LINK.', 2024, 'The academy''s lessons are back in session with Anos Voldigoad fighting more powerful enemies!
(Source: Crunchyroll)', '2026-10-05T05:08:42.269Z', '2026-10-05T05:08:42.269Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('3290d20e-7883-418a-8eeb-608f708dfa52', 130003, 'BOCCHI THE ROCK!', 'Bocchi the Rock!', 'ぼっち・ざ・ろっく！', 'https://cdn.kurzagin.com/anime/covers/130003.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/130003-5F90a7BtsPQN.jpg', 'TV', 'completed', 12, 12, 10, '["Comedy","Music","Slice of Life"]', 'CloverWorks', 2022, 'Hitori Gotou, “Bocchi-chan,” is a girl who’s so introverted and shy around people that she’d always start her conversations with “Ah...”

During her middle school years, she started playing the guitar, wanting to join a band because she thought it could be an opportunity for even someone shy like her to also shine. But because she had no friends, she ended up practicing guitar for six hours every day all by herself. After becoming a skilled guitar player, she uploaded videos of herself playing the guitar to the internet under the name “Guitar Hero” and fantasized about performing at her school’s cultural festival concert. But not only could she not find any bandmates, before she knew it, she was in high school and still wasn’t able to make a single friend!

She was really close to becoming a shut-in, but one day, Nijika Ijichi, the drummer in Kessoku Band, reached out to her. And because of that, her everyday life started to change little by little...

(Source: Crunchyroll)', '2026-10-05T08:46:56.078Z', '2026-10-05T08:46:56.078Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('a496931b-62fc-49dc-84b2-0c7679aefe9f', 186712, 'Bocchi the Rock! 2nd Season', 'Bocchi the Rock! 2nd Season', 'ぼっち・ざ・ろっく！ 2期', 'https://cdn.kurzagin.com/anime/covers/186712.avif', NULL, 'TV', 'planning', 0, NULL, NULL, '["Comedy","Music","Slice of Life"]', 'CloverWorks', NULL, 'We will Be back！

The second season of Bocchi the Rock!

(Source: Official BTR Twitter)', '2026-10-05T08:47:45.135Z', '2026-10-05T08:47:45.135Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('41888cc1-eb9a-4c6a-9fc7-61eaf3018f0e', 14833, 'Maoyu: Archenemy & Hero', 'Maoyuu Maou Yuusha', 'まおゆう魔王勇者', 'https://cdn.kurzagin.com/anime/covers/14833.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/14833.jpg', 'TV', 'completed', 12, 12, 7, '["Adventure","Fantasy","Romance"]', 'ARMS', 2013, 'After a long and treacherous journey, our Hero finally arrives at the Dark Lady''s castle only to find himself being asked for help. The Hero explains how the war that the demons have brought upon the humans have killed thousands and put more in misery. The queen of demons however argues that this war has made the human society band together as one and showed empirical evidence how it has increased population, increased production, boosted economy and improved society overall. Furthermore, she explains to the Hero that ending this war will result in a civil war that will produce more bloodshed than there ever was. The Hero, convinced that the only way to bring peace, relatively speaking, is to join forces with the Dark Lady, agrees to help with her plans!
', '2026-10-05T08:49:35.225Z', '2026-10-05T08:49:35.225Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('4c842c04-0adf-48b5-997d-e00b1a6eb987', 140457, 'I''m Quitting Heroing', 'Yuusha, Yamemasu', '勇者、辞めます', 'https://cdn.kurzagin.com/anime/covers/140457.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/140457-2VXKaTEWOlOP.jpg', 'TV', 'completed', 12, 12, 7, '["Action","Adventure","Comedy","Fantasy"]', 'EMT Squared', 2022, 'After saving humanity from the despicable Demon King, Leo Demonhart does not earn a hero’s standing. Instead, he is regarded with suspicion and hostility by those he fought to protect. Treated as a pariah with nowhere else to turn, exiled Leo seeks a position in the army of his former nemesis! But the army is not what it once was before its defeat at Leo’s hands, so to maintain his new position, Leo must whip the forces back into fighting shape.

(Source: Sentai Filmworks)', '2026-10-05T08:50:07.870Z', '2026-10-05T08:50:07.870Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('242d00b2-92c1-4eba-87a6-e27663641e18', 101168, 'Plunderer', 'Plunderer', 'プランダラ', 'https://cdn.kurzagin.com/anime/covers/101168.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/101168-55dmHGtGlJOY.jpg', 'TV', 'completed', 24, 24, 8, '["Action","Adventure","Comedy","Drama","Ecchi","Fantasy","Romance"]', 'GEEKTOYS', 2020, 'Every human inhabiting the world of Alcia is branded by a “Count” or a number written on their body. Depending on how each person lives their life, this Count either goes up or down. For Hina’s mother, her total drops to 0 and she’s pulled into the Abyss, never to be seen again. But her mother’s last words send Hina on a quest to find a legendary hero from the Waste War—the fabled Ace!

(Source: Funimation)', '2026-10-05T08:50:50.926Z', '2026-10-05T08:50:50.926Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('ec0043cf-f85b-4d0e-97d0-c6f80e4f1c87', 20447, 'Noragami', 'Noragami', 'ノラガミ', 'https://cdn.kurzagin.com/anime/covers/20447.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20447-nlgQQzcgWbgw.jpg', 'TV', 'completed', 12, 12, 7, '["Action","Adventure","Comedy","Supernatural"]', 'bones', 2014, 'Minor god Yato is down on his luck. Fed up with his slacker lifestyle, his partner abruptly quits. He has no money, no worshippers, and no shrine to call home. But just when things are starting to seem hopeless, a bus accident forces him to cross paths with Hiyori Iki, a sweet and perky high school girl. After the accident, Hiyori''s soul has a bad habit of slipping out of her body, and after enlisting Yato''s help to get her back to normal, she begins to fall into the world of spirits and gods.

But Hiyori''s not the only one who''s keeping tabs on Yato. A god from Yato''s past is back, and he''s not interested in a friendly reunion.

(Source: Funimation)', '2026-10-05T08:51:10.845Z', '2026-10-05T08:51:10.845Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('382ecaf4-5580-432f-acc1-9503245197a0', 15051, 'Love Live! School Idol Project', 'Love Live! School idol project', 'ラブライブ! School idol project', 'https://cdn.kurzagin.com/anime/covers/15051.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/15051-fkMle8Yxuxjo.jpg', 'TV', 'completed', 13, 13, 8, '["Music","Slice of Life"]', 'Sunrise', 2013, 'Otonokizaka High School stands on the border of three cities: Akihabara&mdash;a pop culture mecca that''s evolving by the minute; Kanda&mdash;a conservative, cultured city where history and tradition reign supreme; and Jinbo&mdash;a quiet area reserved for a more mature, sophisticated population. Amidst this culture clash, the school now faces closure due to the enrollment of fewer and fewer students.
With the school planning to close within three years, nine female students come together with one thing in mind&mdash;form a pop idol group to revive the school''s popularity and keep it from shutting down. "In order to protect our beloved school, there''s only one thing we can do... become pop stars!"
Their goal is simple: Become an overnight sensation and use their nationwide media exposure to promote their school and bring in a wave of new students to the ailing area. A simple but solid plan, they figure. Naturally, they''re nervous and wonder if this plan can really succeed, but for better or worse their new journey has begun...
"All we can ask for is just a tiny bit of support from you. We truly believe that with your help, we can change the world around us. We will make our dreams come true!"
(Source: NIS America)', '2026-10-07T03:08:03.096Z', '2026-10-07T03:08:03.096Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('397f99da-6678-422e-86e6-cba816f6f38f', 14741, 'Love, Chunibyo & Other Delusions', 'Chuunibyou demo Koi ga Shitai!', '中二病でも恋がしたい!', 'https://cdn.kurzagin.com/anime/covers/14741.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/14741-7RMdUd7tVfSu.jpg', 'TV', 'completed', 12, 12, 9, '["Comedy","Drama","Romance","Slice of Life"]', 'Kyoto Animation', 2012, 'Everybody has had that stage in their life where they have thought themselves to be special, different from the masses of ordinary humans. They might go as far as seeing themselves capable of wielding mystical powers, or maybe even believe themselves to have descended from a fantasy realm. This "disease" is known as "chuunibyou" and is often the source of some of the most embarrassing moments of a person''s life.

For Yuuta Togashi, the scars that his chuunibyou has left behind are still fresh. Having posed as the "Dark Flame Master" during his middle school years, he looks back at those times with extreme embarrassment, so much so that he decides to attend a high school far away where nobody will recognize him. Putting his dark history behind him, he longs to live a normal high school life.

Unfortunately, he hasn''t escaped his past yet: enter Rikka Takanashi, Yuuta''s new classmate and self-declared vessel of the "Wicked Eye." As this eccentric young girl crashes into Yuuta''s life, his dream of an ordinary, chuunibyou-free life quickly crumbles away. In this hilarious and heartwarming story of a boy who just wants to leave his embarrassing memories behind, the delusions of old are far from a thing of the past.

(Source: MAL Rewrite)', '2026-10-07T03:08:41.951Z', '2026-10-07T03:08:41.951Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('adfb0791-a347-4338-836e-a56a1d677d52', 21699, 'KONOSUBA -God''s blessing on this wonderful world! 2', 'Kono Subarashii Sekai ni Shukufuku wo! 2', 'この素晴らしい世界に祝福を！2', 'https://cdn.kurzagin.com/anime/covers/21699.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21699-1PwL1P4i61wP.jpg', 'TV', 'completed', 10, 10, 9, '["Adventure","Comedy","Ecchi","Fantasy"]', 'Studio DEEN', 2017, 'When Kazuma Satou died, he was given two choices: pass on to heaven or be revived in a fantasy world. After choosing the new world, the goddess Aqua tasked him with defeating the Demon King, and let him choose any weapon to aid him. Unfortunately, Kazuma chose to bring Aqua herself and has regretted the decision ever since then.

Not only is he stuck with a useless deity turned party archpriest, the pair also has to make enough money for living expenses. To add to their problems, their group continued to grow as more problematic adventurers joined their ranks. Their token spellcaster, Megumin, is an explosion magic specialist who can only cast one spell once per day and refuses to learn anything else. There is also their stalwart crusader, Lalatina "Darkness" Dustiness Ford, a helpless masochist who makes Kazuma look pure in comparison.

Kono Subarashii Sekai ni Shukufuku wo! 2 continues to follow Kazuma and the rest of his party through countless more adventures as they struggle to earn money and have to deal with one another''s problematic personalities. However, things rarely go as planned, and they are often sidetracked by their own idiotic tendencies.
', '2026-10-07T03:18:03.279Z', '2026-10-07T03:18:03.279Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('de6595c2-6e5c-4c92-8862-b592add51790', 102976, 'KONOSUBA -God''s blessing on this wonderful world!- Legend of Crimson', 'Kono Subarashii Sekai ni Shukufuku wo! Kurenai Densetsu', 'この素晴らしい世界に祝福を！紅伝説', 'https://cdn.kurzagin.com/anime/covers/102976.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/102976-xv7fCzBwQ7GU.jpg', 'MOVIE', 'completed', 1, 1, 9, '["Action","Adventure","Comedy","Ecchi","Fantasy","Supernatural"]', 'J.C.STAFF', 2019, 'A video game-loving shut-in, Satou Kazuma''s life should''ve ended when he was hit by a truck, but through a twist of fate, he ends up reincarnating in another world--and dragging the troublemaking goddess, Aqua, the wildly dorky mage, Megumin, and the unrelentingly delusional lady knight, Darkness, with him.

Now, the Crimson Demon village that Megumin and Yunyun are from is facing a threat that could mean its ending. Kazuma and his gang follow Yunyun, who returns to the Crimson Demon village intent on saving it... when they are faced with their greatest threat yet! What will become of the unremarkable adventurer Kazuma''s life in another world?!

(Source: Crunchyroll)', '2026-10-07T03:19:02.883Z', '2026-10-07T03:19:02.883Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('ac59a3af-6fa8-44cc-b334-45c1acd44bc3', 136804, 'KONOSUBA -God''s blessing on this wonderful world! 3', 'Kono Subarashii Sekai ni Shukufuku wo! 3', 'この素晴らしい世界に祝福を！３', 'https://cdn.kurzagin.com/anime/covers/136804.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/136804-yHC8D64UTiRA.jpg', 'TV', 'completed', 11, 11, 9, '["Action","Adventure","Comedy","Ecchi","Fantasy"]', 'Drive', 2024, 'The dysfunctional party is back, but they may be short a member soon ’cause Kazuma is over it. Disillusioned with adventure, he wants to become a monk, but Aqua, Megumin, and Darkness call bull. However, the career dispute gets put on hold when a princess requests to hear all about their tales. Will the taste of fame at the royal castle keep them together or will this mark their farewell tour?

(Source: Crunchyroll)', '2026-10-07T03:19:40.948Z', '2026-10-07T03:19:40.948Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('7a8acace-56d2-4116-b844-925eb41810e3', 99750, 'I Want to Eat Your Pancreas', 'Kimi no Suizou wo Tabetai', '君の膵臓をたべたい', 'https://cdn.kurzagin.com/anime/covers/99750.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/99750-KPFW2Jv03b2B.jpg', 'MOVIE', 'completed', 1, 1, 7, '["Drama","Romance","Slice of Life"]', 'Studio VOLN', 2018, 'Spring time in April and the last of the cherry blossoms are still in bloom. The usually aloof bookworm with no interest in others comes across a book in a hospital waiting room. Handwritten on the cover are the words: "Living with Dying." He soon discovers that it is a diary kept by his very popular and genuinely cheerful classmate, Sakura Yamauchi, who reveals to him that she is secretly suffering from a pancreatic illness and only has a limited time left. It is at this moment that she gains just one more person to share her secret.

Trying to maintain a normal life as much as possible, Sakura is determined to live her life to the fullest until the very last day. As her free spirit and unpredictable actions throw him for a loop, his heart begins to gradually change.

(Source: Aniplex USA)', '2026-10-05T09:32:04.143Z', '2026-10-05T09:32:04.143Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('8823311e-f37d-4f39-860b-9b99613d2113', 20997, 'Charlotte', 'Charlotte', 'Charlotte(シャーロット)', 'https://cdn.kurzagin.com/anime/covers/20997.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20997-nE9VyUa08vS0.jpg', 'TV', 'completed', 13, 13, 8, '["Comedy","Drama","Romance","Sci-Fi","Supernatural"]', 'P.A.WORKS', 2015, 'The story centers around the special abilities that occur among a small percentage of boys and girls in puberty. Yuu Otosaka uses his power without others knowing, and lives a fairly normal, average school life. Before him suddenly appears a girl, Nao Tomori. Due to his meeting with her, the fate of special power-users will be exposed.

(Source: Anime News Network)', '2026-10-05T09:33:32.096Z', '2026-10-05T09:33:32.096Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('8309a5eb-854c-4340-a647-778c794de0de', 165530, 'The Fated Magical Princess: Who Made Me a Princess', 'Mofa Gongzhu De Xiao Fannao', '魔法公主的小烦恼', 'https://cdn.kurzagin.com/anime/covers/165530.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/165530-i4Wdldb0zmBf.jpg', 'ONA', 'planning', 0, 16, NULL, '["Comedy","Fantasy","Romance"]', 'Colored Pencil Animation', NULL, 'Athanasia de Alger Obelia, the only legitimate princess of the Obelian Empire, awakens memories of a previous life; from these, she sees a future where she dies at the hands of her father, Emperor Claude. While his gaze is full of affection for Athanasia''s older sister, Jennette Margarita, he only regards Athanasia with indifference and leaves her desperately yearning for his love.

To avert the fate that awaits her, the infant Athanasia resolves to escape the palace when she is older and, in the meantime, avoid meeting her father at all costs. However, their paths cross years before it was destined, and so young Athanasia finds herself at the mercy of Claude''s seemingly mercurial whims. But the one emotion that she expects, apathy, is never present on his face. With a father who now considers her family, Athanasia strives to grow into a proper crown princess—but her grim vision may yet have ways to become true.

(Source: MAL Rewrite)', '2026-10-05T09:34:23.297Z', '2026-10-05T09:34:23.297Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('f4c36c8a-ece5-4aef-ba44-5a41fd7a9cc6', 126213, 'Banished from the Hero’s Party, I Decided to Live a Quiet Life in the Countryside', 'Shin no Nakama ja Nai to Yuusha no Party wo Oidasareta node, Henkyou de Slow Life suru Koto ni shimashita', '真の仲間じゃないと勇者のパーティーを追い出されたので、辺境でスローライフすることにしました', 'https://cdn.kurzagin.com/anime/covers/126213.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/126213-1nOONZyGeIfR.jpg', 'TV', 'completed', 13, 13, 9, '["Action","Adventure","Fantasy","Romance","Slice of Life"]', 'WolfsBane', 2021, 'A heroic and mighty adventurer dreams of...opening a pharmacy?

Red was once a part of the Hero’s party, a group destined to save the world by fighting the Raging Demon Lord. But after being betrayed by his comrade, Red hopes to start anew by opening a small apothecary in a sleepy town on the frontier. While keeping his past life a secret is the goal, it won’t be easy...especially when a beautiful adventurer from his past asks to move in.

(Source: Funimation)', '2026-10-05T09:35:52.963Z', '2026-10-05T09:35:52.963Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('92bcfc10-e98b-4273-9849-6c288f75e356', 156131, 'Banished from the Hero’s Party, I Decided to Live a Quiet Life in the Countryside Season 2', 'Shin no Nakama ja Nai to Yuusha no Party wo Oidasareta node, Henkyou de Slow Life suru Koto ni shimashita 2nd', '真の仲間じゃないと勇者のパーティーを追い出されたので、辺境でスローライフすることにしました 2nd', 'https://cdn.kurzagin.com/anime/covers/156131.avif', NULL, 'TV', 'completed', 12, 12, 8, '["Action","Adventure","Fantasy","Romance","Slice of Life"]', 'Studio Flad', 2024, 'A once-great Hero is now living the slow life. Red, shunned from his adventuring party, spends his days running an apothecary. He lives with his lifelong love, Princess Rit, and his sister, Ruti. They indulge in moments of bliss, like soaking in serene hot springs and enjoying delicious meals with a view. No matter what happens to the world around them, these happy moments will be unchanged.

(Source: Crunchyroll)', '2026-10-05T09:36:11.849Z', '2026-10-05T09:36:11.849Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('1c8e8478-fd4b-476d-b265-f8731fe01c60', 97994, 'BLEND-S', 'Blend S', 'ブレンド・S', 'https://cdn.kurzagin.com/anime/covers/97994.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/97994-3JZ05K3Idjco.jpg', 'TV', 'completed', 12, 12, 9, '["Comedy","Slice of Life"]', 'A-1 Pictures', 2017, 'The story centers on a girl named Maika who gets a job at a cafe where all the waitresses are given certain attributes — such as "tsundere" or "little sister" — to embody while serving customers. The manager asks Maika to be the "Do S" (extreme sadist) waitress, so she will have to adopt a dominant and aggressive persona.

(Source: Anime News Network)', '2026-10-05T09:36:30.544Z', '2026-10-05T09:36:30.544Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('6a4e3d9e-fd7d-41f0-a2c2-e61a4852778d', 21306, 'Myriad Colors Phantom World', 'Musaigen no Phantom World', '無彩限のファントム・ワールド', 'https://cdn.kurzagin.com/anime/covers/21306.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21306-xIkqRnZd1xV9.jpg', 'TV', 'completed', 13, 13, 8, '["Action","Ecchi","Slice of Life","Supernatural"]', 'Kyoto Animation', 2016, 'The story takes place in the near future, in a world born of human imagination. What humans would call ghosts or monsters appear, and they come to be called "phantoms". The main character, Haruhiko Ichijo, is a first year at Hosea Academy along with his upperclassman Mai Kawakami, who fights phantoms with the ability "Spirit of Five Elements", Izumi Reina, who has the ability "Phantom Eater", and Koito Minase, who fights phantoms in solitude. They experience the ups and downs of high school life before a certain incident leads them to the truth of this world.

(Source: Anime News Network)', '2026-10-07T03:29:46.136Z', '2026-10-07T03:29:46.136Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('93f0c738-68c7-4c1e-b05f-96c6aa53d8ef', 206401, 'FX Fighter Kurumi-chan', 'FX Senshi Kurumi-chan', 'FX戦士くるみちゃん', 'https://cdn.kurzagin.com/anime/covers/206401.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/206401-Nsf3QKwKxDra.jpg', 'TV', 'planning', 0, 12, NULL, '["Drama","Slice of Life"]', 'Passione', 2026, 'University student Kurumi Fukuga has finally fulfilled her long-held desire of starting foreign exchange (FX) trading, motivated by recouping the 20 million yen her late mother lost in trading. "I''ll easily make it back," she thought, but the world she enters can become heaven or hell in an instant. Unrealized losses, loss-cutting, unstoppable fluctuations… but she still wants to buy, sell and make money! With fellow FX addicts Mochiko, Mebuki and Yasuko along for the ride, the market heats up! Joy, despair, joy, despair — this is an endearing, yet slightly risky money game. Can Kurumi and her friends survive this turbulent world?

(Source: Crunchyroll)', '2026-10-09T11:27:24.003Z', '2026-10-09T11:27:24.003Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('e667d05c-9986-42bc-a25c-1539b2415898', 130298, 'The Eminence in Shadow', 'Kage no Jitsuryokusha ni Naritakute!', '陰の実力者になりたくて！', 'https://cdn.kurzagin.com/anime/covers/130298.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/130298-9yxFlFvKMwRk.jpg', 'TV', 'completed', 20, 20, 9, '["Action","Comedy","Fantasy"]', 'Nexus', 2022, 'Some people just aren’t suited to playing the part of the flashy, in-your-face hero or the dastardly, mustache-twirling villain with larger-than-life panache. Instead, they operate in the shadows and pull the strings of society through wit and cleverness. That’s the role Cid wants to play when he’s transported to another world. Cid spins a yarn or three and becomes the unlikely leader of the underground Shadow Garden organization that fights against a menacing cult (which he totally made up). However, there’s a catch even his wild imagination didn’t see coming: the cult he concocted actually exists, and they’re beyond displeased that his power fantasy just got in the way of their evil plans!

(Source: HIDIVE)', '2026-10-05T09:37:00.664Z', '2026-10-05T09:37:00.664Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('a0229959-35b9-40fe-af99-8029414562dc', 161964, 'The Eminence in Shadow Season 2', 'Kage no Jitsuryokusha ni Naritakute! 2nd season', '陰の実力者になりたくて！ 2nd season', 'https://cdn.kurzagin.com/anime/covers/161964.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/161964-a3MIPlFGpwbo.jpg', 'TV', 'completed', 12, 12, 9, '["Action","Comedy","Fantasy"]', 'Nexus', 2023, 'Everything has been going according to plan, but the hour of awakening draws near. Cid Kagenou and Shadow Garden investigate the Lawless City, a cesspool where the red moon hangs low in the sky and three powerful monarchs rule the streets. The true draw for Cid, however, is one who can draw blood–the Blood Queen, a vampire who has slumbered in her coffin for eons. Her awakening approaches, and Cid could finally face a day of reckoning. 

(Source: HIDIVE, edited)

Note: A world premiere screening of Episode 1 was shown in the The Eminence in Shadow 2nd Season panel at Anime Expo on July 1, 2023.', '2026-10-05T09:37:27.076Z', '2026-10-05T09:37:27.076Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('f451ca7e-71c5-49f8-990d-96d80b5bd868', 130166, 'In the Land of Leadale', 'Leadale no Daichi nite', 'リアデイルの大地にて', 'https://cdn.kurzagin.com/anime/covers/130166.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/130166-VfxhkKvXFppG.jpg', 'TV', 'completed', 12, 12, 8, '["Adventure","Fantasy"]', 'Maho Film', 2022, 'After being put on life support after a tragic accident, Keina Kagami''s only freedom comes from the VRMMO RPG Leadale. One day her life support system shuts off and Keina passes away. When she wakes up, she finds herself in Leadale two hundred years in the future. As the high elf Cayna, with lost skills but incredible stats, she must forge relationships with the residents of this new world... which, shockingly, include the ""children"" characters she designed herself! A leisurely adventure tale is about to begin, featuring a girl transported to a game world and the smiles and tears she shares with her quirky companions!

(Source: Crunchyroll)', '2026-10-05T09:38:36.990Z', '2026-10-05T09:38:36.990Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('0a400fb5-b5e5-4a21-b837-f3923155ffc5', 144553, 'The Reincarnation of the Strongest Exorcist in Another World', 'Saikyou Onmyouji no Isekai Tenseiki', '最強陰陽師の異世界転生記', 'https://cdn.kurzagin.com/anime/covers/144553.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/144553-V8iUimFSq5mO.jpg', 'TV', 'completed', 13, 13, 8, '["Action","Adventure","Fantasy","Romance","Supernatural"]', 'Studio Blanc', 2023, 'You can''t be happy if you''re just strong, even if you''re the strongest exorcist in the world. Exorcist Haruyoshi Kuga, called an unrivaled genius, is betrayed by the Imperial Court and about to die. Resolving to be happy in his next life, he uses a secret reincarnation technique he created and reincarnates in another world. And so he receives a new name, Seika, and a new life.

"What I lacked in my previous life was cunning. In this life, I''ll be more calculating and find happiness." With the strongest exorcist techniques and strong demons working with him, what lies ahead for him? The peaceful life he wants, or.... This is the start of a story no one''s ever seen before: the story of the strongest exorcist in a fantasy world.

(Source: Crunchyroll)', '2026-10-05T09:41:00.566Z', '2026-10-05T09:41:00.566Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('0e80a9f5-74ec-4092-9bb0-2a8882d0bc0a', 142193, 'Reborn to Master the Blade: From Hero-King to Extraordinary Squire', 'Eiyuu-ou, Bu wo Kiwameru Tame Tenseisu: Soshite, Sekai Saikyou no Minarai Kishi♀', '英雄王、武を極めるため転生す ～そして、世界最強の見習い騎士♀～', 'https://cdn.kurzagin.com/anime/covers/142193.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/142193-3WgRXoxGfTAl.jpg', 'TV', 'completed', 12, 12, 7, '["Action","Adventure","Comedy","Fantasy"]', 'Studio Comet', 2023, 'After living a life devoted to serving his country and people, Inglis’ one wish to be free of a king’s burden and to train was actually heard, but as a beautiful girl! Reborn in the far future as a daughter to renowned knights, Inglis can now focus on mastering the martial arts. A wish has been granted, and Inglis will be on the front lines fulfilling the dream of becoming the strongest knight.

(Source: Crunchyroll)', '2026-10-05T09:42:26.094Z', '2026-10-05T09:42:26.094Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('d102ae09-fafc-4b4b-b320-2d66ab85f06d', 119056, 'She Professed Herself Pupil of the Wise Man', 'Kenja no Deshi wo Nanoru Kenja', '賢者の弟子を名乗る賢者', 'https://cdn.kurzagin.com/anime/covers/119056.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/119056-B0nJPm5afUYD.jpg', 'TV', 'completed', 12, 12, 8, '["Adventure","Fantasy"]', 'studio A-CAT', 2022, 'Kagami Sakimori plays as the great mage Danblf in his favorite MMO. He falls asleep after a night of testing new character appearances, but instead of waking up to a suspended game, he’s inside of Arch Earth Online—as a girl! Now named Mira, he must convince the game’s people that Mira is a pupil of Danblf, who vanished without a trace 30 years ago…and figure out how he got here.

(Source: Funimation)', '2026-10-05T09:43:17.230Z', '2026-10-05T09:43:17.230Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('a2939196-c71d-4bc6-b94e-e1935f3ce95d', 135865, 'Saga of Tanya the Evil Season 2', 'Youjo Senki II', '幼女戦記Ⅱ', 'https://cdn.kurzagin.com/anime/covers/135865.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/135865-Ws3e7BhBkFxd.jpg', 'TV', 'planning', 0, 12, NULL, '["Action","Fantasy"]', 'NUT', 2026, 'The second season of Youjo Senki.', '2026-10-04T11:58:48.344Z', '2026-10-04T11:58:48.344Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('84e7544c-6bf5-4d10-b6b4-ac534c156da9', 104252, 'Demon Lord, Retry!', 'Maou-sama, Retry!', '魔王様、リトライ!', 'https://cdn.kurzagin.com/anime/covers/104252.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/104252-qeVvmiAPExqQ.jpg', 'TV', 'completed', 12, 12, 7, '["Action","Adventure","Comedy","Fantasy"]', 'EKACHI EPILKA', 2019, 'The story centers on Akira Ono, a regular guy who works at a company that manages an online game. He often plays the game as his character "Maou" (Dark Lord). But one day, when he logs on, he is whisked into the game''s fantasy world as his character. There, he meets a one-legged girl, and begins his adventures alongside her. But as he is a powerful "Dark Lord," various nations and holy maidens journey to defeat him, and he stirs up trouble everywhere he goes.

(Source: Anime News Network)', '2026-10-05T09:43:51.571Z', '2026-10-05T09:43:51.571Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('5d9fad14-3684-45cd-a5b8-e2b6140dd26f', 159042, 'Reincarnated as a Sword Season 2', 'Tensei Shitara Ken Deshita 2nd Season', '転生したら剣でした 第2期', 'https://cdn.kurzagin.com/anime/covers/159042.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/159042-X0mqyaUFBkms.jpg', 'ONA', 'watching', 1, 12, 8, '["Action","Adventure","Fantasy"]', 'C2C', 2026, 'The second season of Tensei Shitara Ken Deshita.
Note: Each episode was streamed one week in advance of the TV broadcast starting on October 1, 2026 on Abema. Regular broadcasting began on October 8, 2026.', '2026-10-04T00:10:13.411Z', '2026-10-07T05:50:03.401Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('ad1d9898-05f3-4089-8d7f-b8966332bfed', 100668, 'Arifureta: From Commonplace to World''s Strongest', 'Arifureta Shokugyou de Sekai Saikyou', 'ありふれた職業で世界最強', 'https://cdn.kurzagin.com/anime/covers/100668.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/100668-9ZQSB5x5St7c.jpg', 'TV', 'completed', 13, 13, 8, '["Action","Adventure","Fantasy","Psychological"]', 'WHITE FOX', 2019, 'When a classroom of students is transported to another world to act as its saviors, Hajime Nagumo finds himself the weakest link. As his friends and classmates are granted strong classes and impressive abilities due to their existing skills, he is given the weak title of Synergist. When a dungeon quest leaves him separated from his group, Hajime must discover his own talents or be left to rot in this world forever.

(Source: Seven Seas Entertainment)', '2026-10-05T09:44:13.355Z', '2026-10-05T09:44:13.355Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('facde0dd-f778-49cb-8536-9c9eb24c5326', 112323, 'Arifureta: From Commonplace to World''s Strongest Season 2', 'Arifureta Shokugyou de Sekai Saikyou 2nd season', 'ありふれた職業で世界最強 2nd season', 'https://cdn.kurzagin.com/anime/covers/112323.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/112323-cj5O5JUAB840.jpg', 'TV', 'completed', 12, 12, 7, '["Action","Adventure","Fantasy","Psychological"]', 'Asread', 2022, 'Transported to another world and left behind by his former friends, Hajime had to make his rise from literal rock bottom. It was in the labyrinth where he strengthened his weak magic and found several beautiful allies. Now after saving his classmates, he ventures for Erisen to escort Myuu and her mother. He''ll fight and defeat anyone he has to in order to find a way home—including a god!

(Source: Funimation)', '2026-10-05T09:44:49.527Z', '2026-10-05T09:44:49.527Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('888fb3c0-825d-4c47-bdbb-4807e9c5997b', 154473, 'Arifureta: From Commonplace to World''s Strongest Season 3', 'Arifureta Shokugyou de Sekai Saikyou 3rd season', 'ありふれた職業で世界最強 3rd season', 'https://cdn.kurzagin.com/anime/covers/154473.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/154473-FqSlkZcPMfkU.jpg', 'TV', 'planning', 0, 16, NULL, '["Action","Adventure","Fantasy","Psychological"]', 'Asread', 2024, 'En route to conquer a Great Labyrinth with his allies and former classmates, Hajime Nagumo is sidetracked by a tragedy that befalls his party member Shea Haulia. After encountering a group of rabbitmen caught in an ambush, Nagumo learns that members of Shea''s Haulia Tribe have been abducted by soldiers of the Hoelscher Empire. To alleviate the anxiety of Shea, whose father may be in mortal danger, Nagumo decides to head toward the empire and rescue the missing Haulias.

After arriving at his destination, Hajime is caught up in political turmoil between the empire and the Heiligh Kingdom. As princess Liliana S. B. Heiligh tries to formalize an alliance with the empire to protect her weakened kingdom against demon attacks, the Haulia Tribe plans to assassinate Emperor Gahard D. Hoelscher to free all rabbitmen from the empire''s threat. Determined to protect his allies at any cost, Hajime will need to ignore all political considerations and unleash his unstoppable power on anyone who may stand in his way.

(Source: MAL Rewrite)', '2026-10-05T09:45:18.872Z', '2026-10-05T09:45:18.872Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('4d276795-600c-49f1-ab5d-c2b5fc628553', 99263, 'The Rising of the Shield Hero', 'Tate no Yuusha no Nariagari', '盾の勇者の成り上がり', 'https://cdn.kurzagin.com/anime/covers/99263.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/99263-IwkmdCTsDY1t.jpg', 'TV', 'completed', 25, 25, 8, '["Action","Adventure","Fantasy"]', 'Kinema Citrus', 2019, 'Naofumi Iwatani, an uncharismatic Otaku who spends his days on games and manga, suddenly finds himself summoned to a parallel universe! He discovers he is one of four heroes equipped with legendary weapons and tasked with saving the world from its prophesied destruction. As the Shield Hero, the weakest of the heroes, all is not as it seems. Naofumi is soon alone, penniless, and betrayed. With no one to turn to, and nowhere to run, he is left with only his shield. Now, Naofumi must rise to become the legendary Shield Hero and save the world!

Note:
- The first episode was pre-aired on December 27th, 2018. Regular broadcast began on January 9th, 2019.
- The first episode aired with a runtime of ~47 minutes as opposed to the standard 24 minute long episode.', '2026-10-05T09:46:04.255Z', '2026-10-05T09:46:04.255Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('44097925-6328-4dc3-abb4-bf4f7fec3685', 111321, 'The Rising of the Shield Hero Season 2', 'Tate no Yuusha no Nariagari Season 2', '盾の勇者の成り上がり Season 2', 'https://cdn.kurzagin.com/anime/covers/111321.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/111321-nnetF1qONAcE.jpg', 'TV', 'completed', 13, 13, 8, '["Action","Adventure","Fantasy"]', 'Kinema Citrus', 2022, 'With another Wave happening in a week, Naofumi Iwatani and his party have no time to waste. However, when bat familiars raid Lurolona Village and the Wave countdown comes to a halt, the Four Cardinal Heroes reconvene with the queen, Mirelia Q Melromarc, for a quick briefing. The queen presumes that the odd occurrences are linked to the Spirit Tortoise—a threatening creature that has awakened from its slumber, back to cause havoc once again. A plan to put the Spirit Tortoise to rest is devised—but out of the four men, only the cursed Shield Hero agrees to help.

(Source: MAL Rewrite)', '2026-10-05T09:46:25.082Z', '2026-10-05T09:46:25.082Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('cf1d7e17-3f8f-4262-89f9-db7ec9982bae', 111322, 'The Rising of the Shield Hero Season 3', 'Tate no Yuusha no Nariagari Season 3', '盾の勇者の成り上がり Season 3', 'https://cdn.kurzagin.com/anime/covers/111322.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/111322-wK2exU6iNeen.jpg', 'TV', 'completed', 12, 12, 8, '["Action","Adventure","Fantasy"]', 'Kinema Citrus', 2023, 'After defeating the Spirit Tortoise, Naofumi has no time for rest. An attack from the next Guardian Beast is imminent, but the three other Cardinal Heroes have gone missing. So, Naofumi and his party set out to search for the legendary trio. 
(Source: Crunchyroll News)', '2026-10-05T09:46:46.743Z', '2026-10-05T09:46:46.743Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('0c13aa3c-783a-492d-9484-d112a5bf90a4', 124140, 'Sword Art Online the Movie -Progressive- Aria of a Starless Night', 'Sword Art Online: Progressive - Hoshinaki Yoru no Aria', '劇場版 ソードアート・オンライン プログレッシブ 星なき夜のアリア', 'https://cdn.kurzagin.com/anime/covers/124140.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/124140-rkA3sbYSFSo9.jpg', 'MOVIE', 'completed', 1, 1, 9, '["Action","Adventure","Fantasy","Romance"]', 'A-1 Pictures', 2021, 'Return to the death game where it all began—Sword Art Online. In this new Aincrad Arc by original creator Reki Kawahara, the story is seen through Asuna’s eyes. What at first seems like a dream come true quickly becomes a nightmare when newbie gamer Asuna Yuuki learns the only way to escape the virtual world of Aincrad is to beat all 100 levels—but “Game Over” means you die in the real world. 
(Source: Crunchyroll)', '2026-10-04T12:01:54.336Z', '2026-10-04T12:01:54.336Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('df88e3fd-97f4-42f8-9980-8dcde22699fe', 20958, 'Attack on Titan Season 2', 'Shingeki no Kyojin Season 2', '進撃の巨人 Season２', 'https://cdn.kurzagin.com/anime/covers/20958.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20958-Y7eQdz9VENBD.jpg', 'TV', 'completed', 12, 12, 9, '["Action","Drama","Fantasy","Mystery"]', 'WIT STUDIO', 2017, 'Eren Jaeger swore to wipe out every last Titan, but in a battle for his life he wound up becoming the thing he hates most. With his new powers, he fights for humanity''s freedom facing the monsters that threaten his home. After a bittersweet victory against the Female Titan, Eren finds no time to rest—a horde of Titans is approaching Wall Rose and the battle for humanity continues!

(Source: Funimation)', '2026-10-04T12:02:55.053Z', '2026-10-04T12:02:55.053Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('a68ed677-5dcf-4c15-b51b-7edaa92499ce', 173780, 'The Rising of the Shield Hero Season 4', 'Tate no Yuusha no Nariagari Season 4', '盾の勇者の成り上がり Season 4', 'https://cdn.kurzagin.com/anime/covers/173780.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/173780-HImv1cYbvOlp.jpg', 'TV', 'planning', 0, 12, NULL, '["Action","Adventure","Fantasy"]', 'Kinema Citrus', 2025, 'As Naofumi prepares for the Phoenix’s return, assassins from Q’ten Lo target Raphtalia, mistaking her for a throne usurper. To resolve the conflict, Naofumi journeys to Siltvelt, where he is hailed as a demi-human savior, but not all welcome him. In politically volatile Q’ten Lo, Raphtalia becomes a revolutionary symbol. Amid rising chaos, can Naofumi unite his allies and guide them to salvation?

(Source: Crunchyroll News)', '2026-10-05T09:47:11.073Z', '2026-10-05T09:47:11.073Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('d8eabafe-2d66-40e0-81d0-c1c65a9a5c82', 18671, 'Love, Chunibyo & Other Delusions - Heart Throb -', 'Chuunibyou demo Koi ga Shitai! Ren', '中二病でも恋がしたい！戀', 'https://cdn.kurzagin.com/anime/covers/18671.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/18671.jpg', 'TV', 'completed', 12, 12, 9, '["Comedy","Drama","Romance","Slice of Life"]', 'Kyoto Animation', 2014, 'Due to various events, Yuuta and Rikka are living together. This secret co-habitation is so exciting for the two lovebirds! Or so it should be...

Is having a chuuni girlfriend too high of a hurdle for Yuuta, who never even went out with a normal girl?! Yuuta worries about how to advance his relationship with Rikka. And then everyone else, Nibutani, Kumin, and Dekomori, have powered up by advancing a grade. Furthermore, the cause of his chuunibyou outburst in middle school, the girl who calls herself Sophia Ring Saturn the 7th, Satone Shichimiya appears...

This is the long-awaited second season of the adolescent romantic comedy revolving around chuunibyou that makes you laugh and cry.


(Source: Animax)', '2026-10-07T03:09:11.772Z', '2026-10-07T03:09:11.772Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('0810b777-e47d-4405-a1ab-17a3d1e8083a', 98762, 'Love, Chunibyo & Other Delusions: Take on Me', 'Chuunibyou demo Koi ga Shitai!: Take On Me', '映画 中二病でも恋がしたい！ -Take On Me-', 'https://cdn.kurzagin.com/anime/covers/98762.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/98762-NP7QrczIrr73.jpg', 'MOVIE', 'completed', 1, 1, 9, '["Comedy","Drama","Romance","Slice of Life"]', 'Kyoto Animation', 2018, 'Rikka is now a third-year student, but she still has "chuunibyou" syndrome. University entrance exams loom on the horizon, and it''s spring break, and Yuuta and Rikka are together as usual. One day, Rikka''s older sister Touka declares that she''s going to take Rikka to Italy with her, as Touka is moving to Italy for work and she thinks they should move together as a family. Yuuta understands Touka''s opinion, but thinks that at this rate he and Rikka will be separated. Shinka and the other members suggest that Yuuta and Rikka should "elope," and thus sets the stage for Yuuta and Rikka''s travels throughout Japan in their escape drama.

(Source: Anime News Network)', '2026-10-07T03:09:34.502Z', '2026-10-07T03:09:34.502Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('76821ea3-9812-4612-9158-a1308e59e74f', 103632, 'So I''m a Spider, So What?', 'Kumo desu ga, Nani ka?', '蜘蛛ですが、なにか？', 'https://cdn.kurzagin.com/anime/covers/103632.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/103632-N4ssExnvLw74.jpg', 'TV', 'completed', 24, 24, 10, '["Action","Adventure","Comedy","Fantasy","Mystery"]', 'Millepensee', 2021, 'I, the protagonist, was just an ordinary high school girl, but suddenly I was reincarnated as a spider monster in a fantasy world. Not only that, but I awakened in a dungeon filled with vicious monsters. Armed with only my human knowledge and my overwhelming positivity, I''m forced to use spiderwebs and traps to defeat far stronger monsters just to stay alive... So begins the labyrinth survival story of a girl with incredible mental strength living as one of the lowest-ranked beasts!

(Source: Crunchyroll)', '2026-10-07T03:10:13.831Z', '2026-10-07T03:10:13.831Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('6dbc8844-ebe4-492c-964c-d7171283580e', 9919, 'Blue Exorcist', 'Ao no Exorcist', '青の祓魔師', 'https://cdn.kurzagin.com/anime/covers/9919.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/9919-S5idQm3GbZ80.jpg', 'TV', 'completed', 25, 25, 7, '["Action","Fantasy","Supernatural"]', 'A-1 Pictures', 2011, 'This world consists of two dimensions joined as one, like a mirror. The first is the world in which the humans live, Assiah. The other is the world of demons, Gehenna. Ordinarily, travel between the two, and indeed any kind of contact between the two, is impossible. However the demons can pass over into this world by possessing anything that exist within it. Satan the god of demons, but there''s one thing that he doesn''t have, and that''s a substance in the human world that is powerful enough to contain him!! For that purpose he created Rin, his son from a human woman, but will his son agree to his plans? Or will he become something else...? An exorcist?
', '2026-10-07T03:11:15.768Z', '2026-10-07T03:11:15.768Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('876cba66-1d07-463a-a81f-7dee714ed353', 105333, 'Dr. STONE', 'Dr. STONE', 'Dr.STONE', 'https://cdn.kurzagin.com/anime/covers/105333.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/105333-KWKGvBM8Hyga.jpg', 'TV', 'completed', 24, 24, 8, '["Action","Adventure","Comedy","Sci-Fi"]', 'TMS Entertainment', 2019, 'After five years of harboring unspoken feelings, high-schooler Taiju Ooki is finally ready to confess his love to Yuzuriha Ogawa. Just when Taiju begins his confession however, a blinding green light strikes the Earth and petrifies mankind around the world— turning every single human into stone.

Several millennia later, Taiju awakens to find the modern world completely nonexistent, as nature has flourished in the years humanity stood still. Among a stone world of statues, Taiju encounters one other living human: his science-loving friend Senkuu, who has been active for a few months. Taiju learns that Senkuu has developed a grand scheme—to launch the complete revival of civilization with science. Taiju''s brawn and Senkuu''s brains combine to forge a formidable partnership, and they soon uncover a method to revive those petrified.

However, Senkuu''s master plan is threatened when his ideologies are challenged by those who awaken. All the while, the reason for mankind''s petrification remains unknown.

(Source: MAL Rewrite)', '2026-10-07T03:13:06.240Z', '2026-10-07T03:13:06.240Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('aad5238b-b78e-4589-a21a-b05969096333', 16157, 'Hyperdimension Neptunia', 'Choujigen Game Neptune THE ANIMATION', '超次元ゲイム ネプテューヌ THE ANIMATION', 'https://cdn.kurzagin.com/anime/covers/16157.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n16157-d2N5AX8LEpRe.jpg', 'TV', 'completed', 12, 12, 10, '["Action","Comedy","Ecchi","Mahou Shoujo","Sci-Fi","Supernatural"]', 'david production', 2013, 'Welcome to Gamindustri, a fantastical world where all your favorite video game consoles come to life! Neptune and her fellow Goddesses rule the four kingdoms of Lastation, Leanbox, Lowee, and Planeptune – but their royal duties often take a backseat to their obsession with gaming. When their button-mashing shenanigans are interrupted by rampaging monsters, hacker attacks, and killer eggplants, the goddesses must transform into stronger, sexier versions of themselves and fight for their right to game! The bosses get tougher as the game goes on, and the girls will have to work together in order to defeat a bewitching goddess of piracy, an anonymous master hacker, and an evil CPU hell-bent on destroying everything in her path – using any cheat code necessary!
(Source: Funimation)', '2026-10-07T03:16:29.963Z', '2026-10-07T03:16:29.963Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('a537353f-25de-4e0e-afd1-f71db978a448', 187260, 'I Want to Love You Till Your Dying Day', 'Kimi ga Shinu made Koi wo Shitai', 'きみが死ぬまで恋をしたい', 'https://cdn.kurzagin.com/anime/covers/187260.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/187260-HMkLPy3ZvzW1.jpg', 'TV', 'planning', 0, 13, NULL, '["Drama","Fantasy","Romance"]', 'ROLL2', 2026, 'At the mysterious orphanage where Sheena lives, death is nothing new to its residents—girls who no longer have families of their own, who are raised as weapons of war, taught to kill and take the lives of others without batting an eye. Everyone, that is, except Sheena, who wishes for nothing more than the growing conflict around her to end. On the night of her roommate''s death, Sheena meets a strange girl covered in blood, who smiles despite the turmoil surrounding them. The next day, the girl appears as a new student in Sheena''s class and introduces herself as Mimi. Initially thought to be a school myth, there are now whispers in the orphanage''s halls that Mimi is their secret weapon—an immortal who cannot die. When Mimi is later assigned as Sheena''s new roommate, Sheena''s world grows even more complicated when she begins living with someone who loves and welcomes death, when all Sheena wants to do is stop it…

(Source: Kodansha USA)', '2026-10-06T02:33:38.456Z', '2026-10-06T02:33:38.456Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('0741dc2f-2754-4357-9284-0ac9192ce099', 101310, 'Boarding School Juliet', 'Kishuku Gakkou no Juliet', '寄宿学校のジュリエット', 'https://cdn.kurzagin.com/anime/covers/101310.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/101310-ybQFtNXjTyhp.jpg', 'TV', 'completed', 12, 12, 8, '["Comedy","Romance"]', 'LIDENFILMS', 2018, 'Grigio Academy Boarding School. The students that attend this school come from two countries, and reside in their own dormitories. Inazuka and Persia are leaders of rival dorms, but in secret they love each other. Now, they have to keep their relationship a secret from their dorm mates or else bad things will happen to them.
', '2026-10-06T05:39:01.922Z', '2026-10-06T05:39:01.922Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('de90a240-0b71-4522-8598-8e7264eb9915', 20665, 'Your lie in April', 'Shigatsu wa Kimi no Uso', '四月は君の嘘', 'https://cdn.kurzagin.com/anime/covers/20665.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20665-j4kSsfhfkM24.jpg', 'TV', 'completed', 22, 22, 7, '["Drama","Music","Romance","Slice of Life"]', 'A-1 Pictures', 2014, 'Piano prodigy Arima Kousei dominated the competition and all child musicians knew his name. But after his mother, who was also his instructor, passed away, he had a mental breakdown while performing at a recital. This resulted in him no longer being able to hear the sound of his piano playing. Two years later, Kousei hasn’t touched the piano and views the world without any flair or color. He was content at living out his life with his good friends Tsubaki and Watari until, one day, a girl changed everything. Miyazono Kaori is a pretty, free spirited violinist whose playing style reflects her personality. Kaori helps Kousei return to the music world and show that it should be free and mold breaking unlike the structured and rigid style Kousei was used to.', '2026-10-05T09:31:42.986Z', '2026-10-06T05:39:26.220Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('39994417-9d64-4185-9785-21ec7863eaa3', 21685, 'Eromanga Sensei', 'Eromanga Sensei', 'エロマンガ先生', 'https://cdn.kurzagin.com/anime/covers/21685.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21685-7qhjceISmSsv.jpg', 'TV', 'completed', 12, 12, 7, '["Comedy","Drama","Ecchi","Romance","Slice of Life"]', 'A-1 Pictures', 2017, 'The "new sibling romantic comedy" revolves around Masamune Izumi, a light novel author in high school. Masamune''s little sister is Sagiri, a shut-in girl who hasn''t left her room for an entire year. She even forces her brother to make and bring her meals when she stomps the floor. Masamune wants his sister to leave her room, because the two of them are each other''s only family.

Masamune''s novel illustrator, penname “Ero Manga Sensei,” draws extremely perverted drawings, and is very reliable. Masamune had never met his illustrator, and figured he was just a disgusting, perverted otaku. However, the truth is revealed … that his “Ero Manga Sensei” is his own younger sister! To add to the chaos that erupts between the siblings, a beautiful, female, best-selling shoujo manga creator becomes their rival!

(Source: Anime News Network)', '2026-10-07T02:23:56.811Z', '2026-10-07T02:23:56.811Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('354926b2-7b1e-4f7d-9439-e35079c99352', 99507, 'The Ryuo''s Work is Never Done!', 'Ryuuou no Oshigoto!', 'りゅうおうのおしごと!', 'https://cdn.kurzagin.com/anime/covers/99507.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/99507-7kUlcMJTRBVQ.jpg', 'TV', 'completed', 12, 12, 7, '["Comedy","Slice of Life"]', 'project No.9', 2018, '16 year old Kuzuryuu Yaichi has fallen into a slump after winning the major shogi title "Dragon King", the pressure of his losses continue until an elementary schooler called Hinatsuru Ai, with an extraordinary shogi talent, arrives at his doorstep.', '2026-10-07T02:24:19.437Z', '2026-10-07T02:24:19.437Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('ce74bf10-11d4-4227-96aa-3a823e45f2b1', 21857, 'Masamune-kun''s Revenge', 'Masamune-kun no Revenge', '政宗くんのリベンジ', 'https://cdn.kurzagin.com/anime/covers/21857.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21857-k7r362xG7420.png', 'TV', 'completed', 12, 12, 7, '["Comedy","Romance","Slice of Life"]', 'SILVER LINK.', 2017, 'As an overweight child, Makabe Masamune was mercilessly teased and bullied by one particular girl, Adagaki Aki. Determined to one day exact his revenge upon her, Makabe begins a rigorous regimen of self-improvement and personal transformation.

Years later, Masamune re-emerges as a new man. Handsome, popular, with perfect grades and good at sports, Masamune-kun transfers to Aki''s school, and is unrecognizable to her. Now, Masamune-kun is ready to confront the girl who bullied him so many years ago and humiliate her at last. But will revenge be as sweet as he thought?

(Source: Seven Seas Entertainment)', '2026-10-07T02:24:56.369Z', '2026-10-07T02:24:56.369Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('e5adc86a-d977-4ab1-9121-bafcf8fe9fc3', 97859, 'Yuuki Yuuna wa Yuusha de Aru: Washio Sumi no Shou 2 - Tamashii', 'Yuuki Yuuna wa Yuusha de Aru: Washio Sumi no Shou 2 - Tamashii', '結城友奈は勇者である -鷲尾須美の章- 第2章 「たましい」', 'https://cdn.kurzagin.com/anime/covers/97859.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/97859-W5tO2X962bag.jpg', 'MOVIE', 'completed', 1, 1, 10, '["Action","Drama","Fantasy","Mahou Shoujo","Slice of Life"]', 'Studio Gokumi', 2017, 'The second movie in the Washio Sumi no Shou trilogy.', '2026-10-04T14:31:38.575Z', '2026-10-04T14:31:38.575Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('1d133fc1-25ce-4627-945c-7574640db4a8', 11499, 'Sankarea: Undying Love', 'Sankarea', 'さんかれあ', 'https://cdn.kurzagin.com/anime/covers/11499.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/11499-etOfsgdjZY4L.jpg', 'TV', 'completed', 12, 12, 7, '["Comedy","Ecchi","Horror","Romance","Supernatural"]', 'Studio DEEN', 2012, 'Furuya''s not interested in the living, he''s got zombies on the brain! When Furuya''s cat dies, he decides he''s going to try and bring it back to life. In the process, he stumbles across a girl who is involved in an accident and turns into a real zombie! What''s Furuya going to do now that the thing he loves the most is right in front of his eyes?
(Source: FUNimation)', '2026-10-07T02:27:31.836Z', '2026-10-07T02:27:31.836Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('73d69a77-8301-4fe8-a0fe-0f7adf16e56d', 7724, 'Shiki', 'Shiki', '屍鬼', 'https://cdn.kurzagin.com/anime/covers/7724.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/7724.jpg', 'TV', 'completed', 22, 22, 7, '["Horror","Mystery","Supernatural","Thriller"]', 'Daume', 2010, 'During a fiercely hot summer in Sotoba, a peaceful and quiet village with a population of 1300 people, a series of bizarre deaths begin to occur. At the same time, a strange family moves into a long abandoned mansion in the region. After supposedly visiting this strange family, the fashionable Shimizu Megumi goes missing and the entire village goes out in search for her.', '2026-10-07T02:28:22.746Z', '2026-10-07T02:28:22.746Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('04db039f-59d6-45bc-8532-e3e3cd980f6c', 21700, 'Akashic Records of Bastard Magic Instructor', 'Rokudenashi Majutsu Koushi to Akashic Records', 'ロクでなし魔術講師と禁忌教典(アカシックレコード)', 'https://cdn.kurzagin.com/anime/covers/21700.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21700-3JaMOphL8VGr.jpg', 'TV', 'completed', 12, 12, 8, '["Action","Comedy","Fantasy"]', 'LIDENFILMS', 2017, 'In the "action fantasy" story, Glenn is a part-time teacher at a magic school who is inclined to write "self-study" on the blackboard and then take a nap. One of his students, Sistine, gets angry and challenges him to a duel and he is easily defeated. However, when a terrible incident threatens the school, Glenn shows intense dedication to protecting his students.

(Source: Anime News Network)', '2026-10-07T02:29:28.046Z', '2026-10-07T02:29:28.046Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('3ee04346-2ad8-4db3-9c09-f3a3c80a07d9', 143270, 'Lycoris Recoil', 'Lycoris Recoil', 'リコリス・リコイル', 'https://cdn.kurzagin.com/anime/covers/143270.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/143270-Ivjs2nVpARtS.jpg', 'TV', 'completed', 13, 13, 8, '["Action","Slice of Life"]', 'A-1 Pictures', 2022, '“LycoReco” is a café with a traditional Japanese twist located in downtown Tokyo. But the delicious coffee and sugary sweets are not the only orders this café takes! From delivering packages short distances, to pick-ups and drop-offs on the lonely streets at night, to zombies and giant monster extermination…?! Whatever your problem, we''re here to help! We will solve any kind of "trouble" you may have!

Waiting for you are the ever-smiling poster-girl and the cool, serious newcomer. A petite girl who never wants to work and a young woman approaching thirty who wants to get married. And the manager is a nice guy who’s obsessed with Japan!

Whatever your order is, leave it all up to us♪

(Source: Official Site)', '2026-10-07T02:29:59.062Z', '2026-10-07T02:29:59.062Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('6e3c79a0-7deb-48f0-bbb0-cbb27f24863f', 100112, 'Wise Man’s Grandchild', 'Kenja no Mago', '賢者の孫', 'https://cdn.kurzagin.com/anime/covers/100112.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/100112-QIFhGfuiKZ3Y.jpg', 'TV', 'completed', 12, 12, 7, '["Action","Comedy","Fantasy","Romance"]', 'SILVER LINK.', 2019, 'A young man is reborn in another world where he is adopted as a baby by the hero Merlin Wolford and named Shin. By his 15th birthday, Shin has accumulated all kinds of power by studying under Merlin, but one thing his adoptive grandfather didn''t give him was a lick of common sense. 
(Source: Anime News Network)', '2026-10-07T02:34:04.716Z', '2026-10-07T02:34:04.716Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('95884354-c230-4154-aa35-04b8cf630e91', 97682, 'Grimoire of Zero', 'Zero kara Hajimeru Mahou no Sho', 'ゼロから始める魔法の書', 'https://cdn.kurzagin.com/anime/covers/97682.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/97682-HgEodWuTgFgS.jpg', 'TV', 'completed', 12, 12, 7, '["Action","Drama","Fantasy"]', 'WHITE FOX', 2017, 'The "grimoire fantasy" series follows a witch named Zero who is ignorant of the world and a half-beast half-human mercenary who longs to be human. Witches who practice sorcery exist in the world, however, in this era no one knows how about the art and study of witchcraft. Zero is going on a journey to search for a magical tome called "The Book of Zero" that hides a power that can destroy the world. The mercenary travels with her as her guard.

(Source: Anime News Network)', '2026-10-07T02:34:26.696Z', '2026-10-07T02:34:26.696Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('7cde15a5-1e22-4d4a-bcb0-a37648f34927', 101165, 'GOBLIN SLAYER', 'Goblin Slayer', 'ゴブリンスレイヤー', 'https://cdn.kurzagin.com/anime/covers/101165.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/101165-bXPZrNiQGPHd.jpg', 'TV', 'completed', 12, 12, 10, '["Action","Adventure","Fantasy"]', 'WHITE FOX', 2018, 'A young priestess has formed her first adventuring party, but almost immediately they find themselves in distress. It''s the Goblin Slayer who comes to their rescue--a man who''s dedicated his life to the extermination of all goblins, by any means necessary. And when rumors of his feats begin to circulate, there''s no telling who might come calling next...

(Source: Yen Press)', '2026-10-07T02:34:58.583Z', '2026-10-07T02:34:58.583Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('7dea40db-1876-482d-b128-24e86950fd47', 108623, 'GOBLIN SLAYER -GOBLIN’S CROWN-', 'Goblin Slayer: GOBLIN''S CROWN', 'ゴブリンスレイヤー -GOBLIN''S CROWN-', 'https://cdn.kurzagin.com/anime/covers/108623.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/108623-9FL63jABa1N9.jpg', 'MOVIE', 'completed', 1, 1, 10, '["Action","Adventure","Fantasy"]', 'WHITE FOX', 2020, '“Please find any information on the Noble Fencer that disappeared after leaving to slay some goblins.”

Goblin Slayer and his party head up to the snowy mountains in the north after receiving that request from the Sword Maiden. A small village gets attacked, they encounter a mysterious chapel, and something about how these goblins are acting bothers the Goblin slayer.

“I’m going to take back everything that I’ve lost!”

In order to save the captured Noble Fencer, the Goblin Slayer and his party head to an ancient fortress covered in snow to face off with a powerful foe and a horde of goblins!

(Source: Crunchyroll)', '2026-10-07T02:35:22.886Z', '2026-10-07T02:35:22.886Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('08343ef0-eb74-42ed-ab2b-089722fd22af', 129188, 'GOBLIN SLAYER II', 'Goblin Slayer II', 'ゴブリンスレイヤーⅡ', 'https://cdn.kurzagin.com/anime/covers/129188.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/129188-JMptckRAFHEr.jpg', 'TV', 'planning', 0, 12, NULL, '["Action","Adventure","Fantasy"]', 'LIDENFILMS', 2023, 'As spring arrives, goblin activity increases, which is great news for Goblin Slayer, who will do anything to exterminate these vile creatures. While taking on as many goblin slaying quests as possible, he attracts the attention of an ill-tempered novice wizard who asks for his guidance. Although reluctant at first, Goblin Slayer and his fellow adventurers are soon tasked with instructing the boy and several other rookies. With goblins continuing to cause harm nearby, Goblin Slayer will show no mercy to these monsters and ensure that everyone else is prepared.

(Source: MAL Rewrite)', '2026-10-07T02:35:42.555Z', '2026-10-07T02:35:42.555Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('d08a2d67-c9b8-49da-a255-b2a3648a2beb', 108631, 'Cells at Work!!', 'Hataraku Saibou!!', 'はたらく細胞!!', 'https://cdn.kurzagin.com/anime/covers/108631.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/108631-NnAkKEveLSlc.jpg', 'TV', 'completed', 8, 8, 7, '["Action","Comedy","Sci-Fi"]', 'david production', 2021, 'Cells at Work!! continues the tale of…well…you! Set inside the human body, Cells at Work!! chronicles the life and times of everything from the oxygen-carrying Red Blood Cells to the bacteria-fighting White Blood Cells. And, of course, the dangerous viruses and villains lurking beneath the skin!

(Source: Funimation)

Notes:
- The episodes were streamed two days ahead of the Japanese broadcast on Funimation beginning on Jan 8, 2021 at 2:00 JST. The regular TV broadcast started on Jan 9, 2021 at 23:30 JST.
- The pre-screened movie "Hataraku Saibou!!" Saikyou no Teki, Futatabi. Karada no Naka wa "Chou" Oosawagi! is included as episodes 4-8 split into the broadcast.', '2026-10-07T02:36:07.862Z', '2026-10-07T02:36:07.862Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('9e53c9cf-0ee0-49ca-9c9f-0cee759f314e', 98444, 'Laid-Back Camp', 'Yuru Camp△', 'ゆるキャン△', 'https://cdn.kurzagin.com/anime/covers/98444.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/98444-FpH9lzLiafe9.jpg', 'TV', 'completed', 12, 12, 9, '["Comedy","Slice of Life"]', 'C-Station', 2018, 'Rin likes to go camping by herself along the lakes that provide a scenic view of Mt. Fuji. Nadeshiko loves to take cycling trips by herself to places where she can see Mt. Fuji. After they meet, Rin and Nadeshiko take camping trips, eat cup ramen together, and enjoy the scenery. (Source: Anime News Network)', '2026-10-07T02:36:49.978Z', '2026-10-07T02:36:49.978Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('6920f634-4bee-48c8-ac85-9c17df191aca', 99468, 'Teasing Master Takagi-san', 'Karakai Jouzu no Takagi-san', 'からかい上手の高木さん', 'https://cdn.kurzagin.com/anime/covers/99468.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/99468-WdWcFGyIeunj.jpg', 'TV', 'completed', 12, 12, 7, '["Comedy","Romance","Slice of Life"]', 'Shin-Ei Animation', 2018, 'Having a friend that knows you inside out should be a good thing, but in Nishikata''s case, the opposite is true.

His classmate Takagi loves to tease him on a daily basis, and she uses her extensive knowledge of his behavior to predict exactly how he will react to her teasing, making it nearly impossible for Nishikata to ever make a successful comeback. Despite this, Nishikata vows to someday give Takagi a taste of her own medicine by making her blush out of embarrassment from his teasing.
', '2026-10-07T02:38:02.780Z', '2026-10-07T02:38:02.780Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('5229d244-eba3-4f04-bfbe-19872eee4ff7', 105914, 'The Helpful Fox Senko-san', 'Sewayaki Kitsune no Senko-san', '世話やきキツネの仙狐さん', 'https://cdn.kurzagin.com/anime/covers/105914.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/105914-IjUd9COihC94.jpg', 'TV', 'completed', 12, 12, 9, '["Comedy","Fantasy","Slice of Life","Supernatural"]', 'Doga Kobo', 2019, 'Sometimes the cure to a hard day’s work is the tender love and care of…a fox girl?! Salaryman Nakano’s stressful life is suddenly intruded upon by the fox, Senko-san, who is eager to help him heal his exhaustion. Whether she’s cooking, cleaning, or finding other ways to care for Nakano, she’s there to take away his stress!

(Source: Crunchyroll)', '2026-10-07T02:38:31.306Z', '2026-10-07T02:38:31.306Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('1cc6887a-ae5b-46b8-a07d-a50813d294ab', 101921, 'Kaguya-sama: Love is War', 'Kaguya-sama wa Kokurasetai: Tensaitachi no Renai Zunousen', 'かぐや様は告らせたい～天才たちの恋愛頭脳戦～', 'https://cdn.kurzagin.com/anime/covers/101921.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/101921-GgvvFhlNhzlF.jpg', 'TV', 'completed', 12, 12, 8, '["Comedy","Psychological","Romance","Slice of Life"]', 'A-1 Pictures', 2019, 'Known for being both brilliant and powerful, Miyuki Shirogane and Kaguya Shinomiya lead the illustrious Shuchiin Academy as near equals. And everyone thinks they’d make a great couple. Pride and arrogance are in ample supply, so the only logical move is to trick the other into instigating a date! Who will come out on top in this psychological war where the first move is the only one that matters?

(Source: Aniplex)', '2026-10-07T02:38:53.199Z', '2026-10-07T02:38:53.199Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('ac4df55b-614f-4da8-97b1-3d4fd1fe3748', 116267, 'TONIKAWA: Over The Moon For You', 'Tonikaku Kawaii', 'トニカクカワイイ', 'https://cdn.kurzagin.com/anime/covers/116267.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/116267-xQRslGT0tMTS.jpg', 'TV', 'completed', 12, 12, 9, '["Comedy","Romance","Slice of Life"]', 'Seven Arcs', 2020, 'The story follows a protagonist whose name is written with the characters for "Hoshizora" ("Starry Sky" in Japanese), but whose name is pronounced as "Nasa". On the day of his high school entrance exams, Nasa encounters a beautiful girl named Tsukasa. For Nasa, it feels like destiny is finally calling out to him that he will have a girlfriend, but things take a turn for the worse when Nasa is hit by a car and unable to attend his entrance exams.

After Tsukasa helps the injured Nasa, he confesses his feelings to her, and she agrees to go out with him, but only if Nasa agrees to marry her first. A year later Nasa aces the entrance exams, but he decides to work a part time job and live by himself instead of going to school. After Nasa turns 18, Tsukasa re-appears, and their happy, romantic, and mysterious married life together begins.

(Source: Crunchyroll)', '2026-10-07T02:39:16.146Z', '2026-10-07T02:39:16.146Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('6cab5ac0-06e9-459a-a2c3-e93a7dc0bda5', 104647, 'My Next Life as a Villainess: All Routes Lead to Doom!', 'Otome Game no Hametsu Flag shika Nai Akuyaku Reijou ni Tensei shiteshimatta…', '乙女ゲームの破滅フラグしかない悪役令嬢に転生してしまった…', 'https://cdn.kurzagin.com/anime/covers/104647.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/104647-emIYPiyZZJnl.jpg', 'TV', 'completed', 12, 12, 9, '["Comedy","Fantasy","Romance","Slice of Life"]', 'SILVER LINK.', 2020, 'Wealthy heiress Katarina Claes is hit in the head with a rock and recovers the memories of her past life. It turns out the world she lives in is the world of the game Fortune Lover, an otome game she was obsessed with in her past life... but she''s been cast as the villain character who tries to foil the protagonist''s romances! The best ending the game has for Katarina is exile, and the worst, death! She''ll have to find a way to avoid triggering the flags of doom, and make her own happy future!

(Source: Crunchyroll, edited)', '2026-10-07T02:39:58.355Z', '2026-10-07T02:39:58.355Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('e23d475e-5a53-4f90-87dc-8dd3e5baa7f0', 106479, 'BOFURI: I Don''t Want to Get Hurt, so I''ll Max Out My Defense.', 'Itai no wa Iya nano de Bougyoryoku ni Kyokufuri Shitai to Omoimasu.', '痛いのは嫌なので防御力に極振りしたいと思います。', 'https://cdn.kurzagin.com/anime/covers/106479.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/106479-G1rExJ4m8Be3.jpg', 'TV', 'completed', 12, 12, 8, '["Action","Adventure","Comedy","Fantasy","Slice of Life"]', 'SILVER LINK.', 2020, 'The story centers on Kaede Honjou, who is invited by her friend Risa Shiramine to play a virtual reality MMO game with her. While Kaede doesn''t dislike games, what she really, truly dislikes is being in pain. She creates a character named Maple, and decides to put all her points in VIT to minimize pain. As a result, she moves slowly, can''t use magic, and even a rabbit can get the best of her. However, as it turns out, she acquires a skill known as "Absolute Defense" as a result of her pumping points into VIT, as well as a "Counter Skill" that works against special moves. Now, with her ability to nullify all damage, she goes on adventures.(Source: Anime News Network, edited)', '2026-10-07T02:40:35.635Z', '2026-10-07T02:40:35.635Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('07215100-4cba-4e97-965f-1a942c003f69', 116867, 'BOFURI: I Don''t Want to Get Hurt, so I''ll Max Out My Defense. Season 2', 'Itai no wa Iya nano de Bougyoryoku ni Kyokufuri Shitai to Omoimasu. 2', '痛いのは嫌なので防御力に極振りしたいと思います。2', 'https://cdn.kurzagin.com/anime/covers/116867.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/116867-fYVvG0PtdupB.jpg', 'TV', 'completed', 12, 12, 8, '["Action","Adventure","Comedy","Fantasy","Slice of Life"]', 'SILVER LINK.', 2023, 'The best offense is a great defense, and for VRMMO gamer Kaede Honjo, her defense is the best. Under her alias Maple, she and her guild journey through NewWorld Online gaining friends and foes through new battle-filled quests. All those skill points, new defensive techniques, and no pain—Maple can’t be stopped! 
(Source: Crunchyroll)

Note: Episode 1 was streamed in advance on December 17, 2022 on the KADOKAWA Anime YouTube Channel. The regular TV broadcast began on January 11, 2023. ', '2026-10-07T02:40:54.975Z', '2026-10-07T02:40:54.975Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('064002ad-7abd-43b3-a7f1-dfeb1ec5bab4', 4898, 'Black Butler', 'Kuroshitsuji', '黒執事', 'https://cdn.kurzagin.com/anime/covers/4898.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/4898-qqGPkf0qkMDh.jpg', 'TV', 'completed', 24, 24, 8, '["Action","Comedy","Fantasy","Mystery","Supernatural"]', 'A-1 Pictures', 2008, 'In Victorian-era Europe, a young boy loses everything he once held near and dear to a vicious plot. In his moment of death, he strikes a deal with a demon: his soul, in exchange for revenge. Ciel Phantomhive is now the head of the Phantomhive corporation, handling all business affairs as well as the underground work for the Queen of England. His new partner is a demon butler, Sebastian Michaelis, whose powers as a butler is only surpassed by his strength as a demon.
The story follows the two along with their other servants, as they work to unravel the plot behind Ciel''s parents'' murder, and the horrendous tragedies that befell Ciel in the month directly after.', '2026-10-07T02:41:42.409Z', '2026-10-07T02:41:42.409Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('f0f1fdfc-bfcb-46bb-8ee8-8e4b56a9fc08', 129898, 'The World''s Finest Assassin Gets Reincarnated in Another World as an Aristocrat', 'Sekai Saikou no Ansatsusha, Isekai Kizoku ni Tensei suru', '世界最高の暗殺者、異世界貴族に転生する', 'https://cdn.kurzagin.com/anime/covers/129898.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/129898-Qp41lxD3wU9e.jpg', 'TV', 'completed', 12, 12, 9, '["Action","Adventure","Drama","Fantasy","Mystery","Romance"]', 'SILVER LINK.', 2021, 'The world''s number one assassin has been reincarnated as the eldest son of a family of aristocrat assassins. In exchange for being reincarnated in another world, a goddess has imposed upon him one condition. "Kill the Hero who is prophesied to destroy the world." 

This was to be the mission in his new life. The synergistic effect of the vast knowledge and experience he gained that made all manner of assassinations possible in the modern world, and the secret techniques and magic of the fantasy world''s most powerful family of assassins turn him into the greatest assassin of all time.

(Source: Crunchyroll)', '2026-10-07T02:43:21.597Z', '2026-10-07T02:43:21.597Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('45c77a65-f4c0-4cd4-aa08-3b3990086e2e', 124080, 'Horimiya', 'Horimiya', 'ホリミヤ', 'https://cdn.kurzagin.com/anime/covers/124080.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/124080-ARyLAHHgikRq.jpg', 'TV', 'completed', 13, 13, 8, '["Comedy","Romance","Slice of Life"]', 'CloverWorks', 2021, 'A secret life is the one thing they have in common. At school, Hori is a prim and perfect social butterfly, but the truth is she''s a brash homebody. Meanwhile, under a gloomy facade, Miyamura hides a gentle heart, along with piercings and tattoos. In a chance meeting, they both reveal a side they''ve never shown. Could this blossom into something new?

(Source: Funimation)', '2026-10-07T02:44:56.310Z', '2026-10-07T02:44:56.310Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('df246856-3461-463e-a3ae-d902914be1cf', 15583, 'Date A Live', 'Date A Live', 'デート・ア・ライブ', 'https://cdn.kurzagin.com/anime/covers/15583.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/15583.jpg', 'TV', 'completed', 12, 12, 7, '["Action","Comedy","Ecchi","Fantasy","Mecha","Romance","Sci-Fi"]', 'AIC Plus+', 2013, 'Thirty years before a strange phenomena called a "spacequake" devastated the center of Eurasia, claiming the lives of at least 150 million people. Since then, smaller spacequakes plague the world on an irregular basis. Shidou Itsuka, a seemingly ordinary high schooler comes across a mysterious girl at the ground zero of a spacequake and learns from his sister Kotori she is one of the "Spirits" who are the real cause of the spacequakes that occur when they manifest themselves in the world. He also learns that Kotori is the captain of the airship Ratatoskr and recruits him to make use of his mysterious ability to seal the Spirits'' powers and stop them from being a threat to mankind. However, there is a catch: to seal a Spirit, he must make her fall in love with him.

(Source: Anime News Network)', '2026-10-07T02:45:23.795Z', '2026-10-07T02:45:23.795Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('b0ba6a09-685d-4f09-a8d5-ac737501be77', 19163, 'Date A Live II', 'Date A Live II', 'デート・ア・ライブⅡ', 'https://cdn.kurzagin.com/anime/covers/19163.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/19163-AMxCNgJINc2F.jpg', 'TV', 'completed', 10, 10, 7, '["Action","Comedy","Ecchi","Fantasy","Romance","Sci-Fi"]', 'Production IMS', 2014, 'Shido Itsuka, who used to be a normal high school student at Raizen High, meets the first Spirit, Tohka, and awakens his power to "seal the Spirit''s power". Though they may be feared and hated beings due to their immense power, Spirits were always alone and knew only combat and death. Shido, the only one in the world with the power to seal the Spirits'' might, hurls himself into life-threatening dates with the beautiful Spirits in order to save them.

(Source: Anime News Network)', '2026-10-07T02:45:45.352Z', '2026-10-07T02:45:45.352Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('23fe3dbe-dd00-46cf-9bef-bda97c95a525', 100722, 'Date A Live III', 'Date A Live III', 'デート・ア・ライブⅢ', 'https://cdn.kurzagin.com/anime/covers/100722.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/100722-dppmox9jqbx5.jpg', 'TV', 'completed', 12, 12, 7, '["Action","Comedy","Ecchi","Fantasy","Mecha","Romance","Sci-Fi"]', 'J.C.STAFF', 2019, 'Itsuka Shidou''s life has been a whirlwind as of late. Or more precisely, a spatial quake. Several of them, in fact. Powerful "Spirits" from other dimensions that take the form of girls are unintentionally causing these spatial quakes in his reality. And Shidou is the only one who can stop them with his unique ability: kissing them! By having the girls kiss and fall deeply in love with him, their devastating quake powers are sealed. The alternative to romancing them is to have a more militant and technological organization called the AST (Anti-Spirit Team) destroy the Spirits, something Shidou is vehemently against.

So far in the story, six Spirits have fallen for Shidou (as well as a few others). The girls compete with one another and vie for his affection, leaving him no end of headaches and misadventures. But a new challenger approaches.

(Source: Tokyo Otaku Mode)', '2026-10-07T02:46:18.500Z', '2026-10-07T02:46:18.500Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('7faca0d8-57d4-4dcd-95b0-aed1f5ae3146', 10793, 'Guilty Crown', 'Guilty Crown', 'ギルティクラウン', 'https://cdn.kurzagin.com/anime/covers/10793.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/10793-xmJErpujAeD7.jpg', 'TV', 'completed', 22, 22, 9, '["Action","Drama","Mecha","Psychological","Romance","Sci-Fi"]', 'Production I.G', 2011, 'Shuu''s entire world was shattered after a meteorite crashed into Japan, unleashing the lethal Apocalypse Virus. The chaos and anarchy born of the outbreak cost Shuu his family and reduced him to a timid, fearful shell of the boy he''d once been. His life took another unexpected turn after a chance encounter with the stunning pop star, Inori. This mysterious beauty introduced Shuu to the King''s Right Hand: a genetic mutation that allows him to reach into hearts of mortals and turn them into weapons.

Shuu finds himself caught in the crossfire between those who desperately seek his newfound strength. On one side lurks a clandestine government agency, and on the other, Inori and the spirited band of rebels known as Funeral Parlor. The choice is Shuu''s to make - and the world is his to change.

(Source: Funimation)', '2026-10-07T03:17:13.935Z', '2026-10-07T03:17:13.935Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('02ae7ba3-9a3b-4063-a751-c7a6bac740a1', 21851, 'Armed Girl''s Machiavellism', 'Busou Shoujo Machiavellianism', '武装少女マキャヴェリズム', 'https://cdn.kurzagin.com/anime/covers/21851.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21851-WlOu4rhpbflw.jpg', 'TV', 'completed', 12, 12, 8, '["Action","Comedy","Ecchi","Romance"]', 'SILVER LINK.', 2017, 'Originally, Aichi Coexistence Private Academy was an all-girls school for privileged young ladies until it was decided that it would become co-ed. The fearful girls were permitted to bring weapons to protect themselves, and then a vigilante group was established called the “Supreme Five Swords." When rebellious Nomura Fudou is sent to the academy, he is given two options: act and dress like a girl or be expelled!

(Source: Sentai Filmworks)', '2026-10-09T09:45:54.661Z', '2026-10-09T09:45:54.661Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('08939286-b9c1-463f-830c-1ce1ca68e7ff', 129190, 'The Genius Prince''s Guide to Raising a Nation Out of Debt', 'Tensai Ouji no Akaji Kokka Saisei Jutsu', '天才王子の赤字国家再生術', 'https://cdn.kurzagin.com/anime/covers/129190.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/129190-UNHT31z95c23.jpg', 'TV', 'completed', 12, 12, 8, '["Comedy","Fantasy"]', 'Yokohama Animation Lab', 2022, 'Once upon a time in a far away land there lived a prince, a genius prince. The genius prince fought alongside his people and led them to a great many triumphs. However, truth be told, he just wants to let everything go and live in tranquility.

(Source: Funimation)', '2026-10-07T02:46:39.417Z', '2026-10-07T02:46:39.417Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('76382194-5be7-498c-93b8-64cccb456159', 153629, 'The Magical Revolution of the Reincarnated Princess and the Genius Young Lady', 'Tensei Oujo to Tensai Reijou no Mahou Kakumei', '転生王女と天才令嬢の魔法革命', 'https://cdn.kurzagin.com/anime/covers/153629.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/153629-dliAKZ1VM2OQ.jpg', 'TV', 'completed', 12, 12, 8, '["Fantasy","Romance"]', 'diomedéa', 2023, 'Despite her supposed ineptitude with regular magic, Princess Anisphia defies the aristocracy’s expectations by developing “magicology,” a unique magical theory based on memories from her past life. One day, she witnesses the brilliant noblewoman Euphyllia unjustly stripped of her title as the kingdom’s next monarch. That’s when Anisphia concocts a plan to help Euphyllia regain her good name-which somehow involves them living together and researching magic! Little do these two ladies know, however, that their chance encounter will alter not only their own futures, but those of the kingdom...and the entire world! 

(Source: Yen Press)', '2026-10-07T02:47:37.348Z', '2026-10-07T02:47:37.348Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('16f6d287-1ead-4c02-bf1d-d2a1cb972c9f', 162694, 'The 100 Girlfriends Who Really, Really, Really, Really, REALLY Love You', 'Kimi no Koto ga Dai Dai Dai Dai Daisuki na 100-nin no Kanojo', '君のことが大大大大大好きな100人の彼女', 'https://cdn.kurzagin.com/anime/covers/162694.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/162694-PzaToQuFdpsr.jpg', 'TV', 'completed', 12, 12, 8, '["Comedy","Ecchi","Romance"]', 'Bibury Animation Studios', 2023, 'Rentarou Aijou was rejected 100 times in middle school. He visits a shrine and prays for better luck in high school. The God of Love appears and promises that he’ll soon meet 100 people he’s destined to date. But there’s a catch—once destiny introduces someone to him, the two must happily love each other. If they don’t, they’ll die. What will befall Rentarou and his 100 girlfriends in high school?

(Source: Crunchyroll)', '2026-10-07T02:49:01.258Z', '2026-10-07T02:49:01.258Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('4256be9c-b2b1-47f7-96d9-c8855d08c083', 180746, 'SHIBOYUGI: Playing Death Games to Put Food on the Table', 'Shibou Yuugi de Meshi wo Kuu.', '死亡遊戯で飯を食う。', 'https://cdn.kurzagin.com/anime/covers/180746.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/180746-AyfiOMkuHegF.jpg', 'TV', 'planning', 0, 11, NULL, '["Action","Drama","Mystery","Psychological","Thriller"]', 'Studio DEEN', 2026, 'At just seventeen, Yuki is a professional death game player. She’s survived enough rounds to know that survival is calculation, not luck—and that failure is final. For most players, the games are a nightmare with no escape. For Yuki, they’re simply business. Yet in a world where rooms turn into graves and every choice could be her last, even experience offers no protection.

(Source: Crunchyroll)

Note: The first episode aired with a runtime of ~47 minutes as opposed to the standard 24 minute long episode.', '2026-10-07T02:50:20.195Z', '2026-10-07T02:50:20.195Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('5cbd4ce0-155b-453a-bc6c-bb39b69f5ac6', 16067, 'A Lull in the Sea', 'Nagi no Asukara', '凪のあすから', 'https://cdn.kurzagin.com/anime/covers/16067.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/16067.jpg', 'TV', 'completed', 26, 26, 8, '["Drama","Fantasy","Romance","Slice of Life"]', 'P.A.WORKS', 2013, 'Since long ago, human civilization had lived on the ocean floor. However, there were many humans who wanted to live above the surface and they moved to land creating a fundamental separation between the two. After their school closes down, four 14-year-old middle school students from the sea village, Shioshishio, have to attend Mihama Middle School on the surface. What follows is their struggles to adjust to a new environment and the relationships between the sea and land people, while dealing with their own newfound feelings that have just started appearing with the end of their childhood.

(Source: Wikipedia)', '2026-10-07T02:53:49.878Z', '2026-10-07T02:53:49.878Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('b566952f-4a04-4f43-b715-a59888298e65', 20458, 'The Irregular at Magic High School', 'Mahouka Koukou no Rettousei', '魔法科高校の劣等生', 'https://cdn.kurzagin.com/anime/covers/20458.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20458-6sHThFCwyd1T.jpg', 'TV', 'completed', 26, 26, 8, '["Action","Romance","Sci-Fi","Supernatural"]', 'MADHOUSE', 2014, 'Magic is a product of neither legends nor fairy tales, but instead has become a technology of reality since a time unknown to people. Supernatural power became a technology systematized through magic, while magic became a technical skill. A "Supernatural Power User" became a "Magic Technician." Magic Technicians (in short, Magicians) are nurtured through Magic High Schools and Universities.

This is a story about: 

Tatsuya, a defective elder brother low achiever.
Miyuki, a perfect, flawless younger sister high achiever.
After both siblings entered a Magic High School,
The stage of daily turbulence was unveiled—.', '2026-10-07T02:54:19.165Z', '2026-10-07T02:54:19.165Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('8451cccf-51ef-4dd2-be98-4e85450b79b3', 21092, 'Chivalry of a Failed Knight', 'Rakudai Kishi no Cavalry', '落第騎士の英雄譚（キャバルリィ）', 'https://cdn.kurzagin.com/anime/covers/21092.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n21092-WTe5Lx5sLQy1.jpg', 'TV', 'completed', 12, 12, 8, '["Action","Ecchi","Fantasy","Romance"]', 'SILVER LINK.', 2015, 'The "school sword action" story revolves around Magic Knights, modern magic-users who fight with weapons converted from their souls. Ikki Kurogane goes to a school for these Magic Knights, but he is the "Failed Knight" or "Worst One" who is failing because he has no magical skills. However, one day, he is challenged to a duel by Stella, a foreign princess and the "Number One" student. In this duel, "the loser must be obedient for life."

(Source: Anime News Network)', '2026-10-07T02:55:16.626Z', '2026-10-07T02:55:16.626Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('a2774ed5-14df-4d5b-9ea0-803c00a8372a', 20457, 'Black Bullet', 'Black Bullet', 'ブラック・ブレット', 'https://cdn.kurzagin.com/anime/covers/20457.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20457.jpg', 'TV', 'completed', 13, 13, 8, '["Action","Drama","Mystery","Sci-Fi"]', 'Kinema Citrus', 2014, 'The Gastrea virus spreads like wildfire, causing each infected host to rapidly mutate, gaining new powers and abilities with every stage of development, even while they continue to attack, kill and infect multiple new hosts. Unable to fight a pandemic enemy that turns defenders into adversaries, the shocked remnants of the human race are forced to retreat into cities surrounded by giant monoliths made of Varanium, one of the few materials that can stop the Gastrea. Now mankind''s last hope lies in the Cursed Children: young girls infected with the virus who have managed to retain a hold on their humanity. Paired with a partner, they alone have the strength to take on a Gastrea in one-on-one combat. But the very thing that gives them power is a ticking time bomb, so even as they protect humanity, they are also feared and shunned. Are they Girls? Monsters? Or Mankind''s Ultimate Salvation?

(Source: Sentai Filmworks)', '2026-10-07T02:55:47.842Z', '2026-10-07T02:55:47.842Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('86c7bde2-2bed-4456-af5a-2e0d6e5253ba', 20829, 'Seraph of the End: Vampire Reign', 'Owari no Seraph', '終わりのセラフ', 'https://cdn.kurzagin.com/anime/covers/20829.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20829-1BRrVJAxlEKT.jpg', 'TV', 'completed', 12, 12, 8, '["Action","Drama","Fantasy","Mystery","Supernatural"]', 'WIT STUDIO', 2015, 'The story takes place in a world where an unknown virus has killed the entire human population except for children under 13. Those children were then enslaved by vampires. The manga centers on Yuichiro Hyakuya, a human who dreams of becoming strong enough to kill all vampires.

(Source: Anime News Network)', '2026-10-07T02:56:19.720Z', '2026-10-07T02:56:19.720Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('9a146cbb-b55b-4087-8a95-95f04e96eb47', 20993, 'Seraph of the End: Battle in Nagoya', 'Owari no Seraph: Nagoya Kessen-hen', '終わりのセラフ　名古屋決戦編', 'https://cdn.kurzagin.com/anime/covers/20993.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20993-pZacVGnE1F2L.jpg', 'TV', 'completed', 12, 12, 8, '["Action","Drama","Fantasy","Supernatural"]', 'WIT STUDIO', 2015, 'Yuuichirou has reunited with Mikaela at the Shinjuku Battle. But Mikaela was turned into a vampire... To save the "family," and to protect his fellow members, Yuuichirou needed to gain knowledge and power. He searched for ways to bring back vampire to human beings, and at the same time, trained hard working on the Cursed Gear. 

Meanwhile, Kureto calls Guren and tells him a shocking truth. That in one month, the main unit of the vampire will start attacking Tokyo. To get a head start against vampires, Kureto orders Guren to go to Nagoya. The noble extermination mission is about to open fire!

(Source: Official website)', '2026-10-07T02:56:43.350Z', '2026-10-07T02:56:43.350Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('8b1b92d7-c6c4-4c3f-bd24-0f919c53c70d', 20623, 'Parasyte -the maxim-', 'Kiseijuu: Sei no Kakuritsu', '寄生獣 セイの格率', 'https://cdn.kurzagin.com/anime/covers/20623.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20623-xb9PPf8rGOsG.jpg', 'TV', 'completed', 24, 24, 7, '["Action","Drama","Horror","Psychological","Sci-Fi"]', 'MADHOUSE', 2014, 'They arrive in silence and darkness. They descend from the skies. They have a hunger for human flesh. They are everywhere. They are parasites, alien creatures who must invade–and take control of–a human host to survive. And once they have infected their victims, they can assume any deadly form they choose: monsters with giant teeth, winged demons, creatures with blades for hands. But most have chosen to conceal their lethal purpose behind ordinary human faces. So no one knows their secret–except an ordinary high school student. Shin is battling for control of his own body against an alien parasite, but can he find a way to warn humanity of the horrors to come?

(Source: Del Rey)', '2026-10-07T02:57:35.834Z', '2026-10-07T02:57:35.834Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('eefcd098-d6d4-4492-b09f-15c6a47976cb', 20613, 'Akame ga Kill!', 'Akame ga Kill!', 'アカメが斬る！', 'https://cdn.kurzagin.com/anime/covers/20613.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20613-CoEQF4qKiWDX.jpg', 'TV', 'completed', 24, 24, 8, '["Action","Adventure","Drama","Fantasy","Horror","Psychological","Thriller"]', 'WHITE FOX', 2014, 'In a land where corruption rules and a ruthless Prime Minister has turned the puppet Emperor''s armies of soldiers, assassins and secret police against the people, only one force dares to stand against them: Night Raid, an elite team of relentless killers, each equipped with an Imperial Arm - legendary weapons with unique and incredible powers created in the distant past.

Rescued from a fate worse than death by Night Raid, young Tatsumi is offered the chance to join their lethal ranks… but it''s a deadly choice, as few can master an Imperial Arm and even fewer survive when two Arms go against each other in combat. The battle is on, and only the strongest will make it out alive.

(Source: Sentai Filmworks)', '2026-10-07T02:58:33.064Z', '2026-10-07T02:58:33.064Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('1f4db18a-b96c-47c5-8345-f2196b1ff3fd', 20954, 'A Silent Voice', 'Koe no Katachi', '聲の形', 'https://cdn.kurzagin.com/anime/covers/20954.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20954-f30bHMXa5Qoe.jpg', 'MOVIE', 'completed', 1, 1, 9, '["Drama","Romance","Slice of Life"]', 'Kyoto Animation', 2016, 'After transferring into a new school, a deaf girl, Shouko Nishimiya, is bullied by the popular Shouya Ishida. As Shouya continues to bully Shouko, the class turns its back on him. Shouko transfers and Shouya grows up as an outcast. Alone and depressed, the regretful Shouya finds Shouko to make amends.

(Source: Eleven Arts)', '2026-10-07T02:59:05.856Z', '2026-10-07T02:59:05.856Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('417413f9-72a3-4663-a67a-45d9a8d7bdc6', 128893, 'Hell’s Paradise', 'Jigokuraku', '地獄楽', 'https://cdn.kurzagin.com/anime/covers/128893.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/128893-pAA7PjY8l7dy.jpg', 'TV', 'completed', 13, 13, 8, '["Action","Adventure","Mystery","Supernatural"]', 'MAPPA', 2023, 'The Edo period is nearing its end. Gabimaru, a shinobi formerly known as the strongest in Iwagakure who is now a death row convict, is told that he will be acquitted and set free if he can bring back the Elixir of Life from an island that is rumored to be the Buddhist pure land Sukhavati. In hopes of reuniting with his beloved wife, Gabimaru heads to the island along with the executioner Yamada Asaemon Sagiri. Upon arriving there, they encounter other death row convicts in search of the Elixir of Life... as well as a host of unknown creatures, eerie manmade statues, and the hermits who rule the island. Can Gabimaru find the Elixir of Life on this mysterious island and make it back home alive?

(Source: Crunchyroll)', '2026-10-07T03:00:10.760Z', '2026-10-07T03:00:10.760Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('6ff3d807-9a1f-4649-ba3b-23624bc49c03', 166613, 'Hell’s Paradise Season 2', 'Jigokuraku 2nd Season', '地獄楽 第二期', 'https://cdn.kurzagin.com/anime/covers/166613.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/166613-drS86exJlIjG.jpg', 'TV', 'planning', 0, 12, NULL, '["Action","Adventure","Mystery","Supernatural"]', 'MAPPA', 2026, 'Seeking the key to the elixir of immortality, the group arrives at the fortress of the island''s monstrous ruler, the "Tensen." To survive and escape the island, cooperation becomes essential—regardless of whether one is a condemned criminal or an executioner.

Meanwhile, the shogunate orders additional landings on the island of the Immortal Realm, led by Shugen Yamada Asayemon. Among them are the Ishigakure clan, who share a past with Gabimaru.

Desperate to find the elixir and escape the island, Gabimaru and his companions face the Tensen in a battle that escalates into an all-out confrontation between humans and immortals!

(Source: Twin Engine, edited)', '2026-10-07T03:00:37.731Z', '2026-10-07T03:00:37.731Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('c18e8e81-ade8-4317-8065-91ec336e6ee8', 185407, 'Takopi''s Original Sin', 'Takopii no Genzai', 'タコピーの原罪', 'https://cdn.kurzagin.com/anime/covers/185407.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/185407-WOKgyadY4Pr1.jpg', 'ONA', 'completed', 6, 6, 10, '["Drama","Psychological","Sci-Fi"]', 'ENISHIYA', 2025, 'A Happy alien, Takopi, lands on Earth with one mission: to spread happiness! When he meets Shizuka, a lonely fourth grader, he vows to bring back her smile using his magical Happy Gadgets. But as he uncovers the pain in her life, Takopi learns that true happiness may require more than gadgets.

(Source: Crunchyroll)', '2026-10-20T12:48:35.705Z', '2026-10-20T12:48:35.705Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('dc5ff20c-9f14-45e9-9dfa-c39ea6d85a6a', 101759, 'The Promised Neverland', 'Yakusoku no Neverland', '約束のネバーランド', 'https://cdn.kurzagin.com/anime/covers/101759.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/101759-MhlCoeqnODso.jpg', 'TV', 'completed', 12, 12, 8, '["Drama","Fantasy","Horror","Mystery","Psychological","Thriller"]', 'CloverWorks', 2019, 'Emma, Norman and Ray are the brightest kids at the Grace Field House orphanage. And under the care of the woman they refer to as “Mom,” all the kids have enjoyed a comfortable life. Good food, clean clothes and the perfect environment to learn—what more could an orphan ask for? One day, though, Emma and Norman uncover the dark truth of the outside world they are forbidden from seeing.

(Source: VIZ Media)', '2026-10-04T14:46:36.193Z', '2026-10-04T14:46:36.193Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('5ecda361-e516-471f-99f3-2b054c2cf61b', 1535, 'Death Note', 'DEATH NOTE', 'DEATH NOTE', 'https://cdn.kurzagin.com/anime/covers/1535.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/1535.jpg', 'TV', 'completed', 37, 37, 8, '["Mystery","Psychological","Supernatural","Thriller"]', 'MADHOUSE', 2006, 'Light Yagami is a genius high school student who is about to learn about life through a book of death. When a bored shinigami, a God of Death, named Ryuk drops a black notepad called a Death Note, Light receives power over life and death with the stroke of a pen. Determined to use this dark gift for the best, Light sets out to rid the world of evil… namely, the people he believes to be evil. Should anyone hold such power?

The consequences of Light’s actions will set the world ablaze.

(Source: VIZ Media)', '2026-10-07T03:01:16.300Z', '2026-10-07T03:01:16.300Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('7d2a33bd-be17-475a-b53f-3b7dec1fd386', 8074, 'High School of the Dead', 'Gakuen Mokushiroku: HIGHSCHOOL OF THE DEAD', '学園黙示録HIGHSCHOOL OF THE DEAD', 'https://cdn.kurzagin.com/anime/covers/8074.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/8074-g8bVkL09nkdw.jpg', 'TV', 'completed', 12, 12, 7, '["Action","Drama","Ecchi","Horror","Romance","Supernatural"]', 'MADHOUSE', 2010, 'The lockers are splattered with blood, the student bodies are piling up and that''s not mystery meat they''re eating in the cafeteria… it''s the faculty! And that''s just the start of the worst day of school ever when a nightmarish virus is unleashed, turning humans into flesh eating zombies and converting Fujimi High School into a literal hell on Earth. Now it''s a crash course in survival, and the only test or skill that matters is the ability to keep moving, breathing and fighting. Because if nerds, jocks and the surviving staff can''t find a way to work together to escape this carnal house of education, they''re all going to end up on the menu. And that''s assuming there''s anyplace safe left to escape to.

(Source: Sentai Filmworks)', '2026-10-07T03:02:45.665Z', '2026-10-07T03:02:45.665Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('0aa611af-d267-49b6-8baf-b29fa3456fca', 14345, 'BTOOOM!', 'BTOOOM!', 'BTOOOM！', 'https://cdn.kurzagin.com/anime/covers/14345.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/14345-e2mFB7Z21V8s.jpg', 'TV', 'completed', 12, 12, 8, '["Action","Psychological","Sci-Fi"]', 'MADHOUSE', 2012, 'In the blink of the mind''s eye, Ryouta Sakamoto suddenly finds himself transported from playing the hit Btoom! video game to being stranded on a mysterious island, equipped with a day''s worth of provisions, a bag of bombs, a strange crystal embedded in his left hand and a huge gaping hole in his memory. But it doesn''t take long to figure out what''s going on, especially after the first person Ryouta meets tries to kill him. Someone is attempting to recreate the ultra-violent Btoom! game in real life, and the island has been filled with an army of other unwilling players, each armed with one of the multiple variants of explosive weapons called BIM. Fortunately, Ryouta''s an ace Btoom! player, but this insane version of the game has no reset switch or second lives, and there''s only one way off the island: kill seven other people before they can kill you! Can Ryouta repurpose his game based skills fast enough to survive? 
(Source: Sentai Filmworks)', '2026-10-07T03:03:03.682Z', '2026-10-07T03:03:03.682Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('a769a46f-ec22-4d47-ba93-93d17cb62931', 98659, 'Classroom of the Elite', 'Youkoso Jitsuryoku Shijou Shugi no Kyoushitsu e', 'ようこそ実力至上主義の教室へ', 'https://cdn.kurzagin.com/anime/covers/98659.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/98659-u46B5RCNl9il.jpg', 'TV', 'completed', 12, 12, 7, '["Drama","Psychological"]', 'Lerche', 2017, 'Koudo Ikusei Senior High School is a leading school with state-of-the-art facilities. The students there have the freedom to wear any hairstyle and bring any personal effects they desire. Koudo Ikusei is like a utopia, but the truth is that only the most superior students receive favorable treatment.

Kiyotaka Ayanokouji is a student of D-class, which is where the school dumps its "inferior" students in order to ridicule them. For a certain reason, Kiyotaka was careless on his entrance examination, and was put in D-class. After meeting Suzune Horikita and Kikyou Kushida, two other students in his class, Kiyotaka''s situation begins to change. 
(Source: Anime News Network, edited)', '2026-10-07T03:03:56.679Z', '2026-10-07T03:03:56.679Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('0a4bd9ac-d010-4027-b1a7-6574c787ef6f', 9756, 'Puella Magi Madoka Magica', 'Mahou Shoujo Madoka☆Magica', '魔法少女まどか☆マギカ', 'https://cdn.kurzagin.com/anime/covers/9756.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/9756-d5M8NffgJJHB.jpg', 'TV', 'completed', 12, 12, 7, '["Action","Drama","Fantasy","Mahou Shoujo","Psychological","Thriller"]', 'Shaft', 2011, 'One night, 14-year-old Madoka Kaname has a terrible nightmare - against the backdrop of a devastated city, she witnesses a girl fight a losing battle against a dreadful being lingering above, while a cat-like magical creature tells Madoka the only way to change such tragic outcome is for her to make a contract with him and become a magical girl. 
The next day, the teen''s dream seemingly becomes reality as the girl she saw in her dream - Homura - arrives at Mitakihara Middle School as a transfer student, mysteriously warning Madoka to stay just the way she is; but when later on she and her best friend Sayaka encounter the same cat-like magical creature from her dream - who introduces himself as Kyubey - the pair discovers that magical girls are real, and what''s more, they can choose to become one. All they must do is sign a contract with Kyubey and agree to take on the duty to fight abstract beings called ''witches'' that spread despair to the human world, and in return, each one of them will be granted any single wish they desire. However, as Homura''s omen suggests, there might be far more to becoming a magical girl than Madoka and Sayaka realize... 

Notes:
- Due to the 2011 Tōhoku earthquake and tsunami, the broadcasts of episodes 11 and 12 were delayed and were later aired as a double feature on April 21, 2011.', '2026-10-07T03:04:30.492Z', '2026-10-07T03:04:30.492Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('b4d2d7cf-a709-42d3-8b6e-c1aa4815063a', 100010, 'MAGICAL GIRL SITE', 'Mahou Shoujo Site', '魔法少女サイト', 'https://cdn.kurzagin.com/anime/covers/100010.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/100010-WZMK7JXMAi2i.jpg', 'TV', 'completed', 12, 12, 8, '["Action","Drama","Horror","Mahou Shoujo","Psychological","Supernatural"]', 'production doA', 2018, 'Asagiri Aya is a young girl who has fallen victim to bullies at her school. Looking for a way to escape her troubles, she looks to the internet for distraction, when a mysterious website called "Magical Girl Site" appears. Simply viewing the page is all it takes to hurtle Aya headlong into the deadly world of the Magical Girl Apocalypse. There, it’s fight or die, against a seemingly endless array of savagely adorable, frilly-skirted killing machines, each armed with magical powers and an unquenchable thirst for blood and chaos. 

(Source: Seven Seas Entertainment)', '2026-10-07T03:04:55.578Z', '2026-10-07T03:04:55.578Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('b5ac57bc-b7c8-4944-ba8f-97f9b08b5afc', 20853, 'ALDNOAH.ZERO Season 2', 'Aldnoah.Zero Part 2', 'アルドノア・ゼロ 第2クール', 'https://cdn.kurzagin.com/anime/covers/20853.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20853-Xli7nZSGFj00.jpg', 'TV', 'completed', 12, 12, 8, '["Action","Mecha","Sci-Fi"]', 'A-1 Pictures', 2015, 'Seeking for revenge, Count Saazbaum, a Martian, attacked the Earth. Later on, the war between the Terrans and Martians ended with Earth''s Terrans gaining the victory. However, nineteen months later, the battle between them continues. Martians still continues to invade the Earth and the Terrans to protect it.

(Source: Anime News Network)', '2026-10-04T15:25:02.948Z', '2026-10-04T15:25:02.948Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('20fa4cec-6fc0-450d-a637-65ac9eb3dcf1', 849, 'The Melancholy of Haruhi Suzumiya', 'Suzumiya Haruhi no Yuuutsu', '涼宮ハルヒの憂鬱', 'https://cdn.kurzagin.com/anime/covers/849.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/849-Cey4HHIDoeY2.jpg', 'TV', 'completed', 14, 14, 8, '["Comedy","Mystery","Sci-Fi","Slice of Life","Supernatural"]', 'Kyoto Animation', 2006, 'Kyon, your typical high school student, has long given up his belief in the supernatural. However, upon meeting Haruhi Suzumiya, he quickly finds out that it is the supernatural that she is interested in; aliens, time travelers and espers among other things. When Haruhi laments about the lack of intriguing clubs around school, Kyon inspires Haruhi to form her own club. As a result, the SOS Brigade is formed, a club which specializes in all that is the supernatural.
Much to his chagrin, Kyon, along with the silent bookworm, Yuki Nagato, the shy and timid Mikuru Asahina, and the perpetually smiling Itsuki Koizumi, are recruited as members. The story follows the crazy adventures that these four endure under their whimsical leader, Haruhi. The story is based on the light novels by Nagaru Tanigawa.
Note: This entry is for the original 14-episode 2006 airing. The series was further expanded and reordered into a 28-episode series in 2009.', '2026-10-07T03:06:05.542Z', '2026-10-07T03:06:05.542Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('d1f96116-2ada-49cb-9f9c-0e22f876e50d', 5680, 'K-ON!', 'K-ON!', 'けいおん!', 'https://cdn.kurzagin.com/anime/covers/5680.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/5680-Mc9n4eFI4i0Y.jpg', 'TV', 'completed', 13, 13, 10, '["Comedy","Music","Slice of Life"]', 'Kyoto Animation', 2009, 'Hirasawa Yui, a young, carefree girl entering high school, has her imagination instantly captured when she sees a poster advertising the ‘Light Music Club’. Being the carefree girl that she is, she quickly signs up. However, Yui has a problem, she is unable to play an instrument.
When Yui goes to the clubroom to explain, she''s greeted by the other members: Ritsu, Mio and Tsumugi. Although disheartened at Yui’s lack of musical know-how, they still try to convince her to stay to prevent the club’s disbandment. After playing Yui a short piece which re-ignites her imagination, they succeed in keeping their new member and guitarist.
Along with the tasks of school and homework, Yui begins to learn the guitar with the help of the other band members, experiencing many mishaps along the way. However, with the school-festival drawing near and Yui getting stuck with her practice, will the Light Music Club be ready in time for their debut?
(Source: MAL Rewrite)', '2026-10-07T03:06:25.752Z', '2026-10-07T03:06:25.752Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('b2fb0ae4-16a2-477a-b91b-621b11d8d9cc', 7791, 'K-ON! Season 2', 'K-ON!!', 'けいおん!!', 'https://cdn.kurzagin.com/anime/covers/7791.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/7791-XUCEPg0lbD1K.jpg', 'TV', 'completed', 26, 26, 10, '["Comedy","Music","Slice of Life"]', 'Kyoto Animation', 2010, 'It is the new year, which means that the senior members of the Light Music Club are now third-years, with Azusa Nakano being the only second-year. The seniors soon realize that Azusa will be the only member left once they graduate and decide to recruit new members. Despite trying many methods of attracting underclassmen—handing out fliers, bringing people into the clubroom, and performing at the welcoming ceremony—there are no signs of anyone that plans to join.

While heading to the clubroom, Azusa overhears Yui Hirasawa say that the club is fine with only five people and that they can do many fun things together. Changing her mind, she decides that they do not need to recruit any members for the time being.

K-On!! revolves around the members of the Light Music Club as they experience their daily high school life. From rehearsing for concerts to just messing around, they are ready to make their last year together an exciting one!

(Source: MAL Rewrite)', '2026-10-07T03:06:45.313Z', '2026-10-07T03:06:45.313Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('4dde97c9-bad4-4340-bf26-5adfda5c6958', 9617, 'K-ON!: The Movie', 'K-ON! Movie', '映画けいおん！', 'https://cdn.kurzagin.com/anime/covers/9617.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/9617-MhdXJVRG49cA.jpg', 'MOVIE', 'completed', 1, 1, 10, '["Comedy","Music","Slice of Life"]', 'Kyoto Animation', 2011, 'With graduation right around the corner, every member of the Light Music Club except for Azusa will be leaving for good. But the girls aren’t going to let something as silly as graduation tear them apart! For their final hurrah, the girls are going on the ultimate vacation tour— all the way to London! Their overseas journey will lead them on a trip of discovery and friendship as they take the stage one last time for their final encore together.
(Source: Sentai Filmworks)', '2026-10-07T03:07:13.506Z', '2026-10-07T03:07:13.506Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('97823e6d-048e-4024-a977-8b40d13bc295', 21584, 'Love Live! Sunshine!!', 'Love Live! Sunshine!!', 'ラブライブ！サンシャイン!!', 'https://cdn.kurzagin.com/anime/covers/21584.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21584-mvyzC8r4cq6E.jpg', 'TV', 'completed', 13, 13, 8, '["Music","Slice of Life"]', 'Sunrise', 2016, 'Uranohoshi Girls’ High School, a private school in the seaside neighborhood of Uchiura at Numazu city, Shizuoka prefecture. A small high school in a corner of Suruga Bay, it is home to nine teens, led by second-year student Chika Takami, driven by one seriously big dream: To become the next generation of bright, sparkling “school idols”! As long as we don’t give up, any dream can come true... All we have to do now is keep pushing hard for fame and glory! Now their “School Idol Project” begins to make their dreams come true!

(Source: Official Website)', '2026-10-07T03:07:33.070Z', '2026-10-07T03:07:33.070Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('cadd4496-ebc2-4f7f-81c9-4c3c25843853', 21202, 'KONOSUBA -God''s blessing on this wonderful world!', 'Kono Subarashii Sekai ni Shukufuku wo!', 'この素晴らしい世界に祝福を！', 'https://cdn.kurzagin.com/anime/covers/21202.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21202-UWijdV7RMnXo.jpg', 'TV', 'completed', 10, 10, 9, '["Adventure","Comedy","Ecchi","Fantasy"]', 'Studio DEEN', 2016, 'Kazuma Satou decides that today is the day to get out of the house for a bit. Since he dies, pointlessly, it''s clearly a bad choice. The goddess who greets him in the afterlife, however, offers him a chance to be reborn in a world not unlike that of a video game, and as a bonus she''ll even throw in a cool item or power! Can''t possibly be a bad choice, right? Except he arrives with no money at all, dead average skills, and his "bonus" isn''t useful at all--since he picked the goddess, Aqua, herself. How are the two of them supposed to defeat the evil Devil King and live happily ever after? Well, for them, it probably starts with day laboring rather than adventuring. And it''s only going to get more disappointing from there!

(Source: Crunchyroll)', '2026-10-07T03:17:37.386Z', '2026-10-07T03:17:37.386Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('945d5f3a-993f-4203-984b-e2e354ed6895', 122292, 'Yuki Yuna is a Hero: The Great Mankai Chapter', 'Yuuki Yuuna wa Yuusha de Aru: Dai-Mankai no Shou', '結城友奈は勇者である-大満開の章-', 'https://cdn.kurzagin.com/anime/covers/122292.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/122292-lDCKcE35BOVo.jpg', 'TV', 'completed', 12, 12, 10, '["Action","Drama","Fantasy","Mahou Shoujo","Psychological"]', 'Studio Gokumi', 2021, 'The magical girls of the Sanshu Middle School Hero Club have one goal: to make people smile whenever they can and to always help those in need. Through teamwork and the help of their magical powers, Yuna, Mimori, Fuu, Itsuki, Karin and Sonoko have vanquished deadly Vertexes, recovered a missing friend and balanced their lives as magical girls and regular middle school students. Now a new adventure begins, one that will test their skills and their bond as friends alike.

(Source: Sentai Filmworks)', '2026-10-04T14:30:46.032Z', '2026-10-04T14:30:46.032Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('ef4cfb23-709f-4ff6-9e82-960da662ee88', 139587, 'Reincarnated as a Sword', 'Tensei Shitara Ken Deshita', '転生したら剣でした', 'https://cdn.kurzagin.com/anime/covers/139587.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/139587-XFbotQOPcLC4.jpg', 'ONA', 'completed', 12, 12, 7, '["Action","Adventure","Fantasy"]', 'C2C', 2022, 'Some isekai protagonists are reincarnated as powerful warriors or skilled wizards, but our protagonist was reborn in another life as a sentient sword! He’s taken up by Fran, a desperate girl fleeing evil-doers intent on selling her into slavery. With her new weapon’s help and guidance, she’s able to strike down her captors and secure her freedom. Together, this unconventional master-student duo embark on an epic journey to liberate those in need and exact justice on the cruel of heart.

(Source: Sentai Filmworks)

Note: Episode 1 was streamed in advance on September 28, 2022 on AbemaTV. The regular TV broadcast began on October 5, 2022.', '2026-10-04T00:09:32.396Z', '2026-10-04T00:09:32.396Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('2a9f6362-892f-4aea-8393-557478898463', 112608, 'I''ve Been Killing Slimes for 300 Years and Maxed Out My Level', 'Slime Taoshite 300-nen, Shiranai Uchi ni Level MAX ni Nattemashita', 'スライム倒して300年、知らないうちにレベルMAXになってました', 'https://cdn.kurzagin.com/anime/covers/112608.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/112608-MGv0rMEhEWq5.jpg', 'TV', 'completed', 12, 12, 7, '["Adventure","Comedy","Fantasy","Slice of Life"]', 'REVOROOT', 2021, 'An at-home comedy about a powerful girl who doesn’t work too hard!(⋈◍ ˃ᴗ˂ ◍)。✧♡

After dying of overwork in the real world, I’m reincarnated as an immortal witch, and I spend 300 years enjoying a relaxing life. At some point, though, I end up at level 99!
All those years spent killing slimes to make the money to pay the bills gave me a ton of experience points… Rumors of the level 99 witch spread, and soon I’m up to my ears in curious adventurers, duelist dragons, and even a monster girl calling me her mom! “This isn’t a dojo, so don’t come here to fight me…!”

I’ve never been on an adventure, but I’m the strongest in the world… What’s going to happen to my relaxing life?!

(Source: Crunchyroll)', '2026-10-04T00:10:43.277Z', '2026-10-04T00:10:43.277Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('0f80979e-2ada-4d05-8f2c-2a05e1725359', 101280, 'That Time I Got Reincarnated as a Slime', 'Tensei Shitara Slime Datta Ken', '転生したらスライムだった件', 'https://cdn.kurzagin.com/anime/covers/101280.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/101280-9t7J3774n955.jpg', 'TV', 'completed', 24, 24, 8, '["Action","Adventure","Comedy","Fantasy"]', '8-bit', 2018, 'Lonely thirty-seven-year-old Satoru Mikami is stuck in a dead-end job, unhappy with his mundane life, but after dying at the hands of a robber, he awakens to a fresh start in a fantasy realm...as a slime monster! As he acclimates to his goopy new existence, his exploits with the other monsters set off a chain of events that will change his new world forever!

(Source: Yen Press)', '2026-10-04T00:11:13.651Z', '2026-10-04T00:11:13.651Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('12990705-4cf6-4d4e-9d85-5d4a1504901a', 108511, 'That Time I Got Reincarnated as a Slime Season 2', 'Tensei Shitara Slime Datta Ken 2nd Season', '転生したらスライムだった件 第2期', 'https://cdn.kurzagin.com/anime/covers/108511.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/108511-lcP2j3XlKERG.jpg', 'TV', 'completed', 12, 12, 8, '["Action","Adventure","Comedy","Fantasy"]', '8-bit', 2021, 'Now that the Jura Tempest Alliance is growing even further, they will now be meeting the animal kingdom of Eurazania, reuniting with King Gazel, rising tensions between monsters and humans, and Rimuru encountering the strongest enemy he’s ever faced.

(Source: Funimation)', '2026-10-04T00:11:47.194Z', '2026-10-04T00:11:47.194Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('79e47168-0695-45fb-8f71-f46deb49e79a', 156822, 'That Time I Got Reincarnated as a Slime Season 3', 'Tensei Shitara Slime Datta Ken 3rd Season', '転生したらスライムだった件 第3期', 'https://cdn.kurzagin.com/anime/covers/156822.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/156822-y0wPQIl3AHDA.jpg', 'TV', 'completed', 24, 24, 8, '["Action","Adventure","Comedy","Fantasy"]', '8-bit', 2024, 'Rimuru has officially become a Demon Lord after defeating Clayman. Following Walpurgis, the Demon Lords'' banquet, Rimuru''s domain is expanded to include the entire Great Forest of Jura. Anticipating a flood of representatives from all races showing up to pay their respects, Rimuru decides to throw a festival to commemorate the opening of Tempest, using it as an opportunity to gain new citizens and present Demon Lord Rimuru to the world. Meanwhile, in the Holy Empire of Lubelius, home base of the monster-hating cult of Luminism, Holy Knight Captain Hinata receives a message from Rimuru. But the message is actually a fabricated declaration of war sent by some unknown party. Upon learning that Hinata is heading for Tempest, Rimuru makes a decision... Thus begins a new challenge for Rimuru, striving to distinguish friend from foe in his pursuit of the ideal nation where humans and monsters can prosper together. 
(Source: Crunchyroll)', '2026-10-04T00:12:22.224Z', '2026-10-04T00:12:22.224Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('d5485bc6-6745-40fc-820a-d68d60e87fda', 182205, 'That Time I Got Reincarnated as a Slime Season 4', 'Tensei Shitara Slime Datta Ken 4th Season Part 1 & 2', '転生したらスライムだった件 第4期 第1&2クール', 'https://cdn.kurzagin.com/anime/covers/182205.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/182205-fRUoKv6f2JAq.jpg', 'TV', 'completed', 24, 24, 8, '["Action","Adventure","Comedy","Fantasy"]', '8-bit', 2026, 'Demon Lord Rimuru''s dream of creating an alliance between humans and monsters takes a step closer to being realized. As Tempest continues to prosper, Granville Rozzo and his granddaughter, Maribel Rozzo, clash with Demon Lord Rimuru over their plan to protect mankind by ruling over them. Meanwhile, in El Dorado, Demon Lord Leon works toward goals of his own. The awakening of a new Hero draws near!

(Source: Crunchyroll News)', '2026-10-04T00:14:06.836Z', '2026-10-04T00:14:22.180Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('e441f415-b820-4e25-9284-ae9abaf5533a', 139498, 'That Time I Got Reincarnated as a Slime the Movie: Scarlet Bond', 'Tensei Shitara Slime Datta Ken: Guren no Kizuna-hen', '劇場版 転生したらスライムだった件 紅蓮の絆編', 'https://cdn.kurzagin.com/anime/covers/139498.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/139498-f6sMOwOTBQv4.jpg', 'MOVIE', 'completed', 1, 1, 7, '["Action","Adventure","Comedy","Fantasy"]', '8-bit', 2022, 'A long-running conspiracy is swirling over a mysterious power known as “Queen” in Raja, a small country west of Tempest. When a slime who evolved into a Demon Lord named Rimuru Tempest crosses paths with Hiiro, a survivor of the Ogre race, an incredible adventure packed with new characters begins. The power of bonds will be put to the test!


(Source: Crunchyroll)', '2026-10-04T00:15:05.709Z', '2026-10-04T00:15:05.709Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('9e6e2ba5-072b-4c2e-a2d8-3e4155d78494', 112151, 'Demon Slayer -Kimetsu no Yaiba- The Movie: Mugen Train', 'Kimetsu no Yaiba: Mugen Ressha-hen', '鬼滅の刃 無限列車編', 'https://cdn.kurzagin.com/anime/covers/112151.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/112151-eHCBz19nf2yC.jpg', 'MOVIE', 'completed', 1, 1, 10, '["Action","Adventure","Drama","Fantasy","Mystery","Supernatural"]', 'ufotable', 2020, 'This Demon Slayer movie sees Tanjiro Kamado and friends from the Demon Slayer corps board the Infinity Train on a new mission to investigate a mysterious series of disappearances, perpetrated by a demon who has been tormenting people and killing the demon slayers who oppose it.', '2026-10-04T15:08:16.428Z', '2026-10-04T15:08:16.428Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('b3411eb9-8c2a-4424-959f-206680b6de53', 108465, 'Mushoku Tensei: Jobless Reincarnation', 'Mushoku Tensei: Isekai Ittara Honki Dasu', '無職転生 ～異世界行ったら本気だす～', 'https://cdn.kurzagin.com/anime/covers/108465.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/108465-RgsRpTMhP9Sv.jpg', 'TV', 'completed', 11, 11, 7, '["Adventure","Drama","Ecchi","Fantasy"]', 'Studio Bind', 2021, 'When a 34-year-old underachiever gets run over by a bus, his story doesn’t end there. Reincarnated in a new world as an infant, Rudeus will seize every opportunity to live the life he’s always wanted. Armed with new friends, some freshly acquired magical abilities, and the courage to do the things he’s always dreamed of, he’s embarking on an epic adventure—with all of his past experience intact!

(Source: Funimation, edited)

Note: The anime pre-screened its 1st and 2nd episode starting on the 27th of December on the Nico Nico Live Broadcasting and D Anime Store services', '2026-10-04T00:15:33.883Z', '2026-10-04T00:15:33.883Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('9d1bc257-25e0-431a-84b8-c00bb1670b1b', 146065, 'Mushoku Tensei: Jobless Reincarnation Season 2', 'Mushoku Tensei II: Isekai Ittara Honki Dasu', '無職転生Ⅱ ～異世界行ったら本気だす～', 'https://cdn.kurzagin.com/anime/covers/146065.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/146065-33RDijfuxLLk.jpg', 'TV', 'completed', 13, 13, 7, '["Adventure","Drama","Ecchi","Fantasy"]', 'Studio Bind', 2023, 'After his relationship with Eris Boreas Greyrat reaches new heights, Rudeus Greyrat is ecstatic. Unfortunately, his joy is short-lived, as Eris suddenly abandons him to embark on her own journey. Believing that Eris has lost all interest in him, a heartbroken and depressed Rudeus sets forth to the Northern Territories. With his sole goal being to locate his mother on the vast continent, Rudeus wonders if persisting through daily life is worth the pain, falling into a robotic routine as he endlessly ruminates on his lost love.

However, the dangers of the North soon prove that one cannot survive with a dulled mind. While on a quest with the party Counter Arrow, with whom he recently became acquainted, Rudeus has a brush with death—an experience that forces him to finally snap out of his despair. With his newfound teammates, Rudeus rediscovers the pleasure of daily adventuring and moves forward with his original goal of living his second lease on life to the fullest.

(Source: MAL Rewrite)

Note: Includes episode 0, Shugo Jutsushi Fitz.', '2026-10-04T00:15:52.935Z', '2026-10-04T00:15:52.935Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('6d2db2d8-4efd-4592-bd9f-18ed3fee4959', 178789, 'Mushoku Tensei: Jobless Reincarnation Season 3', 'Mushoku Tensei III: Isekai Ittara Honki Dasu', '無職転生Ⅲ ～異世界行ったら本気だす～', 'https://cdn.kurzagin.com/anime/covers/178789.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/178789-9nHWmoRLlcLu.jpg', 'TV', 'planning', 0, 14, NULL, '["Adventure","Drama","Ecchi","Fantasy"]', 'Studio Bind', 2026, 'The third season of Mushoku Tensei: Isekai Ittara Honki Dasu.', '2026-10-04T00:16:11.209Z', '2026-10-04T00:16:11.209Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('7a34f5ed-fe06-4baa-b6cc-5a4c7848c60f', 154587, 'Frieren: Beyond Journey’s End', 'Sousou no Frieren', '葬送のフリーレン', 'https://cdn.kurzagin.com/anime/covers/154587.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/154587-ivXNJ23SM1xB.jpg', 'TV', 'completed', 28, 28, 9, '["Adventure","Drama","Fantasy"]', 'MADHOUSE', 2023, 'The adventure is over but life goes on for an elf mage just beginning to learn what living is all about. Elf mage Frieren and her courageous fellow adventurers have defeated the Demon King and brought peace to the land. But Frieren will long outlive the rest of her former party. How will she come to understand what life means to the people around her? Decades after their victory, the funeral of one her friends confronts Frieren with her own near immortality. Frieren sets out to fulfill the last wishes of her comrades and finds herself beginning a new adventure…

(Source: Crunchyroll)', '2026-10-04T00:16:44.699Z', '2026-10-04T00:16:44.699Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('7b206a29-2911-4ba6-96da-8af930966ba8', 182255, 'Frieren: Beyond Journey’s End Season 2', 'Sousou no Frieren 2nd Season', '葬送のフリーレン 第2期', 'https://cdn.kurzagin.com/anime/covers/182255.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/182255-wyHvp6zJbWsO.jpg', 'TV', 'planning', 0, 10, NULL, '["Adventure","Drama","Fantasy"]', 'MADHOUSE', 2026, 'Following the First-Class Mage Exam, the trio—elven mage Frieren, warrior Stark, and first-class mage Fern—gains access to the dangerous Northern Plateau. As the party presses onward toward Aureole, formidable adversaries force Stark to confront his insecurities, solidifying his resolve and his role as the party''s frontliner. Meanwhile, Fern continues to cherish the gifts she has been blessed with throughout her life, each a reminder of those she holds dear.

Frieren—still honoring her vow to understand humanity—revisits memories of her journey with the Hero''s party and her fleeting encounter with a legendary figure. As she reflects on the passage of time, the elven mage quietly questions whether she has truly changed, yet in the small, almost subtle choices that she makes, there are signs that she might have become more human than she realizes.

(Source: MAL Rewrite)', '2026-10-04T00:17:02.087Z', '2026-10-04T00:17:02.087Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('f9ef3592-4a6b-4fb1-b4cb-77d084b21713', 209939, 'Sousou no Frieren 3rd Season', 'Sousou no Frieren 3rd Season', '葬送のフリーレン 第3期', 'https://cdn.kurzagin.com/anime/covers/209939.avif', NULL, 'TV', 'planning', 0, NULL, NULL, '["Adventure","Drama","Fantasy"]', 'MADHOUSE', 2027, 'The third season of Sousou no Frieren.', '2026-10-04T00:17:22.194Z', '2026-10-04T00:17:22.194Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('1c67c7cb-e2cf-4c39-b0e2-b20d36aa96fe', 20832, 'Overlord', 'Overlord', 'オーバーロード', 'https://cdn.kurzagin.com/anime/covers/20832.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20832-NswCiSYMoI2k.jpg', 'TV', 'completed', 13, 13, 9, '["Action","Adventure","Fantasy"]', 'MADHOUSE', 2015, 'The story takes place in the year 2138 when virtual reality gaming is booming. Yggdrasil, a popular online game is quietly shut down one day. However, the protagonist Momonga decides to not log out. Momonga is then transformed into the image of a skeleton as "the most powerful wizard." The world continues to change, with non-player characters (NPCs) beginning to feel emotion. Having no parents, friends, or place in society, this ordinary young man Momonga then strives to take over the new world the game has become.

(Source: Anime News Network)', '2026-10-04T00:17:47.216Z', '2026-10-04T00:17:47.216Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('909b43ad-1195-4566-9249-d8d3c7973f1f', 98437, 'Overlord II', 'Overlord II', 'オーバーロードⅡ', 'https://cdn.kurzagin.com/anime/covers/98437.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/98437-yZXtJz59UMAo.jpg', 'TV', 'completed', 13, 13, 9, '["Action","Adventure","Fantasy"]', 'MADHOUSE', 2018, 'Continuing his quest to rule this new world, Ains begins to put the pieces in place for his conquest. But between a Lizard Man tribe uprising, and performing missions as adamantite adventurer Lord Momon, Ains has his work cut out for him! Thankfully he has his most loyal and willing subordinates to do his bidding. Nothing and no one can stop the supreme and mighty Overlord in his quest to rule all!

(Source: Manga Entertainment)', '2026-10-04T00:18:03.800Z', '2026-10-04T00:18:03.800Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('1995e0db-9465-47cd-8fa8-7ad617ba742a', 101922, 'Demon Slayer: Kimetsu no Yaiba', 'Kimetsu no Yaiba', '鬼滅の刃', 'https://cdn.kurzagin.com/anime/covers/101922.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/101922-33MtJGsUSxga.jpg', 'TV', 'completed', 26, 26, 9, '["Action","Adventure","Drama","Fantasy","Supernatural"]', 'ufotable', 2019, 'It is the Taisho Period in Japan. Tanjiro, a kindhearted boy who sells charcoal for a living, finds his family slaughtered by a demon. To make matters worse, his younger sister Nezuko, the sole survivor, has been transformed into a demon herself. Though devastated by this grim reality, Tanjiro resolves to become a “demon slayer” so that he can turn his sister back into a human, and kill the demon that massacred his family.

(Source: Crunchyroll)', '2026-10-04T15:07:37.633Z', '2026-10-04T15:07:37.633Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('83913691-661c-4254-99c7-f4e898d8d6e5', 101474, 'Overlord III', 'Overlord III', 'オーバーロードⅢ', 'https://cdn.kurzagin.com/anime/covers/101474.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/101474-n35NKyt9APDw.jpg', 'TV', 'completed', 13, 13, 9, '["Action","Adventure","Fantasy"]', 'MADHOUSE', 2018, 'With his foundations now set in this new world, the first steps of Ains Ooal Gown''s master plan apparent begin to come to fruition. The value of Carne village and especially the political value of his alter ego Momon are reaffirmed; the “hidden” genius of his actions is continuously met with shock and awe by Demiurge, Albedo, the rest of his guardians, and even Ains himself at his “great wisdom.” His attempts to act in a way befitting the ruler of Nazarick, continuing to further cement his guardian’s loyalty, push him ever further down the path of not-so-intentional world domination. Without human conscience due to being undead, he is motivated only to continue searching for other players from Yggdrasil and to gain power to better protect the children and home of him and his forty former companions. Lord Ains Ooal Gown maintains his mantle of Overlord and leads the Great Tomb of Nazarick unto the world stage, directly into a vicious power struggle between two great empires.

(Source: Anime News Network)', '2026-10-04T00:18:20.711Z', '2026-10-04T00:18:20.711Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('c900b441-f905-479d-9301-983c062ad900', 133844, 'Overlord IV', 'Overlord IV', 'オーバーロードⅣ', 'https://cdn.kurzagin.com/anime/covers/133844.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/133844-uIaUmh5aJX3M.jpg', 'TV', 'completed', 13, 13, 9, '["Action","Adventure","Fantasy"]', 'MADHOUSE', 2022, 'E-Rantel, the capital city of the newly established Sorcerer Kingdom, suffers from a dire shortage of goods. Once a prosperous city known for its trade, it now faces a crisis due to its caution—or even fear—of its king, Ainz Ooal Gown. To make amends, Ainz sends Albedo to the city as a diplomatic envoy.

Meanwhile, the cardinals of the Slane Theocracy discuss how to retaliate against Ainz after his attack crippled the Re-Estize Kingdom''s army, plotting for the Baharuth Empire to take over the Sorcerer Kingdom. However, when Emperor Jircniv Rune Farlord El Nix arranges a meeting with the Theocracy''s messengers at a colosseum, he is confronted by none other than Ainz himself.

With their secret gathering now out in the open, the emperor and his guests learn that Ainz has challenged the Warrior King, the empire''s greatest fighter, to a duel. With Ainz''s motivations beyond his comprehension, Jircniv can do nothing but watch as humanity''s future changes before his very eyes.

(Source: MAL Rewrite)', '2026-10-04T00:18:43.659Z', '2026-10-04T00:18:43.659Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('433340f5-7bac-4872-a8da-ec83cc436d54', 19815, 'No Game, No Life', 'No Game No Life', 'ノーゲーム・ノーライフ', 'https://cdn.kurzagin.com/anime/covers/19815.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/19815-BqbuD0wyBS3P.jpg', 'TV', 'completed', 12, 12, 10, '["Adventure","Comedy","Ecchi","Fantasy"]', 'MADHOUSE', 2014, 'Bored with life and considering the real world to be just a “crappy game,” savvy sibling shut-ins Sora and Shiro have withdrawn into their own fantasy world filled with video games. 

However, one day they find themselves summoned to another world by a boy who calls himself “God,” their abilities are about to be put to the ultimate test! Now not only their fates — but the fate of all of humanity — will be decided by a series of games that may just be the hardest these super-geniuses have ever faced!

(Source: Sentai Filmworks, edited)', '2026-10-04T00:19:52.502Z', '2026-10-04T00:19:52.502Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('d724e8b8-1660-493a-9cc0-be0d4d1b79a0', 21875, 'No Game, No Life Zero', 'No Game No Life Zero', 'ノーゲーム・ノーライフ ゼロ', 'https://cdn.kurzagin.com/anime/covers/21875.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21875-WWkiWSnNcdbt.jpg', 'MOVIE', 'completed', 1, 1, 10, '["Action","Adventure","Drama","Fantasy","Romance"]', 'MADHOUSE', 2017, 'Six thousand years before Sora and Shiro were even a blink in the history of Disboard, war consumed the land, tearing apart the heavens, destroying stars, and even threatening to wipe out the human race. Amid the chaos and destruction, a young man named Riku leads humanity toward the tomorrow his heart believes in. One day, in the ruins of an Elf city, he meets Schwi, a female exiled "Ex Machina" android who asks him to teach her what it means to have a human heart.
(Source: Sentai Filmworks)', '2026-10-04T00:20:16.997Z', '2026-10-04T00:20:16.997Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('18d1236f-0d23-45d6-a50e-80f13cc1b7b6', 184591, 'There''s No Freaking Way I''ll Be Your Lover! Unless…', 'Watashi ga Koibito ni Nareru Wake Nai jan, Muri Muri! (※Muri ja Nakatta!?)', 'わたしが恋人になれるわけないじゃん、ムリムリ! (※ムリじゃなかった!?)', 'https://cdn.kurzagin.com/anime/covers/184591.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/184591-ZD4xr3QagPf2.jpg', 'TV', 'planning', 0, 12, NULL, '["Comedy","Romance"]', 'studio MOTHER', 2025, 'Renako Amaori is leaving her awkward and lonely junior high school life behind, determined to become a normal girl with normal friends in high school. Glamorous, confident Mai Ouzuka is Renako’s total opposite: wealthy, outgoing, and a literal fashion model. Against the odds, the two girls form an immediate connection. Renako thinks she may have found the best friend of her dreams…until Mai’s romantic confession sends her into a tailspin. Renako wants to prove to Mai that being BFFs is better than being girlfriends, but Mai is dead set on convincing Renako that they’re destined to be lovers. Let the love games begin!

(Source: Seven Seas Entertainment)', '2026-10-04T06:00:08.892Z', '2026-10-04T06:00:08.892Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('f2e85aa4-8130-4377-bba7-ad2c0f23a8dc', 199112, 'There''s No Freaking Way I''ll Be Your Lover! Unless… ~Next Shine~', 'Watashi ga Koibito ni Nareru Wake Nai jan, Muri Muri! (※Muri ja Nakatta!?): Next Shine!', 'わたしが恋人になれるわけないじゃん、ムリムリ! (※ムリじゃなかった!?)〜ネクストシャイン！〜', 'https://cdn.kurzagin.com/anime/covers/199112.avif', NULL, 'TV', 'planning', 0, 5, NULL, '["Comedy","Romance"]', 'studio MOTHER', 2026, '"I want to learn to love myself—just the way I am!" Renako Amaori, a former gloomy and socially awkward girl, reinvented herself for high school and successfully made her debut. She even managed to join the top-tier popular group... only to be suddenly confessed to by two of its brightest stars?! One is the school’s ultimate prince, Mai Oduka. The other, the beloved angel of the campus, Ajisai Sena. There’s no way she can handle both their affections—no freaking way!

While still struggling to give them an answer, Renako agrees to help her friend Kaho by joining a cosplay event. It’s the perfect excuse to delay her reply… or so she thought. But as she witnesses Kaho''s passion firsthand, something begins to stir inside her. What is it that she truly wants? What is she truly searching for?

Can she really not become someone’s lover? Or has that "no freaking way"... not been so impossible after all?

(Source: REMOW)

Note: The anime first premiered in theaters across Japan on November 21, 2025. It was later split into 5 parts on TV, labelled as episodes 13-17.', '2026-10-04T06:00:30.197Z', '2026-10-04T06:00:30.197Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('13ce5b82-a1b0-422c-b347-83e4f786f1da', 11757, 'Sword Art Online', 'Sword Art Online', 'ソードアート・オンライン', 'https://cdn.kurzagin.com/anime/covers/11757.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/11757-TlEEV9weG4Ag.jpg', 'TV', 'completed', 25, 25, 8, '["Action","Adventure","Fantasy","Romance"]', 'A-1 Pictures', 2012, 'In the near future, a Virtual Reality Massive Multiplayer Online Role-Playing Game (VRMMORPG) called Sword Art Online has been released where players control their avatars with their bodies using a piece of technology called Nerve Gear. One day, players discover they cannot log out, as the game creator is holding them captive unless they reach the 100th floor of the game''s tower and defeat the final boss. However, if they die in the game, they die in real life. Their struggle for survival starts now...
(Source: Crunchyroll)', '2026-10-04T06:26:16.148Z', '2026-10-04T06:26:16.148Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('0d8ea806-d0ec-4a21-ae11-9cd1bdbadf77', 20517, 'Is the Order a Rabbit?', 'Gochuumon wa Usagi desu ka?', 'ご注文はうさぎですか？', 'https://cdn.kurzagin.com/anime/covers/20517.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20517.jpg', 'TV', 'completed', 12, 12, 10, '["Slice of Life"]', 'WHITE FOX', 2014, 'Coming to a new town to start high school can be intimidating, and that''s especially true for Cocoa, who can''t find the place she''s supposed to be staying when she arrives. When she stops at a cafe to ask for directions, however, it turns out that she''s already where she needs to be! You see, the Rabbit House is both a restaurant and a boarding house, and Cocoa will be working there along with the owner''s granddaughter, Chino and the strangely military-obsessed Rize. It''s a great place to work, business is hopping, and Cocoa''s fits right in with her new coworkers, as well as the girls from two other rival cafes. Still, there is something just a little odd about the Rabbit House. Besides the fact that Rize usually carries a Glock and a knife hidden on her, there''s also a mystery involving the shop''s pet rabbit, Tippy. And then there are those girls who sometimes seem to be able to communicate without talking…

(Source: Sentai Filmworks)', '2026-10-04T11:36:07.764Z', '2026-10-04T11:36:07.764Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('16839245-b5aa-468c-a363-718528814ed1', 21034, 'Is the Order a Rabbit?? Season 2', 'Gochuumon wa Usagi desu ka??', 'ご注文はうさぎですか？？', 'https://cdn.kurzagin.com/anime/covers/21034.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n21034-UaWI3qdUZxje.jpg', 'TV', 'completed', 12, 12, 10, '["Slice of Life"]', 'WHITE FOX', 2015, 'It’s time to re-open the doors to Rabbit House, where good friends are ready to take on the next exciting adventure, and there’s always something unusual going on. After all, how many cafés have waitresses who collect firearms and a rabbit that actually talks? However, trouble may be burrowing into the Kafuu residence when a magazine runs an article on places to eat and neglects to mention Rabbit House! Will an investigation into what’s been “haunting” Syaro’s house be a wild goose chase, or will someone get a lot of grey hare as a result? Is the sudden appearance of Cocoa’s big sister a blessing or a disaster waiting happen? Still, nothing is as scary as the prospect of graduating school! Will everyone make the grade, or will some friends be left behind?

(Source: Sentai Filmworks)', '2026-10-04T11:36:47.290Z', '2026-10-04T11:36:47.290Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('9034e5c0-56d7-4224-9a59-853f3495072a', 21613, 'Saga of Tanya the Evil', 'Youjo Senki', '幼女戦記', 'https://cdn.kurzagin.com/anime/covers/21613.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21613-FGAqKSTvfxuA.png', 'TV', 'completed', 12, 12, 7, '["Action","Fantasy"]', 'NUT', 2017, 'The novel series centers on a young girl who fights on the frontlines in war. She has blonde hair, blue eyes, and nearly transparent white skin, and she flies through the air and mercilessly strikes down her opponents. Her name is Tanya Degurechaff, and she speaks with a young girl''s lisp and commands the army. Tanya used to be one of Japan''s elite office workers, but because of a wrathful god, was reborn as a little girl. Tanya prioritizes optimization and career advancement above all, and she will become the most dangerous entity among the Imperial Army''s sorcerers.

(Source: Anime News Network)', '2026-10-04T11:58:20.451Z', '2026-10-04T11:58:20.451Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('c2096aec-4d8e-4bfc-a0e8-c746ef3d3569', 121, 'Fullmetal Alchemist', 'Hagane no Renkinjutsushi', '鋼の錬金術師', 'https://cdn.kurzagin.com/anime/covers/121.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/121-t5K7c8WRuPWl.jpg', 'TV', 'completed', 51, 51, 7, '["Action","Adventure","Drama","Fantasy"]', 'bones', 2003, 'The rules of alchemy state that to gain something, one must lose something of equal value. Alchemy is the process of taking apart and reconstructing an object into a different entity, with the rules of alchemy to govern this procedure. However, there exists an object that can bring any alchemist above these rules, the object known as the Philosopher''s Stone. The young Edward Elric is a particularly talented alchemist who through an accident years back lost his younger brother Alphonse and one of his legs. Sacrificing one of his arms as well, he used alchemy to bind his brother''s soul to a suit of armor. This lead to the beginning of their journey to restore their bodies, in search for the legendary Philosopher''s Stone.

Note: Episodes 11, 12 and 37 were adapted from the light novel "Fullmetal Alchemist: The Land of Sand."', '2026-10-04T11:59:27.615Z', '2026-10-04T11:59:27.615Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('940222a3-b188-4d22-909a-5f74abf65e86', 20594, 'Sword Art Online II', 'Sword Art Online II', 'ソードアート・オンライン II', 'https://cdn.kurzagin.com/anime/covers/20594.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20594-BZOLwqidcS1G.jpg', 'TV', 'completed', 24, 24, 7, '["Action","Adventure","Fantasy","Sci-Fi"]', 'A-1 Pictures', 2014, 'One year after the SAO incident, Kirito is approached by Seijiro Kikuoka from Japan''s Ministry of Internal Affairs and Communications Department "VR Division" with a rather peculiar request.

That was an investigation on the "Death Gun" incident that occurred in the gun and steel filled VRMMO called Gun Gale Online (GGO). "Players who are shot by a mysterious avatar with a jet black gun lose their lives even in the real world..." Failing to turn down Kikuoka''s bizarre request, Kirito logs in to GGO even though he is not completely convinced that the virtual world could physically affect the real world.

Kirito wanders in an unfamiliar world in order to gain any clues about the "Death Gun." Then, a female sniper named Sinon who owns a gigantic "Hecate II" rifle extends Kirito a helping hand. With Sinon''s help, Kirito decides to enter the "Bullet of Bullets," a large tournament to choose the most powerful gunner within the realm of GGO, in hopes to become the target of the "Death Gun" and make direct contact with the mysterious avatar.

(Source: Crunchyroll)', '2026-10-04T12:00:18.046Z', '2026-10-04T12:00:18.046Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('509dabfb-5b66-441c-be11-cee7d6442a8a', 21403, 'Sword Art Online the Movie: Ordinal Scale', 'Sword Art Online: Ordinal Scale', 'ソードアート・オンライン -オーディナル・スケール-', 'https://cdn.kurzagin.com/anime/covers/21403.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21403-3CvHjmnIays3.jpg', 'MOVIE', 'completed', 1, 1, 7, '["Action","Adventure","Fantasy","Romance","Sci-Fi"]', 'A-1 Pictures', 2017, 'In 2022, the world of virtual reality was upended by the arrival of a new invention from a genius programmer, Akihiko Kayaba. Called NerveGear, it was the first full-dive system and with it, came endless possibilities to VRMMORPGs.

In 2026, a new machine called the Augma is developed to compete against the NerveGear and its successor, the Amusphere. A next-gen wearable device, the Augma doesn''t have a full-dive function like its predecessors. Instead, it uses Augmented Reality to get players into the game. It is safe, user-friendly and lets users play while they are conscious, making it an instant hit on the market. The most popular game on the system is “Ordinal Scale” (aka: OS), an ARMMORPG developed exclusively for the Augma.

Asuna and the gang have already been playing OS for a while, by the time Kirito decides to join them. They’re about to find out that Ordinal Scale isn’t all fun and games…

(Source: Official website)', '2026-10-04T12:00:47.386Z', '2026-10-04T12:00:47.386Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('ad71ae4a-c5f6-4da5-a4d0-9a6eae718cae', 125038, 'SHADOWS HOUSE', 'Shadows House', 'シャドーハウス', 'https://cdn.kurzagin.com/anime/covers/125038.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/125038-Gy0IC8sqR8e4.jpg', 'TV', 'completed', 13, 13, 7, '["Fantasy","Horror","Mystery","Slice of Life","Supernatural"]', 'CloverWorks', 2021, 'High atop a cliff sits the mansion known as Shadows House, home to a faceless clan that pretends to live like nobles. They express their emotions through living dolls that also endlessly clean the home of soot. One such servant, Emilico, aids her master Kate as they learn more about themselves and the mysteries of the house.(Source: Funimation)', '2026-10-04T14:46:08.934Z', '2026-10-04T14:46:08.934Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('d4a31a4d-6706-4db9-a023-2961462e6ce2', 16498, 'Attack on Titan', 'Shingeki no Kyojin', '進撃の巨人', 'https://cdn.kurzagin.com/anime/covers/16498.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/16498-8jpFCOcDmneX.jpg', 'TV', 'completed', 25, 25, 9, '["Action","Drama","Fantasy","Mystery"]', 'WIT STUDIO', 2013, 'Several hundred years ago, humans were nearly exterminated by titans. Titans are typically several stories tall, seem to have no intelligence, devour human beings and, worst of all, seem to do it for the pleasure rather than as a food source. A small percentage of humanity survived by walling themselves in a city protected by extremely high walls, even taller than the biggest of titans.
Flash forward to the present and the city has not seen a titan in over 100 years. Teenage boy Eren and his foster sister Mikasa witness something horrific as the city walls are destroyed by a colossal titan that appears out of thin air. As the smaller titans flood the city, the two kids watch in horror as their mother is eaten alive. Eren vows that he will murder every single titan and take revenge for all of mankind.
(Source: MangaHelpers)', '2026-10-04T12:02:29.170Z', '2026-10-04T12:02:29.170Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('eceb408c-73cf-434c-a7fe-3a8f2925e6c4', 99147, 'Attack on Titan Season 3', 'Shingeki no Kyojin Season 3', '進撃の巨人 Season３', 'https://cdn.kurzagin.com/anime/covers/99147.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/99147-HACsFVrynFf5.jpg', 'TV', 'completed', 12, 12, 7, '["Action","Drama","Fantasy","Mystery"]', 'WIT STUDIO', 2018, 'Eren and his companions in the 104th are assigned to the newly-formed Levi Squad, whose assignment is to keep Eren and Historia safe given Eren''s newly-discovered power and Historia''s knowledge and pedigree. Levi and Erwin have good reason to be concerned, because the priest of the Church that Hanji had hidden away was found tortured to death, making it clear that the Military Police are involved with the cover-up. Things get more harrowing when the MPs make a move on Erwin and the Levi Squad narrowly avoids capture. Eren is also having problems with his Titan transformation, and a deadly killer has been hired to secure Eren and Historia, one Levi knows all too well from his youth.

(Source: Anime News Network)', '2026-10-04T12:03:19.944Z', '2026-10-04T12:03:19.944Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('f72b3487-7568-45f5-a281-7d0121b939b0', 110277, 'Attack on Titan Final Season', 'Shingeki no Kyojin: The Final Season', '進撃の巨人 The Final Season', 'https://cdn.kurzagin.com/anime/covers/110277.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/110277-iuGn6F5bK1U1.jpg', 'TV', 'completed', 16, 16, 9, '["Action","Drama","Fantasy","Mystery"]', 'MAPPA', 2021, 'It’s been four years since the Scout Regiment reached the shoreline, and the world looks different now. Things are heating up as the fate of the Scout Regiment—and the people of Paradis—are determined at last. However, Eren is missing. Will he reappear before age-old tensions between Marleyans and Eldians result in the war of all wars?

(Source: Crunchyroll)', '2026-10-04T12:03:56.797Z', '2026-10-04T12:03:56.797Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('c7acacdc-43cd-4093-84bb-859d75c163ee', 98505, 'Princess Principal', 'Princess Principal', 'プリンセス・プリンシパル', 'https://cdn.kurzagin.com/anime/covers/98505.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/98505-3kjCHxsc0IXh.jpg', 'TV', 'completed', 12, 12, 7, '["Action","Adventure","Sci-Fi"]', 'Studio 3Hz', 2017, 'The "spy action" series follows five girls in 19th century London, a city within the Albion Kingdom divided into east and west by a large wall. The girls serve as undercover spies enrolled as students at the prestigious Queen''s Mayfair school. The girls make use of their individual abilities to remain active in the underground world of disguise, espionage, infiltration, and car chases.

(Source: Official Website)', '2026-10-04T12:04:44.434Z', '2026-10-04T12:04:44.434Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('803bf98b-6ad7-4c6a-a834-c02adff0347e', 163076, 'Villainess Level 99: I May Be the Hidden Boss but I''m Not the Demon Lord', 'Akuyaku Reijou Level 99: Watashi wa Ura Boss desu ga Maou de wa Arimasen', '悪役令嬢レベル99 ～私は裏ボスですが魔王ではありません～', 'https://cdn.kurzagin.com/anime/covers/163076.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/163076-vD78A7Jl8j5l.jpg', 'TV', 'completed', 12, 12, 7, '["Comedy","Fantasy","Romance"]', 'Jumondou', 2024, 'This college kid wants nothing more than a quiet life. So when she’s reborn as Yumiella, the hidden villainess of an Otome RPG, she’s not exactly thrilled. Still yearning for peace, she abandons her evil duties to live a more discreet life. Until her gamer side kicks in and she accidentally reaches level 99! Now, everyone suspects that she’s the infamous Demon Lord. What future awaits her?

(Source: Crunchyroll)', '2026-10-04T12:07:26.251Z', '2026-10-04T12:07:26.251Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('2d0e730a-c7cc-44c8-be57-547d8f3058b8', 19603, 'Fate/stay night: Unlimited Blade Works', 'Fate/stay night: Unlimited Blade Works', 'Fate/stay night [Unlimited Blade Works]', 'https://cdn.kurzagin.com/anime/covers/19603.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/19603.jpg', 'TV', 'completed', 13, 13, 10, '["Action","Fantasy","Supernatural"]', 'ufotable', 2014, 'Fuyuki City - a city surrounded by the sea and mountains becomes the setting for an ancient ritual. Seven masters are given control of heroic spirits in order to realize the mythical Holy Grail, which is said to grant its owner any wish. These heroic spirits or servants represent legendary heroes of various classes: "Saber," "Lancer," "Archer," "Rider," "Caster," "Assassin," and "Berserker." Each master will enter into a contract with their chosen servant and battle the others to the death until only one pair remains... This is the "Holy Grail War."

The young and capable mage, Rin Tohsaka, prepares for her long-awaited Fifth Holy Grail War to begin... With her servant Archer, Rin enters the Holy Grail War as the sole heir to the prestigious Tohsaka family after her father''s death. But when Shirou Emiya, a boy from Rin''s school, unwittingly becomes a Master and is fatally wounded in battle, she has no choice but to save him. With Shirou and his servant Saber, Rin sets out to strike down the conspiracies surrounding the Holy Grail War. Will the Holy Grail bless Rin and Shirou''s path toward victory or will they be cursed with defeat?

(Source: Aniplex of America)

Notes:
- Includes Prologue.
- The first, second and last episodes aired with a runtime of ~48 minutes as opposed to the standard 24 minute long episode.
- Based on the second route from TYPE-MOON''s visual novel, Fate/stay night.
', '2026-10-04T12:08:41.613Z', '2026-10-04T12:08:41.613Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('c86ffa5a-cd90-4a10-823e-ff58024b2351', 20792, 'Fate/stay night: Unlimited Blade Works 2nd Season', 'Fate/stay night: Unlimited Blade Works 2nd Season', 'Fate/stay night [Unlimited Blade Works] 2ndシーズン', 'https://cdn.kurzagin.com/anime/covers/20792.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20792-tYnEdWy6Yi0I.jpg', 'TV', 'completed', 13, 13, 10, '["Action","Drama","Fantasy","Supernatural"]', 'ufotable', 2015, 'The Holy Grail War continues, with each Master and Servant duo making their move for the omnipotent wish granter. Caster’s plans have been set in motion, beginning with taking Saber captive while Rin and Archer go their separate ways to continue their fights on their own. Without Saber’s aid, Shirou’s principles are put to the ultimate test. With many battles to come with expected and unexpected enemies, Shirou’s resolve begins to take form. Is his desire to protect people and become a hero, genuine? Or are they simply borrowed feelings? And will it be enough to carry him to the end?

(Source: Aniplex of America)', '2026-10-04T12:09:08.793Z', '2026-10-04T12:09:08.793Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('232635e7-daf1-4653-bf46-430279a629ce', 103275, 'Fate/Grand Order Absolute Demonic Front: Babylonia', 'Fate/Grand Order: Zettai Majuu Sensen Babylonia', 'Fate/Grand Order -絶対魔獣戦線バビロニア-', 'https://cdn.kurzagin.com/anime/covers/103275.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/103275-9vSzr7YzbXQb.jpg', 'TV', 'planning', 0, 21, NULL, '["Action","Adventure","Fantasy","Supernatural"]', 'CloverWorks', 2019, 'A seventh Singularity has been discovered in ancient Mesopotamia in the year 2655 B.C.

The land of Uruk, governed by the wise King Gilgamesh after he returned from his quest for immortality, was grand and prosperous until three goddesses and countless Demonic Beasts appeared. These enemies have brought Uruk to the brink of destruction. With a Rayshift—a method of traveling across both time and space—Fujimaru and Mash journey to the land of Uruk, where they encounter the fortress city of Uruk and the Absolute Demonic Front, where a terrible battle against the fearsome onslaught of the Demonic Beasts rages. There, the citizens of Uruk, who live their lives to the fullest despite facing an existential threat, continue to fight for their future. Deities and Demonic Beasts attack with terrifying force, and mankind pushes back with all its might... This is the era where humans and gods are destined to part ways.

Fujimaru and Mash, the pair who have fought through all six previous Singularities, embark on their final battle.

(Source: Aniplex of America)

Note: Based on the seventh chapter of the first arc in Fate/Grand Order, a Japanese smartphone role-playing game from TYPE-MOON’s Fate franchise.', '2026-10-04T12:09:58.568Z', '2026-10-04T12:09:58.568Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('70377f5b-90e8-48e8-bf3b-11b67767feb8', 20968, 'The Anthem of the Heart', 'Kokoro ga Sakebitagatterun da.', '心が叫びたがってるんだ。', 'https://cdn.kurzagin.com/anime/covers/20968.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20968-1ChkqEXgFAmf.jpg', 'MOVIE', 'completed', 1, 1, 7, '["Drama","Music","Psychological","Romance","Slice of Life"]', 'A-1 Pictures', 2015, 'Jun is a girl whose words have been sealed away. She was once a very happy girl, but because of a certain thing she said when she was very young, her family was torn apart. One day, the egg fairy appeared in front of her and sealed away her ability to talk in order to stop her from hurting anybody else. Since this traumatic experience, Jun lives in the shadows away from the limelight. But, one day, she is nominated to become an executive member of the "community outreach council." On top of that, Jun is also appointed to play the main lead in their musical...

(Source: Official website)', '2026-10-04T14:27:42.606Z', '2026-10-04T14:27:42.606Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('d3a0771a-5020-4245-b5f5-6d166685a100', 21519, 'Your Name.', 'Kimi no Na wa.', '君の名は。', 'https://cdn.kurzagin.com/anime/covers/21519.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21519-1ayMXgNlmByb.jpg', 'MOVIE', 'completed', 1, 1, 7, '["Drama","Romance","Supernatural"]', 'CoMix Wave', 2016, 'Mitsuha Miyamizu, a high school girl, yearns to live the life of a boy in the bustling city of Tokyo—a dream that stands in stark contrast to her present life in the countryside. Meanwhile in the city, Taki Tachibana lives a busy life as a high school student while juggling his part-time job and hopes for a future in architecture.

One day, Mitsuha awakens in a room that is not her own and suddenly finds herself living the dream life in Tokyo—but in Taki''s body! Elsewhere, Taki finds himself living Mitsuha''s life in the humble countryside. In pursuit of an answer to this strange phenomenon, they begin to search for one another.

Kimi no Na wa. revolves around Mitsuha and Taki''s actions, which begin to have a dramatic impact on each other''s lives, weaving them into a fabric held together by fate and circumstance.

(Source: MAL Rewrite)', '2026-10-04T14:28:15.394Z', '2026-10-04T14:28:15.394Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('ae9cd84e-8ded-4eb0-a059-7da2a2d5364a', 106286, 'Weathering With You', 'Tenki no Ko', '天気の子', 'https://cdn.kurzagin.com/anime/covers/106286.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/106286-3oKwiwjd7Wkm.jpg', 'MOVIE', 'completed', 1, 1, 7, '["Drama","Romance","Slice of Life","Supernatural"]', 'CoMix Wave', 2019, 'High school student Hodaka leaves his home on an isolated island and moves to Tokyo, but he immediately becomes broke. He lives his days in isolation, but finally finds a job as a writer for a shady occult magazine. After he starts his job, the weather has been rainy day after day. In a corner of the crowded and busy city, Hodaka meets a young woman named Hina. Due to certain circumstances, Hina and her younger brother live together, but have a cheerful and sturdy life. Hina also has a certain power: the power to stop the rain and clear the sky.

(Source: Anime News Network)', '2026-10-04T14:28:49.288Z', '2026-10-04T14:28:49.288Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('e9aa6441-10a2-45b9-9923-1b2e1d7155be', 20754, 'SCHOOL-LIVE!', 'Gakkou Gurashi!', 'がっこうぐらし!', 'https://cdn.kurzagin.com/anime/covers/20754.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20754-Hwnbsm4uaVFD.jpg', 'TV', 'completed', 12, 12, 10, '["Horror","Mystery","Psychological","Slice of Life","Supernatural"]', 'Lerche', 2015, 'Why would anyone form a School Living Club? Could four girls, their advisor, and a puppy really love their school so much that they’d want to live in it? Or is there another reason, something that lurks behind the façade of their comfortable existence? Something that waits outside their school’s doors. Something that has already robbed one girl of her sanity? While the others try to come to grips with a dark new reality, the rest of the world falls to ruin at the hands of a ravenous force, and insanity may be the last hope for survival. Shocks, heartbreak and stunning revelations await as the twisted tale unfolds.

(Source: Sentai Filmworks)', '2026-10-04T14:29:09.071Z', '2026-10-04T14:29:09.071Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('eab8b7f8-75c6-4457-9e19-99562773df47', 20800, 'Yuki Yuna is a Hero', 'Yuuki Yuuna wa Yuusha de Aru', '結城友奈は勇者である', 'https://cdn.kurzagin.com/anime/covers/20800.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20800-KpoJB6tGnj2V.jpg', 'TV', 'completed', 12, 12, 10, '["Action","Drama","Fantasy","Mahou Shoujo","Psychological","Slice of Life"]', 'Studio Gokumi', 2014, 'Yuuna Yuuki is an ordinary second-year middle school student. She gets up in the morning, gets ready for school, goes to classes, participates in club activities, and has fun with her friends. But there is one extraordinary thing about Yuuki — she belongs to the “Brave Hero Club.” What does the Brave Hero Club do? Who is the mysterious being called “Vertex?” Yuuki Yuuna and her friends’ story takes place in Year 300, Era of the Gods.

(Source: Ponycan USA)', '2026-10-04T14:29:33.542Z', '2026-10-04T14:29:33.542Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('d8311c54-295f-4f3d-b6c2-5a10170a30ff', 97769, 'Yuki Yuna is a Hero: The Hero Chapter', 'Yuuki Yuuna wa Yuusha de Aru: Yuusha no Shou', '結城友奈は勇者である -勇者の章-', 'https://cdn.kurzagin.com/anime/covers/97769.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/97769-omjSxfE8wiTx.jpg', 'TV', 'completed', 6, 6, 10, '["Action","Drama","Fantasy","Mahou Shoujo","Psychological","Slice of Life"]', 'Studio Gokumi', 2017, 'Having fulfilled their destiny during the events of Yuuki Yuuna wa Yuusha de Aru, Sanshu Middle School''s Hero Club—consisting of Yuuna Yuuki, Karin Miyoshi, and siblings Fuu and Itsuki Inubouzaki—is back in full swing, helping out those in need wherever they can. They have also gained a new member, a hero from the past named Sonoko Nogi. But eventually they notice that someone who should be among them, Mimori Tougou, is missing; any trace of her existence is completely gone, save for the girls'' memories.

With no leads on Tougou''s whereabouts, the girls regain the ability to transform and begin the desperate search for their lost friend. But what they find is more shocking than any of them could ever have imagined, and the consequences of their actions begin to change life as they know it.

(Source: MAL Rewrite)', '2026-10-04T14:30:23.285Z', '2026-10-04T14:30:23.285Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('a4f6b682-ed0d-43ae-8061-ea5cad6ce11f', 100791, 'Yuki Yuna is a Hero: The Washio Sumi Chapter', 'Yuuki Yuuna wa Yuusha de Aru: Washio Sumi no Shou', '結城友奈は勇者である -鷲尾須美の章-', 'https://cdn.kurzagin.com/anime/covers/100791.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/100791-JwCVfH2iGcbx.jpg', 'TV', 'completed', 6, 6, 10, '["Action","Drama","Fantasy","Mahou Shoujo","Psychological","Slice of Life"]', 'Studio Gokumi', 2017, 'In the year 298 from the era of the gods, elementary school girls Sumi Washio, Sonoko Nogi, and Gin Minowa are tasked with an important mission. They are to become heroes and fight Vertex, a mysterious enemy that is attacking Shinju-sama, the god tree that protects Shikoku, the only area in the world that is still habitable. What they don''t know, is that this fight will cost them more than they could have ever imagined.
', '2026-10-04T14:31:09.661Z', '2026-10-04T14:31:09.661Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('6a7077f7-20a9-42be-930d-3b79c8d06942', 97858, 'Yuuki Yuuna wa Yuusha de Aru: Washio Sumi no Shou 1 - Tomodachi', 'Yuuki Yuuna wa Yuusha de Aru: Washio Sumi no Shou 1 - Tomodachi', '結城友奈は勇者である -鷲尾須美の章- 第1章 「ともだち」', 'https://cdn.kurzagin.com/anime/covers/97858.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/97858-ZzGSqTZ27NOx.jpg', 'MOVIE', 'completed', 1, 1, 10, '["Action","Drama","Fantasy","Mahou Shoujo","Slice of Life"]', 'Studio Gokumi', 2017, 'The first movie in the Washio Sumi no Shou trilogy.', '2026-10-04T14:32:08.673Z', '2026-10-04T14:32:08.673Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('9ec3cd94-04eb-4980-a673-ec7383d04ea1', 97860, 'Yuuki Yuuna wa Yuusha de Aru: Washio Sumi no Shou 3 - Yakusoku', 'Yuuki Yuuna wa Yuusha de Aru: Washio Sumi no Shou 3 - Yakusoku', '結城友奈は勇者である -鷲尾須美の章- 第3章 「やくそく」', 'https://cdn.kurzagin.com/anime/covers/97860.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/97860-ZExQS1FMfqHI.jpg', 'MOVIE', 'completed', 1, 1, 10, '["Action","Drama","Fantasy","Mahou Shoujo","Slice of Life"]', 'Studio Gokumi', 2017, 'The third and final movie in the Washio Sumi no Shou trilogy.', '2026-10-04T14:32:37.409Z', '2026-10-04T14:32:37.409Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('34406d1f-6b46-4d96-ae54-2966c85d40d4', 20755, 'Assassination Classroom', 'Ansatsu Kyoushitsu', '暗殺教室', 'https://cdn.kurzagin.com/anime/covers/20755.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20755-D4ipww9U8YkC.jpg', 'TV', 'completed', 22, 22, 8, '["Action","Comedy","Drama","Supernatural"]', 'Lerche', 2015, 'The students of class 3-E have a mission: kill their teacher before graduation. He has already destroyed the moon, and has promised to destroy the Earth if he can not be killed within a year. But how can this class of misfits kill a tentacled monster, capable of reaching Mach 20 speed, who may be the best teacher any of them have ever had?', '2026-10-04T14:33:22.114Z', '2026-10-04T14:33:22.114Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('8901ca1d-226c-4fa5-9efc-09e31756cdb0', 21170, 'Assassination Classroom Second Season', 'Ansatsu Kyoushitsu 2nd Season', '暗殺教室 第２期', 'https://cdn.kurzagin.com/anime/covers/21170.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21170-3sLTirZD2J4K.jpg', 'TV', 'completed', 25, 25, 8, '["Action","Comedy","Drama","Supernatural"]', 'Lerche', 2016, 'The students return as school is back in session for the second semester. Following their exploits on the island during summer vacation, Class 3-E continues to sharpen their blades with their sights set on their teacher, the slippery Koro-sensei. They have more to worry about than just their teacher, however, as enemy assassins, both old and new, are out for the increased bounty on the octopus'' head.

Moreover, their rivals in Class A, as well as Kunugigaoka Junior High''s fearsome principal, stand to block Class E from achieving academic excellence. With all of these obstacles opposing them, the group must continue to work together in order to overcome their foes and accomplish their goal of successfully assassinating their teacher.', '2026-10-04T14:33:59.509Z', '2026-10-04T14:33:59.509Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('7304f7ce-075b-4906-9629-f7aa00241ffb', 6547, 'Angel Beats!', 'Angel Beats!', 'Angel Beats!', 'https://cdn.kurzagin.com/anime/covers/6547.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/6547-YUUiSjKyxxeQ.jpg', 'TV', 'completed', 13, 13, 7, '["Action","Comedy","Drama","Supernatural"]', 'P.A.WORKS', 2010, 'Otonashi wakes up in the afterlife to find out he has no memories of his life before death. Desperate to survive in a war that could yield another unfortunate fate, he joins the SSS in the battle against Angel, whose very mission is to destroy all inhabitants of this afterlife. As Otonashi struggles to recover his memory and learn more about this world, he finds that not all is as it had seemed.
(Source: Funimation)', '2026-10-04T14:36:37.275Z', '2026-10-04T14:36:37.275Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('dfb7e0c5-a1c9-495d-abd6-219b776be325', 150672, 'OSHI NO KO', '[Oshi no Ko]', '【推しの子】', 'https://cdn.kurzagin.com/anime/covers/150672.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/150672-ISwoA0eS722H.jpg', 'TV', 'completed', 11, 11, 7, '["Drama","Mystery","Psychological","Supernatural"]', 'Doga Kobo', 2023, 'When a pregnant young starlet appears in Gorou Amemiya’s countryside medical clinic, the doctor takes it upon himself to safely (and secretly) deliver Ai Hoshino’s child so she can make a scandal-free return to the stage. But no good deed goes unpunished, and on the eve of her delivery, he finds himself slain at the hands of Ai’s deluded stalker — and subsequently reborn as Ai’s child, Aquamarine Hoshino! The glitz and glamor of showbiz hide the dark underbelly of the entertainment industry, threatening to dull the shine of his favorite star. Can he help his new mother rise to the top of the charts? And what will he do when unthinkable disaster strikes? 

(Source: HIDIVE)


Note: Episode 1【推しの子】Mother and Children was pre-screened in advance in Japanese theaters on March 17, 2023. The regular TV broadcast began on April 12, 2023. The first episode has an extended runtime of ~82 minutes.', '2026-10-04T14:36:57.666Z', '2026-10-04T14:36:57.666Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('b524fc16-4891-4889-aa0d-0d23537c8b77', 182587, 'OSHI NO KO Season 3', '[Oshi no Ko] 3rd Season', '【推しの子】第3期', 'https://cdn.kurzagin.com/anime/covers/182587.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/182587-SLNmuinewbUF.jpg', 'TV', 'planning', 0, 11, NULL, '["Drama","Mystery","Psychological","Supernatural"]', 'Doga Kobo', 2026, 'The story enters a new stage.

It''s been six months since "POP IN 2" was released. Thanks to MEM-Cho''s hard work, B-Komachi is about to get their major break. Aqua is a multi-talented entertainer, and Akane''s career as a talented actress is going smoothly. Meanwhile, Kana lost the cheerfulness she once had. To track down the truth behind Ai and Goro''s deaths, Ruby keeps rising in the entertainment world—using lies as a weapon.

(Source: Crunchyroll)

Note: The last episode has an extended runtime of ~54 minutes.', '2026-10-04T14:37:22.160Z', '2026-10-04T14:37:22.160Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('eb894014-7bab-4e15-b875-a7e605761abf', 166531, 'OSHI NO KO Season 2', '[Oshi no Ko] 2nd Season', '【推しの子】第2期', 'https://cdn.kurzagin.com/anime/covers/166531.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/166531-vUu7iDwUkC67.jpg', 'TV', 'planning', 0, 13, NULL, '["Drama","Mystery","Psychological","Supernatural"]', 'Doga Kobo', 2024, 'Aqua’s desire for revenge takes center stage as he navigates the dark underbelly of the entertainment world alongside his twin sister, Ruby. While Ruby follows in their slain mother’s footsteps to become an idol, Aqua joins a famous theater troupe in hopes of uncovering clues to the identity of his father — the man who arranged their mother’s untimely death, and the man who once starred in the same troupe Aqua hopes to infiltrate.

(Source: HIDIVE)', '2026-10-04T14:37:47.535Z', '2026-10-04T14:37:47.535Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('f3026d71-ad48-41e4-8079-328030fee477', 17265, 'Log Horizon', 'Log Horizon', 'ログ・ホライズン', 'https://cdn.kurzagin.com/anime/covers/17265.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/17265-53eBCC34SKyM.jpg', 'TV', 'completed', 25, 25, 8, '["Action","Adventure","Fantasy"]', 'Satelight', 2013, 'The online fantasy game Elder Tales is a worldwide phenomenon, immersing millions of players in its intricately conceived virtual world. However, the release of the game''s twelfth expansion pack makes that immersion all too literal, as players from around the world are suddenly pulled into the game''s no-longer-fictional universe! Now, eight-year ET veteran Shiroe, his friend Naotsugu, the beautiful assassin Akatsuki, and 30,000 other players are faced with the daunting task of learning how to deal with an entirely new reality, one where the Non-Player Characters are actually alive, and the tips and tricks learned while playing with a keyboard no longer apply.
(Source: Sentai Filmworks)', '2026-10-04T14:41:39.864Z', '2026-10-04T14:41:39.864Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('14cd49d6-c1d0-498d-8e50-3d0796f1ddf2', 20671, 'Log Horizon 2', 'Log Horizon 2', 'ログ・ホライズン 2', 'https://cdn.kurzagin.com/anime/covers/20671.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20671-PA67NsHagm79.jpg', 'TV', 'planning', 0, 25, NULL, '["Action","Adventure","Fantasy"]', 'Studio DEEN', 2014, 'After struggling to survive in a surreal existence they were suddenly thrown into, Shiroe and his friends have managed to restore order to Akihabara by defending the people against the Goblins in the Zantleaf Region. After six long months with the team gaining the trust of the many guilds that use the city as their home base, they must now prepare for their unforeseen future – and a tough winter ahead. Once shy and a little standoffish, Shiroe has stepped up and shown that he can be a great leader. But can he keep Akatsuki, Naotsugu, and the rest of the gang together as they start to have differing opinions on their future course of action?  And will the clique agree to leave the safety of the holy land of Akihabara to head off to one of the other four cities and explore foreign lands of Elder Tale? Whatever they may decide, this world that was once a game for the players is now reality and they must decide what is best for each and every one of the members of the team.

(Source: Sentai Filmworks)', '2026-10-04T14:41:59.185Z', '2026-10-04T14:41:59.185Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('97b188f1-a978-4cbc-94af-723869dc832d', 20955, 'Rokka -Braves of the Six Flowers-', 'Rokka no Yuusha', '六花の勇者', 'https://cdn.kurzagin.com/anime/covers/20955.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20955-v7GKIwKsq99g.jpg', 'TV', 'completed', 12, 12, 8, '["Action","Adventure","Fantasy","Mystery"]', 'Passione', 2015, 'When the Majin awoke from the depths of darkness, the deity of fate chose six heroes and bequeathed them with the power to save the world. Adlet, a boy who proclaims himself the strongest on Earth, was selected among the Rokka no Yuusha (Heroes of the Six Flowers), and he goes to the rendezvous point — but seven have gathered there. The heroes suspect that someone among the seven is the enemy, and the initial suspicion falls on Adlet.

(Source: Anime News Network)', '2026-10-04T14:42:27.754Z', '2026-10-04T14:42:27.754Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('b957c081-76e1-4b79-a8ba-ebe658dc2b96', 100182, 'Sword Art Online: Alicization', 'Sword Art Online: Alicization', 'ソードアート・オンライン アリシゼーション', 'https://cdn.kurzagin.com/anime/covers/100182.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/100182-8iGTeJ2kYRDt.jpg', 'TV', 'completed', 24, 24, 10, '["Action","Adventure","Fantasy","Sci-Fi"]', 'A-1 Pictures', 2018, 'Kirito awakens in a vast, fantastical forest filled with towering trees. In his search for clues to the truth of his surroundings, he encounters a young boy who seems to know him. He ought to be a simple NPC, but the depth of his emotions seem no different than a human. As they search for the boy''s parents, Kirito finds a peculiar memory returning to him. A memory from his own childhood, of this boy and a girl, too, with golden hair, and a name he should have never forgotten - Alice.

(Source: Yen Press)

Note: The first episode aired with a runtime of ~48 minutes as opposed to the standard 24 minute long episode.', '2026-10-04T12:01:17.593Z', '2026-10-04T14:43:32.427Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('a7513bd6-ded8-4093-beb2-0031084da9e1', 108759, 'Sword Art Online: Alicization - War of Underworld', 'Sword Art Online: Alicization - War of Underworld', 'ソードアート・オンライン アリシゼーション War of Underworld', 'https://cdn.kurzagin.com/anime/covers/108759.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/108759-HGsEWBcisLmO.jpg', 'TV', 'completed', 12, 12, 10, '["Action","Adventure","Drama","Fantasy","Sci-Fi"]', 'A-1 Pictures', 2019, 'Kirito, Eugeo, and Alice. Six months have passed since the two disciples and an Integrity Knight brought down the pontifex, Administrator. With the fighting over, Alice has been living in her hometown of Rulid Village. Beside her is Kirito, who has not only lost his arm and soul, but also his dear friend. As Alice devotes herself to looking after Kirito, she too has lost the will to fight she once had as a knight.

Nevertheless, the time for the final stress test – one which will engulf the entire Underworld with tragedy – draws relentlessly closer.

Meanwhile, in the deepest areas of the Dark Territory, the Dark God Vecta has resurrected, as if to have waited for this very moment. Leading an army of dark forces, they begin their invasion into the human empire in hopes of attaining the Priestess of Light. The human empire force led by the Integrity Knight Bercouli prepares for a war of an unimaginable scale against the army of the Dark Territory. Even then, Alice is nowhere to be seen, nor the two heroes that saved the realm...

(Source: Official Website)', '2026-10-04T14:43:56.023Z', '2026-10-04T14:43:56.023Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('03d63496-7bbc-4d7d-b745-24a2ea04fa69', 114308, 'Sword Art Online: Alicization - War of Underworld Part 2', 'Sword Art Online: Alicization - War of Underworld Part 2', 'ソードアート・オンライン アリシゼーション War of Underworld 最終章 (2nd Season)', 'https://cdn.kurzagin.com/anime/covers/114308.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/114308-VuYDoBJMbU1i.jpg', 'TV', 'completed', 11, 11, 10, '["Action","Adventure","Fantasy"]', 'A-1 Pictures', 2020, 'The final load test... The war between the Human Empire and the Dark Territory has engulfed Underworld entirely. The battle has shifted course with the Dark Territory army led by Gabriel, who seeks to capture Alice, the Priestess of Light, against Asuna and the Human Empire forces fighting to save Underworld.

As Kirito''s consciousness remains buried in a deep sleep, Gabriel, standing in as the Dark God Vecta, has recruited thousands of American players to log in to Underworld to annihilate the Human Empire forces. Meanwhile, Asuna, Sinon, and Leafa have joined the battle utilizing three super-accounts of the deities of the Underworld. As the Goddess of Creation Stacia Asuna fights alongside the Human Empire forces to take on the American players in a vicious combat. Sinon, who has gained the super-account for the Sun Goddess Solus, is in pursuit of Gabriel, who has abducted Alice, while Leafa arrives to Underworld with the super-account Earth Goddess Terraria.

But that is not all...

The impassioned speech by Lisbeth has convinced many ALO players to join the fight with the Human Empire despite the risks. With this great war, not only Underworld''s continued existence, but the bottom-up artificial intelligence, the ultimate AI, and even the future of mankind is at stake.

Though he has yet to awaken, only one man holds the fate of this world: the Black Swordsman.

(Source: Official Website)', '2026-10-04T14:44:22.881Z', '2026-10-04T14:44:22.881Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('835f0784-c2f5-4150-b72c-73a53bb96aa4', 108725, 'The Promised Neverland Season 2', 'Yakusoku no Neverland 2', '約束のネバーランド2', 'https://cdn.kurzagin.com/anime/covers/108725.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/108725-lg940Urvxzfu.jpg', 'TV', 'planning', 0, 11, NULL, '["Action","Adventure","Drama","Fantasy","Horror","Psychological","Thriller"]', 'CloverWorks', 2021, 'Fifteen children escape Grace Field House, a false paradise, hoping for a chance at freedom. Instead, they encounter plants and animals they have never before seen, and are chased by demons. The outside world is so beautiful, and yet is almost too cruel to face.

Even so, the children refuse to give up. They are guided in their search for better lives only by a message from Minerva and a pen Norman left behind in order to fulfill their promise to return to the House to save those of their family who are still trapped within.

(Source: Aniplex of America)

Note: Episode 1 streamed early on Amazon Prime on Jan 7, 2021. The regular TV broadcast started on Jan 8, 2021.', '2026-10-04T14:46:58.980Z', '2026-10-04T14:46:58.980Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('4e6518a5-841a-4274-9265-19bacabf21e0', 20789, 'The Seven Deadly Sins', 'Nanatsu no Taizai', '七つの大罪', 'https://cdn.kurzagin.com/anime/covers/20789.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20789-qwG9GcxIrmVE.jpg', 'TV', 'completed', 24, 24, 9, '["Action","Adventure","Comedy","Ecchi","Fantasy","Supernatural"]', 'A-1 Pictures', 2014, 'When they were accused of trying to overthrow the monarchy, the feared warriors the Seven Deadly Sins were sent into exile. Princess Elizabeth discovers the truth - the Sins were framed by the king''s guard, the Holy Knights - too late to prevent them from assassinating her father and seizing the throne!
Now the princess is on the run, seeking the Sins to help her reclaim the kingdom. But the first Sin she meets, Meliodas, is a little innkeeper with a talking pig. He doesn''t even have a real sword! Have the legends of the Sins'' strength been exaggerated?

(Source: Anime News Network)', '2026-10-04T14:48:07.988Z', '2026-10-04T14:48:07.988Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('355906e1-64c3-4ab8-abb4-d1be89b4cde8', 8425, 'Gosick', 'GOSICK', 'GOSICK', 'https://cdn.kurzagin.com/anime/covers/8425.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/8425-Lf6WLBHfOdRQ.jpg', 'TV', 'completed', 24, 24, 9, '["Drama","Mystery","Romance"]', 'bones', 2011, 'Kazuya Kujou is a foreign student at Saint Marguerite Academy, a luxurious boarding school in the Southern European country of Sauville. Originally from Japan, his jet-black hair and dark brown eyes cause his peers to shun him and give him the nickname "Black Reaper," based on a popular urban legend about the traveler who brings death in the spring.

On a day like any other, Kujou visits the school''s extravagant library in search of ghost stories. However, his focus soon changes as he becomes curious about a golden strand of hair on the stairs. The steps lead him to a large garden and a beautiful doll-like girl known as Victorique de Blois, whose complex and imaginative foresight allows her to predict their futures, now intertwined.

With more mysteries quickly developing—including the appearance of a ghost ship and an alchemist with the power of transmutation—Victorique and Kujou, bound by fate and their unique skills, have no choice but to rely on each other.
(Source: MAL Rewrite)', '2026-10-04T14:51:51.695Z', '2026-10-04T14:51:51.695Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('7985ac00-18fc-43e5-8d58-d1e9b54a07a7', 179966, 'Secrets of the Silent Witch', 'Silent Witch: Chinmoku no Majo no Kakushigoto', 'サイレント・ウィッチ 沈黙の魔女の隠しごと', 'https://cdn.kurzagin.com/anime/covers/179966.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/179966-hf71VrF1zhPM.jpg', 'TV', 'completed', 13, 13, 9, '["Drama","Fantasy"]', 'Studio Gokumi', 2025, 'Monica Everett, the Silent Witch, is the world’s only practitioner of Voiceless Magic, a veritable heroine who single-handedly fended off the Black Dragon of legend. However, the young prodigy is actually…super-duper shy! Yup, turns out she only learned Voiceless Magic to avoid speaking in public. Ignorant of this, the Seven Sages have placed her on a top-secret mission to guard the Second Prince. Can Monica keep it together as she contends with both social interaction and the evils targeting the young royal?
(Source: Yen Press, edited)', '2026-10-04T14:53:32.679Z', '2026-10-04T14:53:32.679Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('a8b2b836-7f59-4cb5-b42f-27f4bafc6437', 159808, 'The Vexations of a Shut-In Vampire Princess', 'Hikikomari Kyuuketsuki no Monmon', 'ひきこまり吸血姫の悶々', 'https://cdn.kurzagin.com/anime/covers/159808.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/159808-hHtK0HhZlyzD.jpg', 'TV', 'completed', 12, 12, 10, '["Action","Comedy","Fantasy"]', 'project No.9', 2023, 'Three years into her life as a shut-in, vampire Terakomari Gandesblood (Komari for short), awakens to find she’s been appointed as a Commander in the Mulnite Imperial Army! The thing is, her new unit consists solely of belligerent ruffians who revolt against their superiors at the slightest hint of weakness. Although Komari hails from a line of vampires as powerful as they are prestigious, her refusal to drink blood has made her the picture of mediocrity—scrawny, un-coordinated, and inept at magic. With the odds stacked against her, will the help of her trusty (and slightly infatuated) maid Vill be enough for this recluse to blunder her way to success? Or will Komari rue the day she ever left the safety of her room?

(Source: Yen Press)', '2026-10-04T14:55:32.524Z', '2026-10-04T14:55:32.524Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('64da8c13-92d0-4eec-8278-987f3c5f8db0', 112609, 'Wandering Witch: The Journey of Elaina', 'Majo no Tabitabi', '魔女の旅々', 'https://cdn.kurzagin.com/anime/covers/112609.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/112609-P969sQ0jIU6S.jpg', 'TV', 'completed', 12, 12, 9, '["Adventure","Fantasy","Slice of Life"]', 'C2C', 2020, 'Inspired by her favorite book, Elaina ventures out to see the world she''s read so much about. Like a leaf on the wind, she travels from one country to another, looking to sate her inquisitiveness and searching for new experiences. She''s confronted by humanity in all its forms, whether strange, bizarre, or emotional. Exploration and curiosity drive her journey. Where to next, Elaina?


(Source: Funimation)', '2026-10-04T14:57:45.810Z', '2026-10-04T14:57:45.810Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('8b9b5af1-2fa1-4f46-b106-97dd00879469', 21058, 'Snow White with the Red Hair', 'Akagami no Shirayuki-hime', '赤髪の白雪姫', 'https://cdn.kurzagin.com/anime/covers/21058.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21058-Kxl8fq3kEgeH.png', 'TV', 'completed', 12, 12, 7, '["Drama","Fantasy","Romance"]', 'bones', 2015, 'In the kingdom of Tanbarun lives Shirayuki, an independent and strong-willed young woman. Her resourceful intelligence has led her become a skilled pharmacist, but her most defining trait is her shock of beautiful apple-red hair. Her dazzling mane gets her noticed by the prince of the kingdom, but instead of romancing her, he demands she be his concubine. Shirayuki refuses, chops off her lovely locks, and runs away to the neighboring kingdom of Clarines. There, she befriends a young man named Zen, who, SURPRISE, is also a prince, although with a much better temperament than the previous one. Watch as Shirayuki finds her place in the new kingdom, and in Zen’s heart.

(Source: FUNimation)', '2026-10-04T14:59:19.540Z', '2026-10-04T14:59:19.540Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('c5ad1e3b-911b-4fa5-9468-890c7edf8595', 21455, 'NEW GAME!', 'NEW GAME!', 'NEW GAME!', 'https://cdn.kurzagin.com/anime/covers/21455.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21455-zxd4BFfVw6SZ.jpg', 'TV', 'completed', 12, 12, 7, '["Comedy","Slice of Life"]', 'Doga Kobo', 2016, 'Fresh out of high school, 18-year-old Aoba Suzukaze is bright-eyed, bushy-tailed, and ready for her first day of work at her dream job. She’s joining the character design team at Eagle Jump, the company that makes her favorite video games! But the real world of office culture can be a challenge for a total noob. From her awkward first day to her first game’s debut, she’s got a lot of skills to master. Luckily, her charming determination wins over even her quirkiest of coworkers, and before she knows it, Aoba has joined the party!

(Source: Funimation)', '2026-10-04T15:05:54.200Z', '2026-10-04T15:05:54.200Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('b6116571-8b42-4326-9267-e9e24eb85444', 21878, 'Gabriel DropOut', 'Gabriel Dropout', 'ガヴリールドロップアウト', 'https://cdn.kurzagin.com/anime/covers/21878.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21878-QVYm5dI7QOmy.jpg', 'TV', 'completed', 12, 12, 8, '["Comedy","Slice of Life","Supernatural"]', 'Doga Kobo', 2017, 'An angel at the top of an angel school has descended to the human world! However, she has already acclimated to the life of the human world so much that she ends up leading a self-indulgent life, skipping school all the time and being absorbed in online games. Gabriel soon forgets about her original goal to make human beings happy and has turned into a lazy and hopeless angel, or a “sloppy angel” in short. Amazingly, she swears to continue to fully enjoy the pleasure of various entertainments of the human world.

(Source: Crunchyroll)', '2026-10-04T15:06:20.990Z', '2026-10-04T15:06:20.990Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('8ff510fd-1931-4802-aedf-6f5a145d5d74', 98292, 'NEW GAME!!', 'NEW GAME!!', 'NEW GAME!!', 'https://cdn.kurzagin.com/anime/covers/98292.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n98292-QChutdQfKyme.jpg', 'TV', 'completed', 12, 12, 7, '["Comedy","Slice of Life"]', 'Doga Kobo', 2017, 'Aoba Suzukaze starts another year designing characters at Eagle Jump, and she can’t wait to meet the newbie recruits…if any are hired. But before she can even unlock her senpai status, she finds herself in a lead designer position for the company’s newest game! Following in her manager’s footsteps, Aoba’s gotta get good if she wants her skills to compete with Ko Yagami’s. Working hard alongside some interesting new coworkers, only time will tell if Aoba gets her best ending.

(Source: Funimation)', '2026-10-04T15:07:06.044Z', '2026-10-04T15:07:06.044Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('11d5749b-ae30-4d77-9499-c72702b7fb54', 20553, 'KanColle', 'Kantai Collection: KanColle', '艦隊これくしょん -艦これ-', 'https://cdn.kurzagin.com/anime/covers/20553.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20553-XVOWgYcNilTF.jpg', 'TV', 'completed', 12, 12, 7, '["Action","Sci-Fi","Slice of Life"]', 'diomedéa', 2015, 'Set in a world where humanity has lost control of the oceans to the “deep sea fleet,” the only hope to counter this threat are the Kanmusu, a group of girls who possess the spirit of Japanese warships. The story revolves around Fubuki, a destroyer who comes to the Chinjufu base to train with other Kanmusu. Watch as their stories unfold! 

(Source: Crunchyroll)', '2026-10-04T15:13:47.550Z', '2026-10-04T15:13:47.550Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('b1a1b2f8-4128-4cb6-8dcf-00ddfd51e78f', 18893, 'Arpeggio of Blue Steel', 'Aoki Hagane no Arpeggio: Ars Nova', '蒼き鋼のアルペジオ', 'https://cdn.kurzagin.com/anime/covers/18893.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n18893-oxCyep74hkb9.jpg', 'TV', 'completed', 12, 12, 7, '["Action","Sci-Fi"]', 'SANZIGEN', 2013, 'In the story, a Fleet of Fog loaded with super weapons suddenly appear all over the world. Without the ability to withstand this fleet, humanity was defeated and could no longer travel the seas. 17 years after the devastating naval war, Chihaya Gunzou and his friends somehow commandeer a Fleet of Fog submarine and rename it I-401. Together with Iona, they take on the Fleet of Fog.

(Source: Anime News Network)', '2026-10-04T15:14:19.951Z', '2026-10-04T15:14:19.951Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('d1da2cd1-981d-4d15-a6e6-62738a55b7db', 9253, 'Steins;Gate', 'Steins;Gate', 'シュタインズ・ゲート', 'https://cdn.kurzagin.com/anime/covers/9253.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n9253-JIhmKgBKsWUN.jpg', 'TV', 'completed', 24, 24, 10, '["Drama","Psychological","Sci-Fi","Thriller"]', 'WHITE FOX', 2011, 'Self-proclaimed mad scientist Okabe Rintarou lives in a small room in Akihabara, where he invents "future gadgets" with fellow lab members Shiina Mayuri, his air-headed childhood friend, and Hashida Itaru, an otaku hacker. The three pass the time by tinkering with their latest creation, a "Phone Microwave" that can be controlled through text messages. 

The lab members soon face a string of mysterious incidents that lead to a game-changing discovery: the Phone Microwave can send emails to the past and thus alter history. Adapted from the critically acclaimed visual novel by 5pb. and Nitroplus, Steins;Gate takes Okabe to the depths of scientific theory and human despair as he faces the dire consequences of changing the past.', '2026-10-04T15:15:12.121Z', '2026-10-04T15:15:12.121Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('067f7498-34fa-489c-aad7-afd08bfe3c12', 20605, 'Tokyo Ghoul', 'Tokyo Ghoul', '東京喰種 トーキョーグール', 'https://cdn.kurzagin.com/anime/covers/20605.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20605-RCJ7M71zLmrh.jpg', 'TV', 'completed', 12, 12, 8, '["Action","Drama","Horror","Mystery","Psychological","Supernatural"]', 'Studio Pierrot', 2014, 'The suspense horror/dark fantasy story is set in Tokyo, which is haunted by mysterious "ghouls" who are devouring humans. People are gripped by the fear of these ghouls whose identities are masked in mystery. An ordinary college student named Kaneki encounters Rize, a girl who is an avid reader like him, at the café he frequents. Little does he realize that his fate will change overnight.

(Source: Anime News Network)', '2026-10-04T15:16:04.160Z', '2026-10-04T15:16:04.160Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('913361ac-e477-44c6-82b7-25358270df80', 21361, 'Granblue Fantasy: The Animation', 'GRANBLUE FANTASY The Animation', 'GRANBLUE FANTASY The Animation', 'https://cdn.kurzagin.com/anime/covers/21361.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21361-NcNDPOPe9oLW.jpg', 'TV', 'completed', 13, 13, 7, '["Adventure","Fantasy"]', 'A-1 Pictures', 2017, 'This is a world of the skies, where many islands drift in the sky.
A boy named Gran and a speaking winged lizard named Vyrn lived in Zinkenstill, an island which yields mysteries. One day, they come across a girl named Lyria.
Lyria had escaped from the Erste Empire, a military government that is trying to rule over this world using powerful military prowess.
Gran and Lyria, in order to escape from the Empire, head out into the vast skies, holding the letter Gran''s father left behind - which said, "I will be waiting at Estalucia, Island of the Astrals".
Note: The first two episodes premiered on January 21st as a special.', '2026-10-04T15:17:37.464Z', '2026-10-04T15:17:37.464Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('a41ab033-f5b5-4849-8554-3d5a2b7feb3d', 97940, 'Black Clover', 'Black Clover', 'ブラッククローバー', 'https://cdn.kurzagin.com/anime/covers/97940.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/97940-1URQdQ4U1a0b.jpg', 'TV', 'dropped', 105, 170, 7, '["Action","Adventure","Comedy","Fantasy"]', 'Studio Pierrot', 2017, 'In a world where magic is everything, Asta and Yuno are both found abandoned at a church on the same day. While Yuno is gifted with exceptional magical powers, Asta is the only one in this world without any. At the age of fifteen, both receive grimoires, magic books that amplify their holder’s magic. Asta’s is a rare Grimoire of Anti-Magic that negates and repels his opponent’s spells. Being opposite but good rivals, Yuno and Asta are ready for the hardest of challenges to achieve their common dream: to be the Wizard King. Giving up is never an option!

(Source: Crunchyroll)', '2026-10-04T15:28:27.680Z', '2026-10-04T15:28:27.680Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('3e82fee0-b7ed-462a-943a-a750ce26dc4b', 21860, 'WorldEnd: What are you doing at the end of the world? Are you busy? Will you save us?', 'Shuumatsu Nani Shitemasu ka? Isogashii desu ka? Sukutte Moratte Ii desu ka?', '終末なにしてますか? 忙しいですか? 救ってもらっていいですか?', 'https://cdn.kurzagin.com/anime/covers/21860.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21860-oQ0YAYNOtGTU.jpg', 'TV', 'completed', 12, 12, 8, '["Drama","Fantasy","Mystery","Romance","Slice of Life","Supernatural"]', 'Satelight', 2017, 'Five hundred years have passed since the humans went extinct at the hands of the fearsome and mysterious ‘Beasts’. The surviving races now make their homes up on floating islands in the sky, out of reach of all but the most mobile of Beasts.

Only a small group of young girls, the Leprechauns, can wield the ancient weapons needed to fend off invasions from these creatures. Into the girls’ unstable and fleeting lives, where a call to certain death could come at any moment, enters an unlikely character: a young man who lost everything in his final battle five hundred years ago, the last living human awakened from a long, icy slumber.

Unable to fight any longer, Willem becomes the father that the girls never had, caring for and nurturing them even as he struggles to come to terms with his new life, in which he feels the pain of helplessly waiting for his loved ones to return home from battle that his ‘Daughter’ once felt for him so long ago. Together, Willem and the girls gradually come to understand what family means and what is truly worth protecting.
', '2026-10-04T15:18:04.535Z', '2026-10-04T15:18:04.535Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('916ef608-467f-4d0b-b5be-e2d66044c336', 9989, 'Anohana: The Flower We Saw That Day', 'Ano Hi Mita Hana no Namae wo Bokutachi wa Mada Shiranai.', 'あの日見た花の名前を僕達はまだ知らない。', 'https://cdn.kurzagin.com/anime/covers/9989.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/9989-pyr6rXlV1oAm.jpg', 'TV', 'completed', 11, 11, 10, '["Drama","Romance","Slice of Life","Supernatural"]', 'A-1 Pictures', 2011, 'Jinta Yadomi and his group of childhood friends have become estranged after a tragic accident split them apart. Now in their high school years, a sudden surprise forces each of them to confront their guilt over what happened that day and come to terms with the ghosts of their past. 
(Source: NIS America)', '2026-10-04T15:18:43.275Z', '2026-10-04T15:18:43.275Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('5324c890-552f-4584-a356-72d830f44e53', 97922, 'INUYASHIKI LAST HERO', 'Inuyashiki', 'いぬやしき', 'https://cdn.kurzagin.com/anime/covers/97922.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/97922-j6ba0Zmq8xOa.jpg', 'TV', 'completed', 11, 11, 8, '["Action","Drama","Psychological","Sci-Fi"]', 'MAPPA', 2017, 'Ichiro Inuyashiki is down on his luck. While only 58 years old, his geriatric looks often have him written off as a pathetic old man by the world around him and he''s constantly ignored and disrespected by his family despite all that he''s done to support them. On top of everything else, his doctor has revealed that he has cancer and it appears that he has little time left in this world. But just when it seems things couldn''t get any worse, a blinding light in the night sky strikes the earth where Ichiro stands. He later wakes up to find himself unscathed, but he soon starts to notice that there''s something…different about himself.

(Source: Crunchyroll)', '2026-10-04T15:19:17.620Z', '2026-10-04T15:19:17.620Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('d83179ff-6646-4b5c-8110-1d9e514c17c2', 97980, 'Re:CREATORS', 'Re:CREATORS', 'Re:CREATORS', 'https://cdn.kurzagin.com/anime/covers/97980.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/97980-kyDniE91Yr9L.jpg', 'TV', 'completed', 22, 22, 9, '["Action","Drama","Fantasy","Mecha","Thriller"]', 'TROYCA', 2017, 'People have created many stories. Joy, sadness, anger, deep emotion. Stories stir up emotion and captivate. However, those emotions are nothing more than the feelings of a spectator. What if the characters in the stories had their own "will"? In their eyes, are we, the creators of the stories, like gods? Revolution for our world. Punishment for the land of the gods. Re:CREATORS. Everyone becomes a Creator.(Source: Amazon)', '2026-10-04T15:19:45.616Z', '2026-10-04T15:19:45.616Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('7bb62343-8544-413e-81cf-5df6fee6716e', 21355, 'Re:ZERO -Starting Life in Another World-', 'Re:Zero kara Hajimeru Isekai Seikatsu', 'Re:ゼロから始める異世界生活', 'https://cdn.kurzagin.com/anime/covers/21355.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21355-f9SjOfEJMk5P.jpg', 'TV', 'completed', 25, 25, 8, '["Action","Adventure","Drama","Fantasy","Psychological","Romance","Thriller"]', 'WHITE FOX', 2016, 'In the story, Subaru Natsuki is an ordinary high school student who is lost in an alternate world, where he is rescued by a beautiful, silver-haired girl. He stays near her to return the favor, but the destiny she is burdened with is more than Subaru can imagine. Enemies attack one by one, and both of them are killed. He then finds out he has the power to rewind death, back to the time he first came to this world. But only he remembers what has happened since.

(Source: Anime News Network)

Notes:
- The first episode aired with a runtime of ~50 minutes as opposed to the standard 25 minute long episode.
- In the Winter 2020 season, Re:ZERO was rebroadcast and re-edited to fit into an hour time-slot. This edit included the first OVA and added slight modifications to certain scenes throughout. It also added an additional scene at the end of the final episode.', '2026-10-04T15:22:45.410Z', '2026-10-04T15:22:45.410Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('57642947-3468-4df9-b413-5da7728ba16c', 108632, 'Re:ZERO -Starting Life in Another World- Season 2', 'Re:Zero kara Hajimeru Isekai Seikatsu 2nd Season', 'Re:ゼロから始める異世界生活 2nd Season', 'https://cdn.kurzagin.com/anime/covers/108632.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/108632-yeLbrgPN4Oni.jpg', 'TV', 'completed', 13, 13, 8, '["Action","Adventure","Drama","Fantasy","Psychological","Thriller"]', 'WHITE FOX', 2020, 'Even after dying countless times, Subaru finally ended the threat of the White Whale and defeated the Witch Cult''s Sin Archbishop representing sloth, Petelgeuse Romaneeconti. But only shortly after overcoming a tragic ending and reuniting with his beloved Emilia, Subaru learns that Rem has been erased from this world, having fallen victim to the White Whale''s Fog of Elimination in the midst of Subaru''s death loop. With the White Whale now gone, Subaru and Emilia are forced to confront a reality they never dreamed would happen.(Source: Crunchyroll)', '2026-10-04T15:23:16.980Z', '2026-10-04T15:23:16.980Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('9ecf012a-5c11-43ff-845c-3cefa5e997b8', 119661, 'Re:ZERO -Starting Life in Another World- Season 2 Part 2', 'Re:Zero kara Hajimeru Isekai Seikatsu 2nd Season Part 2', 'Re:ゼロから始める異世界生活 2nd Season Part 2', 'https://cdn.kurzagin.com/anime/covers/119661.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/119661-9C7DvtL7yfCu.jpg', 'TV', 'completed', 12, 12, 8, '["Action","Adventure","Drama","Fantasy","Psychological","Romance","Thriller"]', 'WHITE FOX', 2021, 'After learning more behind the Death Loop and Witches of Sin, Subaru vows to save Emilia and his friends from further doom.

(Source: Crunchyroll)', '2026-10-04T15:23:44.228Z', '2026-10-04T15:23:44.228Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('30b16275-46ba-470d-bf8b-52b8b0990a00', 20632, 'ALDNOAH.ZERO', 'Aldnoah.Zero', 'アルドノア・ゼロ', 'https://cdn.kurzagin.com/anime/covers/20632.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20632.jpg', 'TV', 'completed', 12, 12, 8, '["Action","Mecha","Sci-Fi"]', 'A-1 Pictures', 2014, 'In 1972, the Apollo 17 mission found a hypergate to Mars on the surface of the moon. Upon landing, astronauts discovered a enchanted utility later referred to as ''Aldnoah'', giving the astronauts a status of superiority. Soon, many humans have relocated to Mars, and have adapted to the name ''Martians''. After Princess Asseylum, a royal Martian princess, descends onto Earth in an attempt to create a treaty between both planets, a war breaks out between Earth and Mars, and Martian soldiers begin to descend from the sky, riding steel giants, intent on exterminating humanity.

(Source: Anime News Network)', '2026-10-04T15:24:38.677Z', '2026-10-04T15:24:38.677Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('bc1ed309-9090-499e-80b8-715a58126341', 12189, 'Hyouka', 'Hyouka', '氷菓', 'https://cdn.kurzagin.com/anime/covers/12189.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/12189-TG0peUcKFqur.jpg', 'TV', 'completed', 22, 22, 7, '["Mystery","Romance","Slice of Life"]', 'Kyoto Animation', 2012, 'Energy-conservative high school student Houtarou Oreki ends up with more than he bargained for when he signs up for the Classic Literature Club at his sister''s behest—especially when he realizes how deep-rooted the club''s history really is. Begrudgingly, Oreki is dragged into an investigation concerning the 45-year-old mystery that surrounds the club room.

Accompanied by his fellow club members, the knowledgeable Satoshi Fukube, the stern but benign Mayaka Ibara, and the ever-curious Eru Chitanda, Oreki must combat deadlines and lack of information with resourcefulness and hidden talent, in order to not only find the truth buried beneath the dust of works created years before them, but of other side cases as well.

Based on the award-winning Koten-bu light novel series, and directed by Yasuhiro Takemoto of Suzumiya Haruhi no Shoushitsu, Hyouka shows that normal life can be full of small mysteries, be it family history, a student film, or even the withered flowers that make up a ghost story.

(Source: MAL Rewrite)', '2026-10-04T15:32:12.300Z', '2026-10-04T15:32:12.300Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('a390ba9f-a23c-45e6-857a-ac9bda5bb53f', 11111, 'Another', 'Another', 'アナザー', 'https://cdn.kurzagin.com/anime/covers/11111.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/11111.jpg', 'TV', 'completed', 12, 12, 7, '["Horror","Mystery","Psychological","Supernatural","Thriller"]', 'P.A.WORKS', 2012, 'When Kouichi Sakakibara transfers to a new school, he senses a frightening atmosphere in his new class, a secret none of them will talk about. At the center is the beautiful Mei Misaki. Kouichi is immediately drawn to her mysterious aura, but he begins to realize that no one else in the class is aware of her presence. Soon after his arrival, what is known as the Calamity begins, and it claims the lives of many students.

(Source: Sentai Filmworks)', '2026-10-04T15:32:35.896Z', '2026-10-04T15:32:35.896Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('2ba5482a-df03-4f8b-a193-a7a254d797bf', 15315, 'Problem Children Are Coming From Another World, Aren''t They?', 'Mondaiji-tachi ga Isekai kara Kuru Sou desu yo?', '問題児たちが異世界から来るそうですよ?', 'https://cdn.kurzagin.com/anime/covers/15315.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/15315.jpg', 'TV', 'completed', 10, 10, 7, '["Action","Comedy","Fantasy","Supernatural"]', 'diomedéa', 2013, 'Izayoi Sakamaki, Asuka Kudou, and You Kasugabe have tremendous psychic powers and are bored with the regular world. An envelope arrives for each person, and when each opens their envelope, they are stunned to see the scenery around them change to a world they had never encountered before. They''ve been summoned by the Black Rabbit to help the community "No Name" to overthrow the Devil King.
(Source: Crunchyroll)', '2026-10-04T15:33:02.186Z', '2026-10-04T15:33:02.186Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('2ff9b143-b0cb-4fcb-ac10-16e58ea0b95b', 10620, 'The Future Diary', 'Mirai Nikki', '未来日記', 'https://cdn.kurzagin.com/anime/covers/10620.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/10620-CsZ2FFSbGpqV.jpg', 'TV', 'completed', 26, 26, 8, '["Action","Horror","Mystery","Psychological","Supernatural","Thriller"]', 'Asread', 2011, 'This psychological thriller, based on the manga written and illustrated by Sakae Esuno, is about Yuki, a loner who''s not very good with people. He prefers to write a diary on his cell phone and talk to his imaginary friend, Deus Ex Machina &ndash; The God of Time and Space. However, Yuki soon learns that Deus is more than a figment of his imagination when he makes Yuki participate in a battle royale with eleven others. The contestants are given special diaries that can predict the future, each diary possessing unique features that give it both advantages and disadvantages. Within the next 90 days, the contestants must try to survive until there is only one left standing. The winner will become the new God of Time and Space.
(Source: FUNimation)', '2026-10-04T15:33:22.313Z', '2026-10-04T15:33:22.313Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('6b18e487-bc94-4a41-adce-ab64bbb86595', 21827, 'Violet Evergarden', 'Violet Evergarden', 'ヴァイオレット・エヴァーガーデン', 'https://cdn.kurzagin.com/anime/covers/21827.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21827-ROucgYiiiSpR.jpg', 'TV', 'completed', 13, 13, 10, '["Drama","Fantasy","Slice of Life"]', 'Kyoto Animation', 2018, 'A certain point in time, in the continent of Telesis. The great war which divided the continent into North and South has ended after four years, and the people are welcoming a new generation. Violet Evergarden, a young girl formerly known as “the weapon”, has left the battlefield to start a new life at CH Postal Service. There, she is deeply moved by the work of “Auto Memories Dolls”, who carry people''s thoughts and convert them into words. Violet begins her journey as an Auto Memories Doll, and comes face to face with various people''s emotions and differing shapes of love. There are words Violet heard on the battlefield, which she cannot forget. These words were given to her by someone she holds dear, more than anyone else. She does not yet know their meaning but she searches to find it.

(Source: Anime News Network)', '2026-10-04T15:36:14.888Z', '2026-10-04T15:36:14.888Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('ae972602-1cdc-48fd-8ed1-42f73e05646b', 97, 'Last Exile', 'Last Exile', 'ラストエグザイル', 'https://cdn.kurzagin.com/anime/covers/97.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/97-kaw3UsKX7IkQ.jpg', 'TV', 'completed', 26, 26, 8, '["Action","Adventure","Sci-Fi"]', 'GONZO', 2003, 'It''s the dawn of the Golden Age of Aviation on planet Prester, and retro-futuristic sky vehicles known as vanships dominate the horizon. Claus Valca &ndash; a flyboy born with the right stuff &ndash; and his fiery navigator Lavie are fearless racers obsessed with becoming the first sky couriers to cross the Grand Stream in a vanship. But when the high-flying duo encounters a mysterious girl named Alvis, they are thrust into the middle of an endless battle between Anatoray and Disith &ndash; two countries systematically destroying each other according to the code of chivalric warfare. Lives will be lost and legacies determined as Claus and Lavie attempt to bring peace to their world by solving the riddle of its chaotic core.

(Source: Funimation)', '2026-10-04T15:40:24.390Z', '2026-10-04T15:40:24.390Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('de1b4dcb-1bc1-41a6-8656-8700e28115ba', 18095, 'No-Rin', 'Nourin', 'のうりん', 'https://cdn.kurzagin.com/anime/covers/18095.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/18095-jpbVsYZQqzH6.jpg', 'TV', 'completed', 12, 12, 7, '["Comedy","Ecchi","Romance"]', 'SILVER LINK.', 2014, 'When the national idol Kusakabe Yuka suddenly retired from the entertainment business, it shocked the world and it devastated teenager Hata Kosaku. Kosaku was Yuka''s biggest fan and her departure left him depressed. His classmates at the Tamo Agriculture School finally are able to get him to leave his room and attend his class, but to everyone''s amazement, Kusakabe Yuka (her stage name) comes into the class under the name Kinoshita Ringo as a transfer student. Kosaku realizes he has the once in a lifetime opportunity to get to personally know his dream girl and, together with his group of friends, try to find out why she is here and become closer than just classmates.
(Source: MangaHelpers)', '2026-10-04T23:11:24.391Z', '2026-10-04T23:11:24.391Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('6c6747f2-a4de-4dea-a2ec-d8aca52c13ef', 113415, 'JUJUTSU KAISEN', 'Jujutsu Kaisen', '呪術廻戦', 'https://cdn.kurzagin.com/anime/covers/113415.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/113415-jQBSkxWAAk83.jpg', 'TV', 'dropped', 3, 24, 7, '["Action","Drama","Supernatural"]', 'MAPPA', 2020, 'A boy fights... for "the right death."

Hardship, regret, shame: the negative feelings that humans feel become Curses that lurk in our everyday lives. The Curses run rampant throughout the world, capable of leading people to terrible misfortune and even death. What''s more, the Curses can only be exorcised by another Curse.

Itadori Yuji is a boy with tremendous physical strength, though he lives a completely ordinary high school life. One day, to save a friend who has been attacked by Curses, he eats the finger of the Double-Faced Specter, taking the Curse into his own soul. From then on, he shares one body with the Double-Faced Specter. Guided by the most powerful of sorcerers, Gojou Satoru, Itadori is admitted to the Tokyo Metropolitan Technical High School of Sorcery, an organization that fights the Curses... and thus begins the heroic tale of a boy who became a Curse to exorcise a Curse, a life from which he could never turn back.

(Source: Crunchyroll)

Note: The first episode received an early web premiere on September 19th, 2020. The regular TV broadcast started on October 3rd, 2020.', '2026-10-04T23:13:00.718Z', '2026-10-04T23:13:00.718Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('4fb2d05d-9c10-4fc8-a4ff-e8f2c61540cd', 127230, 'Chainsaw Man', 'Chainsaw Man', 'チェンソーマン', 'https://cdn.kurzagin.com/anime/covers/127230.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/127230-o8IRwCGVr9KW.jpg', 'TV', 'paused', 1, 12, NULL, '["Action","Drama","Horror","Supernatural"]', 'MAPPA', 2022, 'Denji is a teenage boy living with a Chainsaw Devil named Pochita. Due to the debt his father left behind, he has been living a rock-bottom life while repaying his debt by harvesting devil corpses with Pochita.
One day, Denji is betrayed and killed. As his consciousness fades, he makes a contract with Pochita and gets revived as "Chainsaw Man" — a man with a devil''s heart.

(Source: Crunchyroll)', '2026-10-04T23:14:22.518Z', '2026-10-04T23:14:22.518Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('34563111-01af-4ecf-8e46-ec85acbd6bf9', 18153, 'Beyond the Boundary', 'Kyoukai no Kanata', '境界の彼方', 'https://cdn.kurzagin.com/anime/covers/18153.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/18153-Pw3uKfv6ZNqP.jpg', 'TV', 'completed', 12, 12, 8, '["Action","Drama","Fantasy","Slice of Life","Supernatural"]', 'Kyoto Animation', 2013, 'They should never have met. They shouldn''t even exist. But when they come together, the entire world will change. The last surviving member of her clan, Mirai Kuriyama is cursed with the terrifying ability to control and manipulate blood, a power so heretical that she is shunned even by those with the ability to understand her "gift". Akihito Kanbara is only half human, but while the monstrous other half of his lineage seems to have doomed him to a life alone, it has also given him near invulnerability in the form of rapid healing. Alone, their futures seem bleak, but when a chance encounter brings them together, it becomes clear that they share more than just an unexpected bond. Together they share a destiny and a mission that only the two of them together may be strong enough to survive.

(Source: Sentai Filmworks)', '2026-10-04T23:20:44.054Z', '2026-10-04T23:20:44.054Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('de96f15a-6e56-4998-b432-761a6f71a1d8', 20963, 'Beyond the Boundary -I''LL BE HERE-: Future', 'Kyoukai no Kanata: I''LL BE HERE - Mirai-hen', '劇場版 境界の彼方 I''LL BE HERE 未来篇', 'https://cdn.kurzagin.com/anime/covers/20963.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n20963-n5v8YuHRpyqj.jpg', 'MOVIE', 'completed', 1, 1, 8, '["Action","Drama","Fantasy","Romance","Slice of Life","Supernatural"]', 'Kyoto Animation', 2015, 'This is the second part of a two-part movie. The story takes place one year after the TV series.', '2026-10-04T23:21:13.565Z', '2026-10-04T23:21:13.565Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('4bba755c-013a-4334-99a0-463c10c73553', 20768, 'Beyond the Boundary -I''LL BE HERE-: Past', 'Kyoukai no Kanata: I''LL BE HERE - Kako-hen', '劇場版 境界の彼方 I''LL BE HERE 過去篇', 'https://cdn.kurzagin.com/anime/covers/20768.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n20768-XaSSBUJpLqNy.jpg', 'MOVIE', 'completed', 1, 1, 8, '["Drama","Fantasy","Slice of Life","Supernatural"]', 'Kyoto Animation', 2015, 'This is the first part of a two-part movie. The story is a recap of the TV series.', '2026-10-04T23:21:43.218Z', '2026-10-04T23:21:43.218Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('122487c8-b0ae-4cff-859c-e50f54e6865f', 21776, 'Miss Kobayashi''s Dragon Maid', 'Kobayashi-san Chi no Maidragon', '小林さんちのメイドラゴン', 'https://cdn.kurzagin.com/anime/covers/21776.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21776-hI5smQyXFK7G.jpg', 'TV', 'completed', 13, 13, 8, '["Comedy","Fantasy","Slice of Life"]', 'Kyoto Animation', 2017, 'What happens when a drunken promise leads to living with a dragon? That’s Miss Kobayashi’s new reality when Tohru appears in her life. With a maid-slash-dragon in her home, she’s experiencing a whole new level of domestic bliss! But the dragons don’t stop there. On a mission to find Tohru appears Kanna, a little dragon with a big attitude. Before she knows it, Kobayashi’s got a house full of dragons—one serving tail and the other serving serious moe! Together, they live side by side with only the occasional disaster…well, maybe. But nothing beats coming home to the warm welcome of a dragon maid!

(Source: Funimation)', '2026-10-04T23:22:13.648Z', '2026-10-04T23:22:13.648Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('65250b24-2018-4e77-81ac-612635ba5c26', 21087, 'One-Punch Man', 'One Punch Man', 'ワンパンマン', 'https://cdn.kurzagin.com/anime/covers/21087.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21087-sHb9zUZFsHe1.jpg', 'TV', 'completed', 12, 12, 8, '["Action","Comedy","Sci-Fi","Supernatural"]', 'MADHOUSE', 2015, 'Saitama has a rather peculiar hobby, being a superhero, but despite his heroic deeds and superhuman abilities, a shadow looms over his life. He''s become much too powerful, to the point that every opponent ends up defeated with a single punch.

The lack of challenge has driven him into a state of apathy, as he watches his life pass by having lost all enthusiasm, at least until he''s unwillingly thrust in the role of being a mentor to the young and revenge-driven Genos.   

', '2026-10-04T23:25:02.078Z', '2026-10-04T23:25:02.078Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('c30f7599-8bcb-46fe-a540-a6891ba680c8', 97668, 'One-Punch Man Season 2', 'One Punch Man 2', 'ワンパンマン 2', 'https://cdn.kurzagin.com/anime/covers/97668.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/97668-8Yo3iH2fxbKR.jpg', 'TV', 'completed', 12, 12, 8, '["Action","Comedy","Sci-Fi","Supernatural"]', 'J.C.STAFF', 2019, 'Saitama is a hero who only became a hero for fun. After three years of “special training,” he’s become so strong that he’s practically invincible. In fact, he’s too strong—even his mightiest opponents are taken out with a single punch. Now, the great seer Madame Shibabawa’s prediction about the Earth being doomed seems to be coming true as the frequency of monster incidents escalates. Alongside Genos, his faithful disciple, Saitama begins his official hero duties as a member of the Hero Association, while Garou, a man utterly fascinated by monsters, makes his appearance.', '2026-10-04T23:25:29.658Z', '2026-10-04T23:25:29.658Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('f0874781-1849-45e1-bd13-ad1149308ba9', 101351, 'Happy Sugar Life', 'Happy Sugar Life', 'ハッピーシュガーライフ', 'https://cdn.kurzagin.com/anime/covers/101351.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/101351-gAmnBuRCb1U0.png', 'TV', 'completed', 12, 12, 8, '["Drama","Horror","Mystery","Psychological","Romance"]', 'Ezo’la', 2018, 'Satou Matsuzaka is a beautiful high schooler who has a reputation for being permissive with men. However, a chance encounter with a young girl named Shio Koube makes Satou realize that this is her first and only true feeling of love. Telling others that she lives with her aunt, Satou secretly shares an apartment with Shio. Despite her innocent appearance, Satou is willing to do anything to protect her beloved, resorting to desperate measures to ensure that their "happy sugar life" remains intact. (Source: MAL Rewrite)', '2026-10-09T00:51:47.203Z', '2026-10-09T00:51:47.203Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('53a59287-5ba4-4c05-a323-698d10340bad', 21131, 'The Asterisk War', 'Gakusen Toshi Asterisk', '学戦都市アスタリスク', 'https://cdn.kurzagin.com/anime/covers/21131.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21131-NuvCaPakVhMS.jpg', 'TV', 'completed', 12, 12, 8, '["Action","Comedy","Ecchi","Fantasy","Romance","Sci-Fi"]', 'A-1 Pictures', 2015, 'Invertia (meteor storm)… an unprecedented disaster that struck the world during the 20th century.

Because of this disaster, numerous cities around the world were destroyed. However, within the meteor, an unknown element called mana (the all-encompassing element), was discovered, which allowed human technology to make rapid strides.

This also gave rise to a new species of human born with unique skills – the Star Pulse Generation (Genestella).

The setting for the world’s greatest comprehensive battle spectacle, the Festas (Star Warrior Festivals), is an academy city above the water surrounded by six academies called Rikka also commonly known as Asterisk. Having transferred into Seidoukan Academy in order to fulfill his own wish, scholarship student Ayato Amagiri swears he too will fight in this city.

Burning souls race…

The curtain rises on this school battle spectacle!

(Source: Crunchyroll)', '2026-10-07T03:20:01.937Z', '2026-10-07T03:20:01.937Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('456b0df4-f25c-48f7-9a95-5ff6ba54a1c8', 20920, 'Is It Wrong to Try to Pick Up Girls in a Dungeon?', 'Dungeon ni Deai wo Motomeru no wa Machigatteiru Darou ka', 'ダンジョンに出会いを求めるのは間違っているだろうか', 'https://cdn.kurzagin.com/anime/covers/20920.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20920-QZeO1gVTQSUZ.jpg', 'TV', 'completed', 13, 13, 8, '["Action","Adventure","Comedy","Fantasy","Romance"]', 'J.C.STAFF', 2015, 'Some adventurers delve into the sprawling labyrinths beneath the city of Orario to find fame and fortune. Others come to test their skills against the legions of monsters lurking in the darkness below. However, Bell Cranel’s grandfather told him a different reason: it’s a great place to rescue (and subsequently meet) girls! Now that Bell’s a dungeon delver himself, the ladies he’s encountering aren’t the helpless damsels in distress he’d imagined, and one of them, the beautiful swordswoman Ais Wallenstein, keeps rescuing Bell instead. As embarrassing as that is, it’s nothing compared to what happens when goddesses get involved. Freya, Hephaistos, and Loki, with their powerful Familias, are intimidating enough, but there’s one goddess whose relationship with Bell is certain to spark trouble.

(Source: Sentai Filmworks)', '2026-10-07T03:20:29.686Z', '2026-10-07T03:20:29.686Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('521a26dd-d341-4d5a-a00e-63bd9ff1f2b5', 101167, 'Is It Wrong to Try to Pick Up Girls in a Dungeon? II', 'Dungeon ni Deai wo Motomeru no wa Machigatteiru Darou ka II', 'ダンジョンに出会いを求めるのは間違っているだろうかⅡ', 'https://cdn.kurzagin.com/anime/covers/101167.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/101167-VirZ21Z7DGZk.jpg', 'TV', 'completed', 12, 12, 8, '["Action","Adventure","Comedy","Fantasy","Romance"]', 'J.C.STAFF', 2019, 'There''s rarely a dull moment when you''re the champion of a tiny Familia, and things only get rougher for Bell when the God Apollo declares war on Hestia and her followers. With Apollo''s Familia able to field a hundred times as many men, Hestia will have to work a lot of favors to keep her Familia from being completely destroyed.

Even if Bell and Hestia manage to pull off the impossible, a major debt that Hestia owes is about to come due and Lili''s sordid past comes back to haunt her! Which means that when Bell and his friends come to Lili''s aid, it sets into motion yet another impending clash of the titans that may destroy everything!

(Source: Sentai Filmworks)', '2026-10-07T03:20:58.869Z', '2026-10-07T03:20:58.869Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('af611d48-572a-4b53-9a80-0414849eabf3', 21390, 'The Asterisk War 2', 'Gakusen Toshi Asterisk 2', '学戦都市アスタリスク 2', 'https://cdn.kurzagin.com/anime/covers/21390.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21390-Sc4OlDjVKATs.jpg', 'TV', 'completed', 12, 12, 8, '["Action","Comedy","Ecchi","Fantasy","Romance","Sci-Fi"]', 'A-1 Pictures', 2016, 'Less than a century ago a meteor collided with the planet''s surface and the resulting disaster caused the next generation of humanity to develop a wide variety of amazing abilities. In the center of the meteor''s crater lies Rikka, a system of six academies known as the Asterisk. Ayato Amagiri enters the Asterisk as a transfer student hoping to compete in a special battle event known as the Festa. However, he quickly finds himself on the bad side of one of the strongest fighters around—the beautiful but fiery Julis-Alexa von Riessfeld. To stand against her he''ll have to rely on his own sword-wielding ability, but when the tables turn, will they be able to team up to take down the competition?

(Source: Anime News Network)', '2026-10-07T03:22:36.277Z', '2026-10-07T03:22:36.277Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('f59b4fdb-7e16-4c46-9e72-340c40eea284', 129193, 'The Executioner and Her Way of Life', 'Shokei Shoujo no Virgin Road', '処刑少女の生きる道（バージンロード）', 'https://cdn.kurzagin.com/anime/covers/129193.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/129193-ac5BiVxEdZ02.jpg', 'TV', 'completed', 12, 12, 8, '["Action","Adventure","Drama","Fantasy"]', 'J.C.STAFF', 2022, 'When interdimensional travelers from an otherworldly land known as “Japan” appear, they often bring death and destruction. It’s up to Executioners like Menou to track and exterminate the Lost Ones before they wreak havoc. When Menou encounters a beguiling Lost One named Akari, it’s bloody business as usual… until Menou discovers Akari can cheat death, that is. Even so, Menou has a job to do, and she is committed to her executioner’s mission come hell or high water — provided her newly stirring feelings don’t get in the way.

(Source: Sentai Filmworks)

Note: The first two episodes received an advance release on Abema on March 20, 2022. The regular TV broadcast started on April 2, 2022.', '2026-10-07T03:22:58.021Z', '2026-10-07T03:22:58.021Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('5435deeb-126e-455b-b31f-95f02f4865cd', 162780, 'Gushing Over Magical Girls', 'Mahou Shoujo ni Akogarete', '魔法少女にあこがれて', 'https://cdn.kurzagin.com/anime/covers/162780.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/162780-rZ0KpsfCg2IA.jpg', 'TV', 'completed', 13, 13, 9, '["Comedy","Ecchi","Mahou Shoujo","Slice of Life"]', 'Asahi Production', 2024, 'Hiiragi Utena is a major fangirl of the magical girls protecting her city, so when she has the chance to become one herself, she leaps at the chance to join their technicolor ranks… but when she transforms, she learns she isn’t fated to be a daring do-gooder, but rather a villain on the side of evil! At first she tries to quit her new gig as the leader of the local baddies, but she quickly realizes she enjoys it and is a total natural at tormenting the magical girls she loves so much. With both a bang and a whimper, Hiragi’s journey as a magical-girl-tormenting sadist has begun!

(Source: HIDIVE)', '2026-10-07T03:24:26.572Z', '2026-10-07T03:24:26.572Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('9cadf0fe-54fe-4d8e-a235-7cce3c863729', 20807, 'Prison School', 'Prison School', '監獄学園〈プリズンスクール〉', 'https://cdn.kurzagin.com/anime/covers/20807.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20807-IHYC4Qby3dkT.jpg', 'TV', 'completed', 12, 12, 8, '["Comedy","Ecchi"]', 'J.C.STAFF', 2015, 'Hachimitsu Private Academy was a revered and elite all-girls'' boarding school on the outskirts of Tokyo...once upon a time. But with the new school year comes a revision to school policy: Boys are to be admitted into the student body for the first time ever. But on his first day at Hachimitsu, Kiyoshi Fujino discovers that he''s one of only five boys enrolled at the school. Their numbers overwhelmed by the thousand girls in the student body, is it heaven or hell that awaits these five (un)fortunates?!.

(Source: Anime News Network)', '2026-10-09T09:46:24.064Z', '2026-10-09T09:46:24.064Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('8314277a-3f02-4a20-bc65-795fbce893b7', 107201, 'In/Spectre', 'Kyokou Suiri', '虚構推理', 'https://cdn.kurzagin.com/anime/covers/107201.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/107201-XZHSg0HdC9kR.jpg', 'TV', 'completed', 12, 12, 8, '["Comedy","Mystery","Romance","Supernatural"]', 'Brain''s Base', 2020, 'At the young age of 11, Kotoko Iwanaga was abducted by youkai for two weeks and asked to become their "God of Wisdom," a mediator between the spirit and human worlds, to which the girl quickly agreed but at the cost of her right eye and left leg. Now, six years later, whenever youkai wish for their problems to be solved, they make their way to Kotoko for consultation.

Meanwhile, Kurou Sakuragawa, a 22-year-old university student, has just broken up with his girlfriend after he fled alone when the two encountered a kappa. Seeing this as her chance to become closer with him, Kotoko immediately makes her move, hoping to get married to Kurou one day. However, she quickly realizes there is something more to Kurou. With this knowledge, she asks for his help in solving the various issues presented by the supernatural, all the while wishing her newfound partner will eventually reciprocate her feelings.
', '2026-10-07T03:27:49.803Z', '2026-10-07T03:27:49.803Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('53a4681f-ba4c-4b1b-9f40-477ccb111e51', 117343, 'Talentless Nana', 'Munou na Nana', '無能なナナ', 'https://cdn.kurzagin.com/anime/covers/117343.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/117343-w0m2gfOlQphZ.jpg', 'TV', 'completed', 13, 13, 10, '["Drama","Horror","Mystery","Psychological","Supernatural","Thriller"]', 'Bridge', 2020, 'It is the year 20XX. Earth has been assaulted by monsters known as ''the Enemy of Humanity''. In order to deal with this threat, special schools comprised of teenagers with extraordinary abilities were formed. These people, who came to be known as ''the Talented'', have abilities that defy the rules of reality. Among these superpowered individuals was an outlier, someone who was sent to one of these schools despite having no innate special abilities whatsoever. This is the story of our protagonist, who attempts to defeat the Enemies of Humanity through the use of intelligence and manipulation.
', '2026-10-07T03:28:20.921Z', '2026-10-07T03:28:20.921Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('04a4e967-4cd7-4cac-a3fa-d206afc1581f', 20556, 'Nanana''s Buried Treasure', 'Ryuugajou Nanana no Maizoukin', '龍ヶ嬢七々々の埋蔵金', 'https://cdn.kurzagin.com/anime/covers/20556.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20556-7jD8D1p8FEyi.jpg', 'TV', 'completed', 11, 11, 8, '["Comedy","Mystery","Supernatural"]', 'A-1 Pictures', 2014, '"I''m going to build a place where young people can challenge to reach any of their dreams!"

The 7 genius students, known as the GREAT 7, launched a project to construct an artificial island called Nanae Island to realize their leader, Nanana Ryugajo''s peculiar idea. 

12 years later, with a total population of 100,000 people with as much as 80% of those inhabitants being students, Nanae Island has successfully become prosperous as a special student zone. One of the island''s newest residents was Jugo Yama -- a high school student who had just transferred to the island after being disowned by his father. One day, Jugo finds in his own apartment the earth-bound spirit of the late Nanana Ryugajo, who was murdered by someone 10 years ago! Jugo''s plan of living alone was suddenly thwarted by this strange roommate. 

The original novel "Nanana''s Buried Treasure" won the Grand Prize of the 13th Entertainment Awards, which was the first Grand Prize in eight years. This anime series features the adventures and challenges of Jugo Yama as he searches through the historic ruins of Nanae Island for the great treasures, A.K.A "Nanana''s Collection," along with the extraordinary characters he meets along the way. The mysterious puzzles of the ruins! The excitement of the treasure hunt! The strategic maneuvers and battles of thought and reason between the characters! Nanana''s Buried Treasure is an adventure you won''t want to miss! 

(Source: Aniplex USA)', '2026-10-07T03:28:44.583Z', '2026-10-07T03:28:44.583Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('6bf39f40-832d-4aa2-a031-9ea2e83417a4', 13655, 'Little Busters!', 'Little Busters!', 'リトルバスターズ!', 'https://cdn.kurzagin.com/anime/covers/13655.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/13655-XBJOquNEggcN.jpg', 'TV', 'completed', 26, 26, 8, '["Comedy","Drama","Slice of Life","Supernatural"]', 'J.C.STAFF', 2012, 'When tragedy struck Riki Naoe as a child, he was rescued from grief over his parent''s deaths when four other kids "recruited" him for their group&mdash;the "Little Busters." Now in high school, Riki and the other Busters are still fast friends, and though their vision of being heroes for justice may have faded, they''d still do anything for each other. Which is why Riki is now on TWO special missions. The not so secret one: recruiting new members so the Busters can form a baseball team. Preferably FEMALE recruits, as the current dude/babe ratio is an inconvenient 4 to 1. The OTHER mission, though... That''s the strange one. Because Riki and Rin, the group''s singular girl, are receiving odd messages, delivered by cats, concerning the existence of a "secret world" and assigning them tasks they have to complete. Were their youthful dreams of being crusaders not so fanciful after all? Or is there something even more vital at stake? Between steeling his courage to talk to girls, dealing with his own narcolepsy and facing his feelings concerning Rin, Riki may just need the strength of a superhero to solve the ultimate mystery of the Little Busters!
(Source: Sentai Filmworks)', '2026-10-09T06:06:02.515Z', '2026-10-09T06:06:02.515Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('a024e14f-7b12-4c21-b35b-b7d20ed7afcf', 18195, 'Little Busters! Refrain', 'Little Busters!: Refrain', 'リトルバスターズ! ~Refrain~', 'https://cdn.kurzagin.com/anime/covers/18195.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/n18195-RnrDm1J9XO59.jpg', 'TV', 'completed', 13, 13, 8, '["Drama","Mystery","Supernatural"]', 'J.C.STAFF', 2013, 'Riki Naoe and his teammates have finally formed a complete baseball team for the Little Busters. When the Little Busters reunite, there''s a strange sense of déjà vu, as the personal mysteries and idiosyncrasies that have permeated the game coalesce into something unexpected. As the team members fall into their roles, the pieces of the puzzle begin to fall into place. And as Riki learns the secrets behind his narcolepsy, a stunning truth about this world will be revealed, one that will change everything. Will the game continue into extra innings, or will it be called before the final player goes to bat? Riki made the team and his teammates came, but the next pitch may throw everyone in LITTLE BUSTERS! REFRAIN!(Source: Sentai Filmworks)', '2026-10-09T06:06:25.017Z', '2026-10-09T06:06:25.017Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('a42b50cf-b062-4c19-9f71-bc589dc45ced', 108388, 'High School Prodigies Have It Easy Even In Another World', 'Choujin Koukousei-tachi wa Isekai demo Yoyuu de Ikinuku you desu!', '超人高校生たちは異世界でも余裕で生き抜くようです!', 'https://cdn.kurzagin.com/anime/covers/108388.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/108388-eZP0Niki1Ca2.jpg', 'TV', 'completed', 12, 12, 7, '["Action","Adventure","Drama","Ecchi","Fantasy"]', 'project No.9', 2019, 'Seven Japanese high school prodigies have taken the world by storm, exercising their mind-blowing abilities in everything from politics to entertainment. But when their plane crashes one day, these geniuses awaken to find themselves in a different realm -one that''s home to magic and beast folk! While such strange new surroundings might throw an average person for a loop, these prodigies take their situation in stride...and then some! With the greatest minds and talents known to Earth, this dream team is about to turn the other world on its head!

(Source: Yen Press)', '2026-10-09T09:44:24.485Z', '2026-10-09T09:44:24.485Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('d2b52826-633e-4325-809e-73d5bd50cb13', 21428, 'Grimgar of Fantasy and Ash', 'Hai to Gensou no Grimgar', '灰と幻想のグリムガル', 'https://cdn.kurzagin.com/anime/covers/21428.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21428-WXeLTDwfmKI5.jpg', 'TV', 'completed', 12, 12, 9, '["Action","Adventure","Drama","Fantasy"]', 'A-1 Pictures', 2016, 'Fear, survival, instinct. Thrown into a foreign land with nothing but hazy memories and the knowledge of their name, they can feel only these three emotions resonating deep within their souls. A group of strangers is given no other choice than to accept the only paying job in this game-like world—the role of a soldier in the Reserve Army—and eliminate anything that threatens the peace in their new world, Grimgar.

When all of the stronger candidates join together, those left behind must create a party together to survive: Manato, a charismatic leader and priest; Haruhiro, a nervous thief; Yume, a cheerful hunter; Shihoru, a shy mage; Mogzo, a kind warrior; and Ranta, a rowdy dark knight. Despite its resemblance to one, this is no game—there are no redos or respawns; it is kill or be killed.

It is now up to this ragtag group of unlikely fighters to survive together in a world where life and death are separated only by a fine line.
', '2026-10-09T09:47:04.570Z', '2026-10-09T09:47:04.570Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('161fca00-1ef4-4ea6-a5c4-db2f56b04cb7', 99457, 'Maquia: When the Promised Flower Blooms', 'Sayonara no Asa ni Yakusoku no Hana wo Kazarou', 'さよならの朝に約束の花をかざろう', 'https://cdn.kurzagin.com/anime/covers/99457.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/99457-OvX44AF17mEL.jpg', 'MOVIE', 'completed', 1, 1, 10, '["Drama","Fantasy","Psychological"]', 'P.A.WORKS', 2018, 'The people of Iorph live far away from the lands of men, weaving the happenings of each day into a fabric called Hibiol. They live for centuries while maintaining their youthful appearance. Maquia, an orphaned Iorph girl, lives her life in an oasis surrounded by friends, yet somehow feels “alone”. But the tranquil lives of the Iorph are shattered in an instant when the Mezarte army invades their territory on a dragon fleet, seeking the blood that grants the Iorph long life. Maquia manages to escape, but loses her friends and her home in the chaos. She then encounters an orphaned baby who is “alone”. Maquia raises this boy "Ariel", with the help of some new friends. But as the era changes, the bond between Maquia and Ariel changes too, amidst a backdrop of racial tensions between the Iorph and the Mezarte. This is a story of irreplaceable time, woven by two lonely people who can only find solace in each other.

(Source: Eleven Arts)', '2026-10-09T09:47:37.913Z', '2026-10-09T09:47:37.913Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('9802c436-33d4-43f8-9c18-72b9602c8e84', 99423, 'DARLING in the FRANXX', 'Darling in the Franxx', 'ダーリン・イン・ザ・フランキス', 'https://cdn.kurzagin.com/anime/covers/99423.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/99423-OQfem628gdxD.jpg', 'TV', 'completed', 24, 24, 9, '["Action","Drama","Mecha","Psychological","Romance","Sci-Fi"]', 'TRIGGER', 2018, 'The distant future: Humanity established the mobile fort city, Plantation, upon the ruined wasteland. Within the city were pilot quarters, Mistilteinn, otherwise known as the “Birdcage.” That is where the children live... Their only mission in life was the fight. Their enemies are the mysterious giant organisms known as Kyoryu. The children operate robots known as FRANXX in order to face these still unseen enemies. Among them was a boy who was once called a child prodigy: Code number 016, Hiro. One day, a mysterious girl called Zero Two appears in front of Hiro. “I’ve found you, my Darling.”

(Source: Crunchyroll)', '2026-10-04T15:16:53.405Z', '2026-10-09T09:47:57.452Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('f0361939-0e40-4dce-8342-587b2e503444', 21696, 'Urara Meirocho', 'Urara Meirochou', 'うらら迷路帖', 'https://cdn.kurzagin.com/anime/covers/21696.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21696-j2vBJIcPIMhn.png', 'TV', 'completed', 12, 12, 8, '["Comedy","Fantasy","Slice of Life"]', 'J.C.STAFF', 2017, 'The story is set in Meiro-chou, a town where all-female diviners (uranaishi) live and where girls from all over the country yearn to become the top diviner — "Urara." Today, a solitary girl named Chiya enters the town''s gates. However, she has another purpose coming here, besides becoming the Urara. Chiya''s days as an apprentice diviner begin as she meets three friends — the earnest Kon, Koume who is a fan of Western culture, and the shy Nono.
(Source: Anime News Network)', '2026-10-10T03:54:12.469Z', '2026-10-10T03:54:12.469Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('d0490114-045c-4658-877a-dcdf6ddbfc23', 105190, 'Darwin''s Game', 'Darwin''s Game', 'ダーウィンズゲーム', 'https://cdn.kurzagin.com/anime/covers/105190.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/105190-HhqT6N5MJCpE.jpg', 'TV', 'completed', 11, 11, 7, '["Action","Mystery","Sci-Fi","Thriller"]', 'Nexus', 2020, 'Kaname Sudou, an ordinary high school student, receives an invitation email to try a mysterious app called "Darwin''s Game." Kaname, upon launching the app, is drawn into a game where players fight one another using superpowers called Sigils. Without knowing the reason for all this, can Kaname survive furious battles against the powerful players who attack him?

(Source: Aniplex of America)

Note: The first episode aired with a runtime of ~48 minutes as opposed to the standard 24 minute long episode.', '2026-10-10T03:56:46.777Z', '2026-10-10T03:56:46.777Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('0db41af5-20e6-4bea-b385-221cb74d028c', 207329, 'The Laid-Off Cheat-Granting Mage Enjoys a Second Lease on Life', 'Tsuihou Sareta Cheat Fuyo Majutsushi wa Kimama na Second Life wo Ouka Suru.: Ore wa Buki dake ja Naku, Arayuru Mono ni "Kyouka Point" wo Fuyo Dekiru shi, Ore no Ishi de Itsudemo Kouka wo Kaijo Dekiru kedo, Nokotta Hitotachi Daijoubu?', '追放されたチート付与魔術師は気ままなセカンドライフを謳歌する。　～俺は武器だけじゃなく、あらゆるものに『強化ポイント』を付与できるし、俺の意思でいつでも効果を解除できるけど、残った人たち大丈夫？～', 'https://cdn.kurzagin.com/anime/covers/207329.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/207329-9IqRSKIsM3TC.jpg', 'TV', 'planning', 0, NULL, NULL, '["Adventure","Comedy","Fantasy","Slice of Life"]', 'P.A.WORKS', 2026, 'Rein, an enchanter, is suddenly expelled from his guild one day. But instead of despairing, he declares, “Now I can do anything!” and begins reclaiming the massive number of enhancement points he once poured into his guildmates’ gear, setting off on a brand-new path as an adventurer.
Gathering around him are people carrying wounds that don’t fade easily: a genius adventurer who shut her heart after her party was slaughtered, a warrior who lost her family, and an assassin raised from childhood to kill. Yet Rein never rejects their pasts or their scars—he accepts them all with bright, straightforward warmth.
The stage is a unique fantasy world where Uzis, slingshots, and even yakuza exist side by side. But in this world, the more people rely on convenient technology, the more their magic weakens, and adventurers grow fragile.
Intelligent, vicious monsters roam freely, while in the underworld, outlaws bare their greed and ambition as schemes and betrayals intertwine. In a world where ideals and justice are easily crushed, adventurers fight on with nothing but their magic and their convictions.
This is the story of those who have lost their place in the world finding a new way to live. Rein and his companions’ wild, free-spirited second life begins now!
(Source: The Laid-Off Cheat-Granting Mage Enjoys a Second Lease on Life Site)', '2026-10-10T12:52:53.562Z', '2026-10-10T12:52:53.562Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('1a54ef9a-9411-45f0-816b-89475f635f69', 101227, 'Didn''t I Say to Make My Abilities Average in the Next Life?!', 'Watashi, Nouryoku wa Heikinchi de tte Itta yo ne!', '私、能力は平均値でって言ったよね！', 'https://cdn.kurzagin.com/anime/covers/101227.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/101227-hGIZHBjTowqe.jpg', 'TV', 'completed', 12, 12, 8, '["Action","Adventure","Comedy","Fantasy"]', 'project No.9', 2019, 'When she turns ten years old, Adele von Ascham is hit with a horrible headache–and memories of her previous life as an eighteen-year-old Japanese girl named Kurihara Misato. That life changed abruptly, however, when Misato died trying to aid a little girl and met god. During that meeting, she made an odd request and asked for average abilities in her next life. But few things–especially wishes–ever go quite as planned.

(Source: Seven Seas Entertainment)', '2026-10-11T08:48:46.393Z', '2026-10-11T08:48:46.393Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('391ba3f2-3d2f-4a96-92b9-58401830ba34', 208609, 'Hone Dragon no Mana Musume', 'Hone Dragon no Mana Musume', '骨ドラゴンのマナ娘', 'https://cdn.kurzagin.com/anime/covers/208609.avif', NULL, 'TV', 'planning', 0, NULL, NULL, '["Adventure","Fantasy"]', 'Doga Kobo', NULL, 'In the Forest of Scraps, a place where all manner of things are discarded, an old dragon sleeps away his final days—that is, until an abandoned child suddenly appears before him. The tiny human is Eve, and despite being only five years of age, she has somehow endured the many dangers that surround them. In an act of pity, the dragon decides to raise her as his own...but his time is still running out.

After five years together, he takes his last breath, leaving his precious daughter on her own. Little does the dragon know, Eve is capable of more than he realizes, and their reunion may be sooner than he thinks…

(Source: J-Novel Club)', '2026-10-16T03:41:20.903Z', '2026-10-16T03:41:20.903Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('6c0d1846-b03f-498f-8672-5e0122c803a9', 206949, 'Nia Liston: The Merciless Maiden', 'Kyouran Reijou Nia Liston', '凶乱令嬢ニア・リストン', 'https://cdn.kurzagin.com/anime/covers/206949.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/206949-c5hfhixdgvy5.jpg', 'TV', 'planning', 0, 25, NULL, '["Action","Fantasy"]', 'KONAMI animation', 2026, 'A great hero lies undefeated on her deathbed, regretting that she never found a foe who could take her down. She never intended to meet her fate anywhere other than on the battlefield, and her peaceful demise has her wishing desperately that things could have been different... But when she suddenly comes to in the body of the young, frail Nia Liston, she’s got an all-new fight ahead of her. Nia is a sickly child, meaning she has a long way to go before she’s in fighting form. Now that she’s been given a second shot at life, however, she’s determined to get what she wants. She’s going to live—and die—for battle this time! Make way for the Merciless Maiden!

(Source: J-Novel Club)', '2026-10-19T23:30:41.227Z', '2026-10-19T23:30:41.227Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('85772be4-5e88-4719-8590-6984602f9ce6', 20994, 'Gate', 'GATE: Jieitai Kanochi nite, Kaku Tatakaeri', 'GATE 自衛隊 彼の地にて、斯く戦えり', 'https://cdn.kurzagin.com/anime/covers/20994.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/20994-9Vy4mDOFYT7O.jpg', 'TV', 'completed', 12, 12, 10, '["Action","Adventure","Fantasy"]', 'A-1 Pictures', 2015, 'The military fantasy series begins when a gate appears in Tokyo''s Ginza district sometime in the 21st century. From the gate pours out monsters, knights from middle-age Europe, and other fantasy-like beings, and they kill many of the citizens of Tokyo. This event is known as the Ginza Incident.

The government sends a small group of soldiers from the Japanese Self-Defense Forces (a replacement for Japan''s military) to the alternate world beyond the gate. Led by otaku soldier Youji, they find that the villages in the world are being attacked by a dragon. An elf girl who is a survivor from the dragon''s rampage joins the group in their travels across the dangerous new world.

(Source: Anime News Network)', '2026-10-20T12:49:10.477Z', '2026-10-20T12:49:10.477Z');
INSERT OR REPLACE INTO anime_watchlist (id, anilist_id, title, romaji_title, native_title, cover_url, banner_url, format, status, current_episode, total_episodes, score, genres, studio, season_year, summary, created_at, updated_at) VALUES ('5084a470-ff56-4e1c-9902-be0041189b48', 21364, 'Gate 2', 'GATE: Jieitai Kanochi nite, Kaku Tatakaeri Part 2', 'GATE 自衛隊 彼の地にて、斯く戦えり 第2クール', 'https://cdn.kurzagin.com/anime/covers/21364.avif', 'https://s4.anilist.co/file/anilistcdn/media/anime/banner/21364-e2myFtThuuVC.jpg', 'TV', 'completed', 12, 12, 10, '["Action","Adventure","Fantasy"]', 'A-1 Pictures', 2016, 'Several months have passed since the infamous Ginza Incident, with tensions between the Empire and JSDF escalating in the vast and mysterious "Special Region" over peace negotiations. The greed and curiosity of the global powers have also begun to grow, as reports about the technological limitations of the magical realm''s archaic civilizations come to light.

Meanwhile, Lieutenant Youji Itami and his merry band of female admirers struggle to navigate the complex political intrigue that plagues the Empire''s court. Despite her best efforts, Princess Piña Co Lada faces difficulties attempting to convince her father that the JSDF has no intention of conquering their kingdom. Pressured from both sides of the Gate, Itami must consider even more drastic measures to fulfill his mission.', '2026-10-20T12:49:28.512Z', '2026-10-20T12:49:28.512Z');

